class FILETIME(ctypes.Structure):
    _fields_ = [("dwLowDateTime", ctypes.c_uint32), ("dwHighDateTime", ctypes.c_uint32)]


class MEMORYSTATUSEX(ctypes.Structure):
    _fields_ = [
        ("dwLength", ctypes.c_uint32),
        ("dwMemoryLoad", ctypes.c_uint32),
        ("ullTotalPhys", ctypes.c_uint64),
        ("ullAvailPhys", ctypes.c_uint64),
        ("ullTotalPageFile", ctypes.c_uint64),
        ("ullAvailPageFile", ctypes.c_uint64),
        ("ullTotalVirtual", ctypes.c_uint64),
        ("ullAvailVirtual", ctypes.c_uint64),
        ("ullAvailExtendedVirtual", ctypes.c_uint64),
    ]


def _ft_value(ft: FILETIME) -> int:
    return (int(ft.dwHighDateTime) << 32) | int(ft.dwLowDateTime)


def is_admin() -> bool:
    try:
        return bool(ctypes.windll.shell32.IsUserAnAdmin())
    except Exception:
        return False


def ensure_admin() -> None:
    if is_admin():
        return
    if getattr(sys, "frozen", False):
        executable = sys.executable
        params = subprocess.list2cmdline(sys.argv[1:])
    else:
        executable = sys.executable
        params = subprocess.list2cmdline([str(Path(__file__).resolve()), *sys.argv[1:]])
    result = ctypes.windll.shell32.ShellExecuteW(None, "runas", executable, params, str(APP_DIR), 1)
    if result <= 32:
        raise RuntimeError(f"Yönetici izni alınamadı. Windows hata kodu: {result}")
    raise SystemExit(0)


def acquire_single_instance() -> bool:
    global _MUTEX_HANDLE
    try:
        _MUTEX_HANDLE = ctypes.windll.kernel32.CreateMutexW(None, False, "T_BOOSTER_SINGLE_INSTANCE")
        return bool(_MUTEX_HANDLE) and ctypes.windll.kernel32.GetLastError() != 183
    except Exception:
        return True


def run_text_command(args: list[str], timeout: int = 8) -> str:
    try:
        flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
        result = subprocess.run(args, capture_output=True, text=True, timeout=timeout, creationflags=flags, errors="ignore")
        return (result.stdout or "").strip()
    except Exception:
        return ""


def set_roblox_framerate_cap(cap: int = 9999, settings_path: str | Path | None = None) -> dict:
    """Safely update Roblox GlobalBasicSettings_13.xml and keep a timestamped backup."""
    try:
        cap = int(cap)
    except (TypeError, ValueError):
        raise ValueError("FPS sınırı geçerli bir sayı olmalı.")
    if not 1 <= cap <= 999999:
        raise ValueError("FPS sınırı 1 ile 999999 arasında olmalı.")

    local_appdata = os.environ.get("LOCALAPPDATA", "").strip()
    target = Path(settings_path) if settings_path else Path(local_appdata) / "Roblox" / "GlobalBasicSettings_13.xml"
    if not target.exists():
        raise FileNotFoundError(
            "GlobalBasicSettings_13.xml bulunamadı. Roblox'u aç, Ayarlar > Maksimum Kare Hızı bölümünü "
            "önce 60 FPS yap, Roblox'u tamamen kapat ve düğmeye tekrar bas."
        )

    raw = target.read_bytes()
    encoding = "utf-8"
    if raw.startswith(b"\xff\xfe") or raw.startswith(b"\xfe\xff"):
        encoding = "utf-16"
    elif raw.startswith(b"\xef\xbb\xbf"):
        encoding = "utf-8-sig"

    try:
        content = raw.decode(encoding)
    except UnicodeDecodeError:
        decoded = None
        for candidate in ("utf-8-sig", "utf-16", "cp1254", "latin-1"):
            try:
                decoded = raw.decode(candidate)
                encoding = candidate
                break
            except UnicodeDecodeError:
                continue
        if decoded is None:
            raise RuntimeError("Roblox ayar dosyasının metin kodlaması okunamadı.")
        content = decoded

    pattern = re.compile(
        r'(<(?:int|int64)\b[^>]*\bname\s*=\s*["\']FramerateCap["\'][^>]*>)\s*(-?\d+)\s*(</(?:int|int64)>)',
        re.IGNORECASE,
    )
    match = pattern.search(content)
    if not match:
        raise RuntimeError(
            "FramerateCap satırı bulunamadı. Roblox'u açıp FPS ayarını önce 60 yap, oyunu tamamen kapat ve tekrar dene."
        )

    old_cap = int(match.group(2))
    updated = pattern.sub(lambda m: f"{m.group(1)}{cap}{m.group(3)}", content, count=1)

    timestamp = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    backup = target.with_name(f"{target.stem}.TB_BACKUP_{timestamp}{target.suffix}")
    shutil.copy2(target, backup)

    temp_path = target.with_name(f"{target.name}.tb_tmp")
    try:
        temp_path.write_bytes(updated.encode(encoding))
        os.replace(temp_path, target)
    finally:
        try:
            if temp_path.exists():
                temp_path.unlink()
        except Exception:
            pass

    verification = target.read_bytes().decode(encoding, errors="strict")
    verify_match = pattern.search(verification)
    if not verify_match or int(verify_match.group(2)) != cap:
        try:
            shutil.copy2(backup, target)
        except Exception:
            pass
        raise RuntimeError("FPS değeri doğrulanamadığı için eski Roblox ayarı geri yüklendi.")

    return {
        "path": str(target),
        "backup": str(backup),
        "old_cap": old_cap,
        "new_cap": cap,
        "changed": old_cap != cap,
    }


def _read_windows_system_times():
    try:
        idle = FILETIME()
        kernel = FILETIME()
        user = FILETIME()
        ok = ctypes.windll.kernel32.GetSystemTimes(
            ctypes.byref(idle),
            ctypes.byref(kernel),
            ctypes.byref(user),
        )
        if not ok:
            return None
        return (_ft_value(idle), _ft_value(kernel), _ft_value(user))
    except Exception:
        return None


def _cpu_usage_windows_api(sample_seconds: float = 0.18):
    # İlk çağrıda bile gerçek örnek üretmek için iki Windows API ölçümü alır.
    with _CPU_SAMPLE_LOCK:
        first = _read_windows_system_times()
        if first is None:
            return None
        time.sleep(max(0.08, float(sample_seconds)))
        second = _read_windows_system_times()
        if second is None:
            return None

    idle_delta = second[0] - first[0]
    kernel_delta = second[1] - first[1]
    user_delta = second[2] - first[2]
    total_delta = kernel_delta + user_delta
    if total_delta <= 0 or idle_delta < 0:
        return None
    busy_delta = max(0, total_delta - idle_delta)
    return max(0.0, min(100.0, busy_delta * 100.0 / total_delta))


def _cpu_usage_windows_counter():
    script = r'''
$ErrorActionPreference = 'SilentlyContinue'
$value = Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor |
    Where-Object { $_.Name -eq '_Total' } |
    Select-Object -First 1 -ExpandProperty PercentProcessorTime
if ($null -ne $value) {
    [Console]::WriteLine(
        ([double]$value).ToString(
            '0.0',
            [Globalization.CultureInfo]::InvariantCulture
        )
    )
}
'''
    output = run_text_command(
        [
            'powershell.exe', '-NoLogo', '-NoProfile', '-NonInteractive',
            '-ExecutionPolicy', 'Bypass', '-Command', script,
        ],
        timeout=5,
    )
    try:
        return max(0.0, min(100.0, float(output.splitlines()[-1].strip())))
    except Exception:
        return None


def cpu_usage_percent() -> float:
    api_value = _cpu_usage_windows_api()
    if api_value is not None:
        return api_value

    if psutil:
        try:
            value = float(psutil.cpu_percent(interval=0.18))
            return max(0.0, min(100.0, value))
        except Exception:
            pass

    counter_value = _cpu_usage_windows_counter()
    if counter_value is not None:
        return counter_value
    return 0.0


def memory_info() -> dict:
    if psutil:
        try:
            mem = psutil.virtual_memory()
            return {
                "percent": float(mem.percent),
                "total_gb": mem.total / (1024 ** 3),
                "used_gb": mem.used / (1024 ** 3),
                "free_gb": mem.available / (1024 ** 3),
            }
        except Exception:
            pass
    status = MEMORYSTATUSEX()
    status.dwLength = ctypes.sizeof(MEMORYSTATUSEX)
    try:
        ok = ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(status))
        if ok:
            total = int(status.ullTotalPhys)
            free = int(status.ullAvailPhys)
            used = max(0, total - free)
            return {
                "percent": float(status.dwMemoryLoad),
                "total_gb": total / (1024 ** 3),
                "used_gb": used / (1024 ** 3),
                "free_gb": free / (1024 ** 3),
            }
    except Exception:
        pass
    return {"percent": 0.0, "total_gb": 0.0, "used_gb": 0.0, "free_gb": 0.0}


def disk_info(path: str = "C:\\") -> dict:
    try:
        total, used, free = shutil.disk_usage(path)
        return {
            "percent": (used / total * 100.0) if total else 0.0,
            "total_gb": total / (1024 ** 3),
            "used_gb": used / (1024 ** 3),
            "free_gb": free / (1024 ** 3),
        }
    except Exception:
        return {"percent": 0.0, "total_gb": 0.0, "used_gb": 0.0, "free_gb": 0.0}


def cpu_temp_c():
    if psutil:
        try:
            all_temps = psutil.sensors_temperatures()
            for entries in all_temps.values():
                for entry in entries:
                    current = getattr(entry, "current", None)
                    if current is not None and 0 < float(current) < 150:
                        return float(current)
        except Exception:
            pass
    output = run_text_command([
        "wmic", "/namespace:\\\\root\\wmi", "PATH", "MSAcpi_ThermalZoneTemperature",
        "get", "CurrentTemperature", "/value",
    ])
    for raw in re.findall(r"CurrentTemperature=(\d+)", output):
        value = int(raw) / 10.0 - 273.15
        if 0 < value < 150:
            return value
    return None


def _friendly_gpu_engine_name(name: str | None) -> str | None:
    if not name:
        return None

    clean = str(name).strip().replace("_", " ")
    replacements = {
        "VideoEncode": "Video Encode",
        "VideoDecode": "Video Decode",
        "VideoProcessing": "Video Processing",
        "Compute 0": "Compute",
        "Compute 1": "Compute",
    }
    for source, target in replacements.items():
        clean = clean.replace(source, target)

    clean = re.sub(r"(?i)video\s*encode", "Video Encode", clean)
    clean = re.sub(r"(?i)video\s*decode", "Video Decode", clean)
    clean = re.sub(r"(?i)video\s*processing", "Video Processing", clean)
    clean = re.sub(r"\s+", " ", clean).strip()
    return clean or None


def windows_gpu_engine_usage() -> tuple[float | None, str | None]:
    # Task Manager'a yakın GPU yüzdesi için işlem başına sayaçları
    # fiziksel GPU ve motor türüne göre toplar, en yoğun motoru döndürür.
    script = r'''
$ErrorActionPreference = 'SilentlyContinue'
$rows = Get-CimInstance `
    -Namespace root\cimv2 `
    -ClassName Win32_PerfFormattedData_GPUPerformanceCounters_GPUEngine

$totals = @{}
foreach ($row in $rows) {
    $name = [string]$row.Name
    $value = [double]$row.UtilizationPercentage
    if ($value -lt 0) { continue }

    $engine = $null
    $key = $null
    if ($name -match 'luid_(.+?)_phys_(\d+)_eng_\d+_engtype_(.+)$') {
        $engine = $Matches[3]
        $key = "$($Matches[1])|$($Matches[2])|$engine"
    }
    elseif ($name -match 'engtype_(.+)$') {
        $engine = $Matches[1]
        $key = $engine
    }

    if ([string]::IsNullOrWhiteSpace($key)) { continue }
    if (-not $totals.ContainsKey($key)) { $totals[$key] = 0.0 }
    $totals[$key] = [double]$totals[$key] + $value
}

$bestValue = -1.0
$bestName = ''
foreach ($key in $totals.Keys) {
    $value = [Math]::Min(100.0, [double]$totals[$key])
    if ($value -gt $bestValue) {
        $bestValue = $value
        $bestName = [string]$key
    }
}

if ($bestValue -ge 0) {
    $engine = ($bestName -split '\|')[-1]
    $number = $bestValue.ToString('0.0', [Globalization.CultureInfo]::InvariantCulture)
    [Console]::WriteLine($number + '|' + $engine)
}
'''

    output = run_text_command(
        [
            "powershell.exe",
            "-NoLogo",
            "-NoProfile",
            "-NonInteractive",
            "-ExecutionPolicy",
            "Bypass",
            "-Command",
            script,
        ],
        timeout=5,
    )
    if not output:
        return None, None

    line = output.splitlines()[-1].strip()
    if "|" not in line:
        return None, None

    raw_percent, raw_engine = line.split("|", 1)
    try:
        percent = max(0.0, min(100.0, float(raw_percent.strip())))
    except (TypeError, ValueError):
        return None, None

    return percent, _friendly_gpu_engine_name(raw_engine)


def gpu_info() -> dict:
    engine_percent, engine_name = windows_gpu_engine_usage()

    nv_percent = None
    temp = None
    vram_used = None
    vram_total = None
    gpu_name = None

    output = run_text_command([
        "nvidia-smi",
        "--query-gpu=utilization.gpu,temperature.gpu,memory.used,memory.total,name",
        "--format=csv,noheader,nounits",
    ])
    if output:
        line = output.splitlines()[0]
        parts = [item.strip() for item in line.split(",")]
        if len(parts) >= 5:
            try:
                nv_percent = float(parts[0])
            except (TypeError, ValueError):
                nv_percent = None
            try:
                temp = float(parts[1])
            except (TypeError, ValueError):
                temp = None
            try:
                vram_used = float(parts[2])
                vram_total = float(parts[3])
            except (TypeError, ValueError):
                vram_used = None
                vram_total = None
            gpu_name = parts[4] or None

    percent = engine_percent if engine_percent is not None else nv_percent
    source = "Windows GPU Engine" if engine_percent is not None else (
        "nvidia-smi" if nv_percent is not None else None
    )
    return {
        "percent": percent,
        "engine": engine_name,
        "source": source,
        "nvidia_percent": nv_percent,
        "temp": temp,
        "vram_used": vram_used,
        "vram_total": vram_total,
        "name": gpu_name,
    }


def collect_metrics() -> dict:
    return {
        "cpu": {"percent": cpu_usage_percent(), "temp": cpu_temp_c()},
        "ram": memory_info(),
        "disk": disk_info(),
        "gpu": gpu_info(),
    }


def memory_profile_info() -> dict:
    script = r'''
$ErrorActionPreference = 'SilentlyContinue'
$memory = @(Get-CimInstance Win32_PhysicalMemory | Select-Object DeviceLocator, BankLabel, Manufacturer, PartNumber, Speed, ConfiguredClockSpeed, Capacity)
$board = Get-CimInstance Win32_BaseBoard | Select-Object Manufacturer, Product
$bios = Get-CimInstance Win32_BIOS | Select-Object SMBIOSBIOSVersion
[PSCustomObject]@{ Memory = $memory; Board = $board; BIOS = $bios } | ConvertTo-Json -Depth 5 -Compress
'''
    output = run_text_command([
        "powershell.exe", "-NoLogo", "-NoProfile", "-NonInteractive",
        "-ExecutionPolicy", "Bypass", "-Command", script,
    ], timeout=12)
    if not output:
        return {"ok": False, "error": "RAM ve anakart bilgileri Windows tarafından okunamadı."}
    try:
        raw = json.loads(output)
    except Exception as exc:
        return {"ok": False, "error": f"RAM bilgileri çözümlenemedi: {exc}"}

    memory = raw.get("Memory") or []
    if isinstance(memory, dict):
        memory = [memory]
    modules, part_numbers, manufacturers = [], set(), set()
    configured_speeds, rated_speeds = set(), set()
    total_bytes = 0
    for index, item in enumerate(memory, start=1):
        manufacturer = str(item.get("Manufacturer") or "Bilinmiyor").strip()
        part_number = str(item.get("PartNumber") or "Bilinmiyor").strip()
        locator = str(item.get("DeviceLocator") or item.get("BankLabel") or f"Modül {index}").strip()
        try: capacity = int(item.get("Capacity") or 0)
        except Exception: capacity = 0
        try: speed = int(item.get("Speed") or 0)
        except Exception: speed = 0
        try: configured = int(item.get("ConfiguredClockSpeed") or speed or 0)
        except Exception: configured = speed
        total_bytes += capacity
        if manufacturer != "Bilinmiyor": manufacturers.add(manufacturer.casefold())
        if part_number != "Bilinmiyor": part_numbers.add(part_number.casefold())
        if configured: configured_speeds.add(configured)
        if speed: rated_speeds.add(speed)
        modules.append({
            "locator": locator, "manufacturer": manufacturer, "part_number": part_number,
            "capacity_gb": capacity/(1024**3) if capacity else 0,
            "configured_mhz": configured, "rated_mhz": speed,
        })
    board = raw.get("Board") or {}
    bios = raw.get("BIOS") or {}
    board_text = " ".join(p for p in (str(board.get("Manufacturer") or "").strip(), str(board.get("Product") or "").strip()) if p) or "Anakart bilgisi okunamadı"
    bios_text = str(bios.get("SMBIOSBIOSVersion") or "Okunamadı").strip()
    mixed = len(part_numbers)>1 or len(manufacturers)>1 or len(configured_speeds)>1 or len(rated_speeds)>1
    configured_max = max(configured_speeds) if configured_speeds else 0
    rated_max = max(rated_speeds) if rated_speeds else 0
    if mixed:
        profile_hint = "Karışık RAM algılandı. D.O.C.P./XMP açılırsa doğrudan en yüksek frekans yerine 3000–3200 MHz gibi daha temkinli bir değerle stabilite testi yapılmalı."
    elif configured_max >= 3000:
        profile_hint = f"RAM şu anda {configured_max} MHz civarında çalışıyor. Yüksek bellek profili etkin olabilir; kesin durum BIOS'tan doğrulanır."
    elif rated_max and configured_max and rated_max > configured_max:
        profile_hint = f"Modül {rated_max} MHz bildiriyor ancak sistem {configured_max} MHz kullanıyor. D.O.C.P./XMP kapalı veya hız elle düşürülmüş olabilir."
    else:
        profile_hint = "Windows, D.O.C.P./XMP anahtarının açık olup olmadığını kesin olarak bildirmez. Durum BIOS içinden doğrulanmalıdır."
    module_lines = [
        f"{m['locator']} • {m['capacity_gb']:.0f} GB • {m['configured_mhz'] or '—'} MHz aktif • {m['rated_mhz'] or '—'} MHz bildirilen • {m['manufacturer']} • {m['part_number']}"
        for m in modules
    ]
    return {
        "ok": True, "board": board_text, "bios": bios_text, "module_count": len(modules),
        "total_gb": total_bytes/(1024**3) if total_bytes else 0,
        "configured_mhz": configured_max, "rated_mhz": rated_max, "mixed": mixed,
        "profile_hint": profile_hint, "modules_text": "\n".join(module_lines) or "RAM modülü bulunamadı.",
    }



