def _extract_pci_subsys_vendor(pnp_device_id: str) -> str:
    value = str(pnp_device_id or "")
    match = re.search(r"SUBSYS_[0-9A-Fa-f]{4}([0-9A-Fa-f]{4})", value)
    if not match:
        return ""
    return GPU_SUBSYS_VENDOR_MAP.get(match.group(1).upper(), "")


def _normalise_vendor(value: str) -> str:
    value = (value or "").strip().casefold()
    if "nvidia" in value:
        return "nvidia"
    if "advanced micro devices" in value or "amd" in value or "radeon" in value:
        return "amd"
    if "intel" in value:
        return "intel"
    if "asustek" in value or "asus" in value:
        return "asus"
    if "micro-star" in value or value == "msi" or " msi " in f" {value} ":
        return "msi"
    if "gigabyte" in value:
        return "gigabyte"
    if "asrock" in value:
        return "asrock"
    if "biostar" in value:
        return "biostar"
    if "evga" in value:
        return "evga"
    if "dell" in value:
        return "dell"
    if "hewlett" in value or value.startswith("hp"):
        return "hp"
    if "lenovo" in value:
        return "lenovo"
    if "acer" in value:
        return "acer"
    return "unknown"


def driver_hardware_info() -> dict:
    script = r"""
$ErrorActionPreference = 'SilentlyContinue'
$gpus = @(Get-CimInstance Win32_VideoController | Select-Object Name, AdapterCompatibility, PNPDeviceID)
$board = Get-CimInstance Win32_BaseBoard | Select-Object Manufacturer, Product, Version, SerialNumber
[PSCustomObject]@{ GPUs = $gpus; Board = $board } | ConvertTo-Json -Depth 5 -Compress
"""
    output = run_text_command([
        "powershell.exe", "-NoLogo", "-NoProfile", "-NonInteractive",
        "-ExecutionPolicy", "Bypass", "-Command", script,
    ], timeout=14)
    if not output:
        return {"ok": False, "error": "Ekran kartı ve anakart bilgileri Windows tarafından okunamadı."}
    try:
        raw = json.loads(output)
    except Exception as exc:
        return {"ok": False, "error": f"Donanım bilgileri çözümlenemedi: {exc}"}

    gpu_rows = raw.get("GPUs") or []
    if isinstance(gpu_rows, dict):
        gpu_rows = [gpu_rows]
    gpu_names, gpu_vendors, gpu_descriptions = [], [], []
    for item in gpu_rows:
        name = str(item.get("Name") or "").strip()
        compatibility = str(item.get("AdapterCompatibility") or "").strip()
        pnp_id = str(item.get("PNPDeviceID") or "").strip()
        if name:
            gpu_names.append(name)
        vendor = _normalise_vendor(f"{compatibility} {name} {pnp_id}")
        if vendor == "unknown":
            upper_pnp = pnp_id.upper()
            if "VEN_10DE" in upper_pnp:
                vendor = "nvidia"
            elif "VEN_8086" in upper_pnp:
                vendor = "intel"
            elif "VEN_1002" in upper_pnp or "VEN_1022" in upper_pnp:
                vendor = "amd"
        partner = _extract_pci_subsys_vendor(pnp_id)
        if vendor in GPU_DRIVER_URLS and vendor not in gpu_vendors:
            gpu_vendors.append(vendor)
        desc = name or "Bilinmeyen GPU"
        if partner and partner.casefold() not in desc.casefold():
            desc = f"{partner} {desc}"
        elif compatibility and compatibility.casefold() not in desc.casefold():
            desc = f"{compatibility} {desc}"
        gpu_descriptions.append(desc)

    board = raw.get("Board") or {}
    manufacturer = str(board.get("Manufacturer") or "Bilinmiyor").strip()
    model = str(board.get("Product") or "Bilinmiyor").strip()
    version = str(board.get("Version") or "").strip()
    return {
        "ok": True,
        "gpu_names": gpu_names,
        "gpu_vendors": gpu_vendors,
        "gpu_descriptions": gpu_descriptions,
        "board_manufacturer": manufacturer,
        "board_model": model,
        "board_version": version,
        "board_vendor": _normalise_vendor(manufacturer),
    }


def motherboard_support_url(data: dict) -> str | None:
    """Return only the official support page for the detected board vendor."""
    return MOTHERBOARD_SUPPORT_URLS.get(str(data.get("board_vendor") or "unknown"))


def _complete_hardware_fallback(base: dict | None = None) -> dict:
    base = dict(base or {})
    ram_value = base.get("RAM", 0)
    module_value = base.get("Modules", 0)
    return {
        "Build": str(base.get("Build") or "?"),
        "WindowsCaption": str(base.get("WindowsCaption") or "Windows"),
        "CPU": str(base.get("CPU") or "Okunamadı"),
        "GPU": str(base.get("GPU") or "Okunamadı"),
        "GPUVendors": list(base.get("GPUVendors") or []),
        "RAM": ram_value,
        "Modules": module_value,
        "RAMText": str(base.get("RAMText") or f"{ram_value} GB • {module_value} modül"),
        "RAMModulesText": str(base.get("RAMModulesText") or "RAM modül ayrıntısı okunamadı"),
        "Board": str(base.get("Board") or "Okunamadı"),
        "DiskText": str(base.get("DiskText") or "Disk bilgisi okunamadı"),
        "DisksDetailed": list(base.get("DisksDetailed") or []),
        "DiskProbeComplete": bool(base.get("DiskProbeComplete", False)),
    }


def _u128_le(data: bytes, offset: int) -> int:
    chunk = data[offset:offset + 16]
    if len(chunk) != 16:
        return 0
    return int.from_bytes(chunk, "little", signed=False)


def _parse_nvme_health_bytes(log: bytes) -> dict | None:
    if not isinstance(log, (bytes, bytearray)) or len(log) < 512:
        return None
    critical_warning = int(log[0])
    kelvin = int.from_bytes(log[1:3], "little", signed=False)
    temperature = round(kelvin - 273.15) if 200 <= kelvin <= 500 else None
    available_spare = int(log[3])
    spare_threshold = int(log[4])
    percentage_used = int(log[5])
    remaining = max(0, 100 - min(percentage_used, 100))
    data_units_read = _u128_le(log, 32)
    data_units_written = _u128_le(log, 48)
    controller_busy_minutes = _u128_le(log, 96)
    power_cycles = _u128_le(log, 112)
    power_on_hours = _u128_le(log, 128)
    unsafe_shutdowns = _u128_le(log, 144)
    media_errors = _u128_le(log, 160)
    error_log_entries = _u128_le(log, 176)

    if critical_warning & 0b00001100:
        health_status = "Sorunlu"
    elif critical_warning or remaining <= 10 or available_spare < spare_threshold:
        health_status = "Uyarı"
    else:
        health_status = "Sağlıklı"

    return {
        "health_percent": remaining,
        "health_status": health_status,
        "health_source": "NVMe SMART / Percentage Used",
        "percentage_used": percentage_used,
        "wear_percent": percentage_used,
        "temperature": temperature,
        "available_spare": available_spare,
        "spare_threshold": spare_threshold,
        "critical_warning": critical_warning,
        "data_read_tb": round(data_units_read * 512000 / 1_000_000_000_000, 2),
        "data_written_tb": round(data_units_written * 512000 / 1_000_000_000_000, 2),
        "controller_busy_minutes": controller_busy_minutes,
        "power_cycles": power_cycles,
        "power_on_hours": power_on_hours,
        "unsafe_shutdowns": unsafe_shutdowns,
        "media_errors": media_errors,
        "error_log_entries": error_log_entries,
    }


def read_nvme_health_log(physical_drive_index: int) -> dict | None:
    """Read the standard NVMe SMART/Health log using the Windows storage API."""
    if os.name != "nt":
        return None

    IOCTL_STORAGE_QUERY_PROPERTY = 0x002D1400
    STORAGE_DEVICE_PROTOCOL_SPECIFIC_PROPERTY = 50
    PROPERTY_STANDARD_QUERY = 0
    PROTOCOL_TYPE_NVME = 3
    NVME_DATA_TYPE_LOG_PAGE = 2
    NVME_LOG_PAGE_HEALTH_INFO = 2
    PROTOCOL_DATA_SIZE = 40
    QUERY_HEADER_SIZE = 8
    LOG_SIZE = 512
    BUFFER_SIZE = QUERY_HEADER_SIZE + PROTOCOL_DATA_SIZE + LOG_SIZE

    GENERIC_READ = 0x80000000
    GENERIC_WRITE = 0x40000000
    FILE_SHARE_READ = 0x00000001
    FILE_SHARE_WRITE = 0x00000002
    OPEN_EXISTING = 3
    FILE_ATTRIBUTE_NORMAL = 0x00000080
    INVALID_HANDLE_VALUE = ctypes.c_void_p(-1).value

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    create_file = kernel32.CreateFileW
    create_file.argtypes = [
        wintypes.LPCWSTR, wintypes.DWORD, wintypes.DWORD, ctypes.c_void_p,
        wintypes.DWORD, wintypes.DWORD, wintypes.HANDLE,
    ]
    create_file.restype = wintypes.HANDLE
    device_io = kernel32.DeviceIoControl
    device_io.argtypes = [
        wintypes.HANDLE, wintypes.DWORD, ctypes.c_void_p, wintypes.DWORD,
        ctypes.c_void_p, wintypes.DWORD, ctypes.POINTER(wintypes.DWORD), ctypes.c_void_p,
    ]
    device_io.restype = wintypes.BOOL
    close_handle = kernel32.CloseHandle
    close_handle.argtypes = [wintypes.HANDLE]
    close_handle.restype = wintypes.BOOL

    device_path = rf"\\.\PhysicalDrive{int(physical_drive_index)}"
    handle = None
    for access in (GENERIC_READ | GENERIC_WRITE, GENERIC_READ, 0):
        candidate = create_file(
            device_path,
            access,
            FILE_SHARE_READ | FILE_SHARE_WRITE,
            None,
            OPEN_EXISTING,
            FILE_ATTRIBUTE_NORMAL,
            None,
        )
        candidate_value = ctypes.cast(candidate, ctypes.c_void_p).value
        if candidate_value not in (None, INVALID_HANDLE_VALUE):
            handle = candidate
            break
    if handle is None:
        return None

    try:
        buffer = ctypes.create_string_buffer(BUFFER_SIZE)
        # STORAGE_PROPERTY_QUERY
        struct.pack_into("<II", buffer, 0, STORAGE_DEVICE_PROTOCOL_SPECIFIC_PROPERTY, PROPERTY_STANDARD_QUERY)
        # STORAGE_PROTOCOL_SPECIFIC_DATA (10 ULONG fields)
        struct.pack_into(
            "<10I",
            buffer,
            QUERY_HEADER_SIZE,
            PROTOCOL_TYPE_NVME,
            NVME_DATA_TYPE_LOG_PAGE,
            NVME_LOG_PAGE_HEALTH_INFO,
            0,
            PROTOCOL_DATA_SIZE,
            LOG_SIZE,
            0,
            0,
            0,
            0,
        )
        returned = wintypes.DWORD(0)
        ok = device_io(
            handle,
            IOCTL_STORAGE_QUERY_PROPERTY,
            buffer,
            BUFFER_SIZE,
            buffer,
            BUFFER_SIZE,
            ctypes.byref(returned),
            None,
        )
        if not ok or returned.value < QUERY_HEADER_SIZE + PROTOCOL_DATA_SIZE:
            return None

        raw = bytes(buffer[:min(BUFFER_SIZE, returned.value or BUFFER_SIZE)])
        try:
            version, descriptor_size = struct.unpack_from("<II", raw, 0)
            protocol_values = struct.unpack_from("<10I", raw, QUERY_HEADER_SIZE)
        except struct.error:
            return None
        if version < 40 or descriptor_size < 40:
            return None
        protocol_type, data_type = protocol_values[0], protocol_values[1]
        data_offset, data_length = protocol_values[4], protocol_values[5]
        if protocol_type != PROTOCOL_TYPE_NVME or data_type != NVME_DATA_TYPE_LOG_PAGE:
            return None
        if data_offset < PROTOCOL_DATA_SIZE or data_length < LOG_SIZE:
            return None
        data_start = QUERY_HEADER_SIZE + data_offset
        if data_start + LOG_SIZE > len(raw):
            return None
        log = raw[data_start:data_start + LOG_SIZE]

        return _parse_nvme_health_bytes(log)
    except Exception as exc:
        core.log_line(f"NVMe SMART sorgusu başarısız (Disk {physical_drive_index}): {exc}")
        return None
    finally:
        try:
            close_handle(handle)
        except Exception:
            pass


def _smart_raw_value(raw_bytes) -> int:
    try:
        values = bytes(int(value) & 0xFF for value in raw_bytes)
    except Exception:
        return 0
    return int.from_bytes(values[:6].ljust(6, b"\x00"), "little", signed=False)


def _parse_ata_smart_attributes(vendor_specific) -> dict[int, dict]:
    try:
        data = bytes(int(value) & 0xFF for value in (vendor_specific or []))
    except Exception:
        return {}
    attributes = {}
    if len(data) < 14:
        return attributes
    for offset in range(2, min(len(data), 362), 12):
        attr_id = data[offset]
        if attr_id in (0, 0xFF) or offset + 12 > len(data):
            continue
        raw_bytes = list(data[offset + 5:offset + 11])
        attributes[attr_id] = {
            "id": attr_id,
            "flags": int.from_bytes(data[offset + 1:offset + 3], "little"),
            "current": int(data[offset + 3]),
            "worst": int(data[offset + 4]),
            "raw_bytes": raw_bytes,
            "raw": _smart_raw_value(raw_bytes),
        }
    return attributes


def _normalize_disk_interface(interface: str, model: str = "", media_type: str = "") -> str:
    raw = str(interface or "").strip()
    upper = raw.upper()
    combo = f"{raw} {model or ''} {media_type or ''}".upper()
    if "NVME" in combo or "NVM EXPRESS" in combo:
        return "NVMe"
    if any(token in combo for token in ("SATA", "SERIAL ATA", "AHCI")):
        return "SATA"
    if upper == "ATA":
        return "SATA"
    if "USB" in combo:
        return "USB"
    if "SAS" in combo:
        return "SAS"
    if "SCSI" in combo:
        return "SCSI"
    if "RAID" in combo:
        return "RAID"
    return raw or "Bilinmiyor"


def _looks_like_ssd(model: str, media_type: str, interface: str, attributes: dict[int, dict] | None = None) -> bool:
    haystack = f"{model or ''} {media_type or ''} {interface or ''}".casefold()
    if any(token in haystack for token in (
        "ssd", "solid state", "solid-state", "nvme", "m.2", "msata", "pcie", "2280"
    )):
        return True
    if any(token in haystack for token in ("hdd", "hard disk", "mechanical", "spinning")):
        return False
    attrs = attributes or {}
    ssd_life_attrs = {0xA9, 0xAD, 0xB1, 0xCA, 0xD1, 0xE7, 0xE8, 0xE9}
    if any(attr in attrs for attr in ssd_life_attrs):
        return True
    return _normalize_disk_interface(interface, model, media_type) == "NVMe"


def _ata_life_remaining(model: str, attributes: dict[int, dict], interface: str = "SATA") -> tuple[int | None, str]:
    """Read only vendor-defined SSD life fields; never invent a percentage."""
    model_upper = str(model or "").upper().strip()
    source_prefix = "SATA SMART" if _normalize_disk_interface(interface, model, "") == "SATA" else "ATA SMART"

    def current(attr_id: int):
        item = attributes.get(attr_id)
        value = item.get("current") if item else None
        return int(value) if isinstance(value, int) and 0 <= value <= 100 else None

    def raw_byte(attr_id: int, index: int = 0):
        item = attributes.get(attr_id)
        values = item.get("raw_bytes") if item else None
        if not values or index >= len(values):
            return None
        value = int(values[index])
        return value if 0 <= value <= 100 else None

    def normalized_remaining(attr_id: int, label: str):
        value = current(attr_id)
        if value is not None:
            return value, f"{source_prefix} {attr_id:02X} — {label}"
        return None

    def raw_remaining(attr_id: int, label: str):
        value = raw_byte(attr_id)
        if value is not None:
            return value, f"{source_prefix} {attr_id:02X} — {label}"
        return None

    # WD Green / WD Blue / SanDisk SATA SSD:
    # SMART 169 (0xA9) is Remaining Lifetime Percentage. 100 -> 0.
    # WDC WDS240G2G0A-00JH30 must be read from this field.
    is_wd_sandisk = (
        model_upper.startswith("WDC ")
        or model_upper.startswith("WD ")
        or "WESTERN DIGITAL" in model_upper
        or "SANDISK" in model_upper
        or "WDS" in model_upper
    )
    if is_wd_sandisk:
        result = normalized_remaining(0xA9, "Kalan ömür yüzdesi")
        if result:
            return result
        # A few SanDisk firmwares expose the same percentage in raw byte 0.
        result = raw_remaining(0xA9, "Kalan ömür yüzdesi")
        if result:
            return result
        return None, ""

    # Micron / Crucial: SMART 202 (0xCA) raw byte 0 is lifetime USED.
    if any(name in model_upper for name in ("MICRON", "CRUCIAL")):
        used = raw_byte(0xCA)
        if used is not None:
            return max(0, min(100, 100 - used)), f"{source_prefix} CA — Kullanılan ömür"
        return None, ""

    # Samsung SATA SSDs: SMART 177 (0xB1), normalized value is life remaining.
    if "SAMSUNG" in model_upper:
        result = normalized_remaining(0xB1, "Wear Leveling / kalan ömür")
        return result if result else (None, "")

    # Kingston SATA SSDs: SMART 231 (0xE7) is SSD Life Left.
    if "KINGSTON" in model_upper:
        result = raw_remaining(0xE7, "SSD Life Left")
        if result:
            return result
        result = normalized_remaining(0xE7, "SSD Life Left")
        return result if result else (None, "")

    # Intel SATA SSDs: SMART 233 (0xE9) Media Wearout Indicator.
    if "INTEL" in model_upper:
        result = normalized_remaining(0xE9, "Media Wearout Indicator")
        return result if result else (None, "")

    # Toshiba / Kioxia SATA SSDs commonly expose life left in 0xE7.
    if any(name in model_upper for name in ("KIOXIA", "TOSHIBA")):
        result = normalized_remaining(0xE7, "SSD Life Left")
        if result:
            return result
        result = raw_remaining(0xE7, "SSD Life Left")
        return result if result else (None, "")

    # Phison-based consumer SATA SSDs commonly use 0xE7 as SSD Life Left.
    if any(name in model_upper for name in (
        "ADATA", "TEAMGROUP", "TEAM ", "CORSAIR", "PNY", "SILICON POWER",
        "HIKSEMI", "HIKVISION", "PATRIOT", "GIGABYTE SSD"
    )):
        result = normalized_remaining(0xE7, "SSD Life Left")
        if result:
            return result
        result = raw_remaining(0xE7, "SSD Life Left")
        return result if result else (None, "")

    # OCZ / Indilinx commonly use 0xD1 for SSD life left.
    if any(name in model_upper for name in ("OCZ", "INDILINX")):
        result = normalized_remaining(0xD1, "SSD Life Left")
        return result if result else (None, "")

    # Unknown vendor: do not guess from E7/E8/E9/B1 because meanings differ.
    return None, ""


def rich_system_info(base: dict | None = None) -> dict:
    """Read detailed hardware and genuine SMART/NVMe health data."""
    fallback = _complete_hardware_fallback(base or core.hardware_info())
    script = r"""
$ErrorActionPreference = 'SilentlyContinue'
$os = Get-CimInstance Win32_OperatingSystem | Select-Object BuildNumber, Caption
$cpu = Get-CimInstance Win32_Processor | Select-Object -First 1 Name
$board = Get-CimInstance Win32_BaseBoard | Select-Object Manufacturer, Product, Version
$gpus = @(Get-CimInstance Win32_VideoController | Select-Object Name, AdapterCompatibility, PNPDeviceID)
$memory = @(Get-CimInstance Win32_PhysicalMemory | Select-Object Manufacturer, PartNumber, Capacity, ConfiguredClockSpeed, Speed)
$disks = @(Get-CimInstance Win32_DiskDrive | Select-Object Model, Size, InterfaceType, MediaType, Status, SerialNumber, Index, FirmwareRevision, Partitions, BytesPerSector, PNPDeviceID)
try {
    $storageDisks = @(Get-Disk | Select-Object Number, FriendlyName, SerialNumber, BusType, PartitionStyle, OperationalStatus, HealthStatus, Size, IsBoot, IsSystem, IsReadOnly, IsOffline)
} catch { $storageDisks = @() }
try {
    $physicalDisks = @(Get-PhysicalDisk | ForEach-Object {
        $pd = $_
        $rel = $null
        try { $rel = Get-StorageReliabilityCounter -PhysicalDisk $pd -ErrorAction SilentlyContinue } catch {}
        [PSCustomObject]@{
            FriendlyName = $pd.FriendlyName; Model = $pd.Model; SerialNumber = $pd.SerialNumber
            DeviceId = $pd.DeviceId; BusType = $pd.BusType; MediaType = $pd.MediaType
            HealthStatus = $pd.HealthStatus; OperationalStatus = ($pd.OperationalStatus -join ', '); Size = $pd.Size
            Wear = if ($rel) { $rel.Wear } else { $null }
            Temperature = if ($rel) { $rel.Temperature } else { $null }
            TemperatureMax = if ($rel) { $rel.TemperatureMax } else { $null }
            PowerOnHours = if ($rel) { $rel.PowerOnHours } else { $null }
            ReadErrorsTotal = if ($rel) { $rel.ReadErrorsTotal } else { $null }
            ReadErrorsUncorrected = if ($rel) { $rel.ReadErrorsUncorrected } else { $null }
            WriteErrorsTotal = if ($rel) { $rel.WriteErrorsTotal } else { $null }
            WriteErrorsUncorrected = if ($rel) { $rel.WriteErrorsUncorrected } else { $null }
        }
    })
} catch { $physicalDisks = @() }
try {
    $smartData = @(Get-CimInstance -Namespace root/wmi -ClassName MSStorageDriver_FailurePredictData | ForEach-Object {
        [PSCustomObject]@{ InstanceName = $_.InstanceName; VendorSpecific = @($_.VendorSpecific) }
    })
} catch { $smartData = @() }
try {
    $smartStatus = @(Get-CimInstance -Namespace root/wmi -ClassName MSStorageDriver_FailurePredictStatus | Select-Object InstanceName, PredictFailure, Reason)
} catch { $smartStatus = @() }
[PSCustomObject]@{
    OS = $os; CPU = $cpu; Board = $board; GPUs = $gpus; Memory = $memory; Disks = $disks
    StorageDisks = $storageDisks; PhysicalDisks = $physicalDisks; SmartData = $smartData; SmartStatus = $smartStatus
} | ConvertTo-Json -Depth 9 -Compress
"""
    output = run_text_command([
        "powershell.exe", "-NoLogo", "-NoProfile", "-NonInteractive",
        "-ExecutionPolicy", "Bypass", "-Command", script,
    ], timeout=22)
    if not output:
        fallback["DiskProbeComplete"] = True
        fallback["DiskProbeError"] = "Windows SMART sorgusu yanıt vermedi."
        return fallback

    try:
        raw = json.loads(output)
        if not isinstance(raw, dict):
            fallback["DiskProbeComplete"] = True
            fallback["DiskProbeError"] = "Windows SMART yanıtı çözümlenemedi."
            return fallback

        def ensure_list(value):
            if not value:
                return []
            return value if isinstance(value, list) else [value]

        def as_dict(value):
            return value if isinstance(value, dict) else {}

        def parse_int(value):
            if value is None or value == "":
                return None
            try:
                return int(value)
            except (TypeError, ValueError):
                try:
                    return int(float(value))
                except (TypeError, ValueError):
                    return None

        def clean_id(value):
            return re.sub(r"[^a-z0-9]", "", str(value or "").casefold())

        def format_number(value):
            if value is None:
                return "—"
            try:
                return f"{int(value):,}".replace(",", ".")
            except Exception:
                return str(value)

        def status_text(value):
            raw_status = str(value or "").strip()
            low = raw_status.casefold()
            if any(word in low for word in ("healthy", "ok")):
                return "Sağlıklı"
            if any(word in low for word in ("warning", "pred fail", "degraded", "stressed")):
                return "Uyarı"
            if any(word in low for word in ("unhealthy", "bad", "error", "lost communication")):
                return "Sorunlu"
            return raw_status or "Bilinmiyor"

        def best_match(disk, candidates):
            serial = clean_id(disk.get("SerialNumber"))
            model = clean_id(disk.get("Model"))
            index = parse_int(disk.get("Index"))
            best = None
            best_score = -1
            for candidate in candidates:
                score = 0
                candidate_serial = clean_id(candidate.get("SerialNumber"))
                candidate_name = clean_id(candidate.get("FriendlyName") or candidate.get("Model"))
                candidate_number = parse_int(candidate.get("Number") if "Number" in candidate else candidate.get("DeviceId"))
                if serial and candidate_serial and serial == candidate_serial:
                    score += 100
                elif serial and candidate_serial and (serial in candidate_serial or candidate_serial in serial):
                    score += 70
                if model and candidate_name and (model in candidate_name or candidate_name in model):
                    score += 50
                if index is not None and candidate_number is not None and index == candidate_number:
                    score += 25
                if score > best_score:
                    best = candidate
                    best_score = score
            return best if best_score > 0 else None

        def best_smart_match(disk, candidates):
            pnp = clean_id(disk.get("PNPDeviceID"))
            model = clean_id(disk.get("Model"))
            best = None
            best_score = -1
            for candidate in candidates:
                instance = clean_id(candidate.get("InstanceName"))
                score = 0
                if pnp and instance:
                    if pnp in instance or instance in pnp:
                        score += 120
                    pnp_tokens = set(re.findall(r"[a-z0-9]{4,}", str(disk.get("PNPDeviceID") or "").casefold()))
                    inst_raw = str(candidate.get("InstanceName") or "").casefold()
                    score += sum(min(len(token), 15) for token in pnp_tokens if token in inst_raw)
                if model and instance:
                    for token in re.findall(r"[a-z0-9]{4,}", model):
                        if token in instance:
                            score += min(len(token), 15)
                if score > best_score:
                    best = candidate
                    best_score = score
            return best if best_score >= 8 else None

        os_info = as_dict(raw.get("OS"))
        cpu_info = as_dict(raw.get("CPU"))
        board_info = as_dict(raw.get("Board"))
        gpus = [item for item in ensure_list(raw.get("GPUs")) if isinstance(item, dict)]
        memory = [item for item in ensure_list(raw.get("Memory")) if isinstance(item, dict)]
        disks = [item for item in ensure_list(raw.get("Disks")) if isinstance(item, dict)]
        storage_disks = [item for item in ensure_list(raw.get("StorageDisks")) if isinstance(item, dict)]
        physical_disks = [item for item in ensure_list(raw.get("PhysicalDisks")) if isinstance(item, dict)]
        smart_data = [item for item in ensure_list(raw.get("SmartData")) if isinstance(item, dict)]
        smart_status = [item for item in ensure_list(raw.get("SmartStatus")) if isinstance(item, dict)]

        ram_total = 0
        ram_brands = []
        module_summaries = []
        for item in memory:
            manu = str(item.get("Manufacturer") or "Bilinmiyor").strip()
            part = str(item.get("PartNumber") or "").strip()
            cap = parse_int(item.get("Capacity")) or 0
            ram_total += cap
            if manu and manu.casefold() != "bilinmiyor" and manu not in ram_brands:
                ram_brands.append(manu)
            gb = f"{cap / (1024**3):.0f} GB" if cap else "? GB"
            configured = str(item.get("ConfiguredClockSpeed") or item.get("Speed") or "").strip()
            bits = [gb]
            if manu and manu.casefold() != "bilinmiyor": bits.append(manu)
            if part and part.casefold() != "bilinmiyor": bits.append(part)
            if configured: bits.append(f"{configured} MHz")
            module_summaries.append(" • ".join(bits))
        ram_gb = round(ram_total / (1024**3), 1) if ram_total else 0
        ram_text = fallback["RAMText"]
        if memory:
            ram_text = f"{ram_gb:.0f} GB • {len(memory)} modül" if ram_total else f"{len(memory)} modül"
            if ram_brands: ram_text += " • " + ", ".join(ram_brands)

        gpu_descriptions = []
        gpu_vendor_keys = []
        for item in gpus:
            name = str(item.get("Name") or "Bilinmeyen GPU").strip()
            compat = str(item.get("AdapterCompatibility") or "").strip()
            pnp = str(item.get("PNPDeviceID") or "").strip()
            partner = _extract_pci_subsys_vendor(pnp)
            vendor = _normalise_vendor(f"{compat} {name} {pnp}")
            upper_pnp = pnp.upper()
            if vendor == "unknown":
                if "VEN_10DE" in upper_pnp: vendor = "nvidia"
                elif "VEN_8086" in upper_pnp: vendor = "intel"
                elif "VEN_1002" in upper_pnp or "VEN_1022" in upper_pnp: vendor = "amd"
            if vendor in GPU_DRIVER_URLS and vendor not in gpu_vendor_keys:
                gpu_vendor_keys.append(vendor)
            desc = name
            if partner and partner.casefold() not in desc.casefold(): desc = f"{partner} {desc}"
            elif compat and compat.casefold() not in desc.casefold(): desc = f"{compat} {desc}"
            gpu_descriptions.append(desc)

        board_parts = [str(board_info.get("Manufacturer") or "").strip(), str(board_info.get("Product") or "").strip()]
        board_text = " ".join(part for part in board_parts if part) or fallback["Board"]
        board_ver = str(board_info.get("Version") or "").strip()
        if board_ver and board_ver.casefold() not in ("none", "default string", "to be filled by o.e.m."):
            board_text += f" ({board_ver})"

        disk_details = []
        compact_lines = []
        for disk in disks:
            model = str(disk.get("Model") or "Bilinmeyen Disk").strip()
            index = parse_int(disk.get("Index"))
            storage_match = best_match(disk, storage_disks)
            physical_match = best_match(disk, physical_disks)
            smart_data_match = best_smart_match(disk, smart_data)
            smart_status_match = best_smart_match(disk, smart_status)

            interface_raw = str((storage_match or {}).get("BusType") or (physical_match or {}).get("BusType") or disk.get("InterfaceType") or "Bilinmiyor").strip()
            media = str((physical_match or {}).get("MediaType") or disk.get("MediaType") or "Bilinmiyor").strip()
            interface = _normalize_disk_interface(interface_raw, model, media)
            partition_style = str((storage_match or {}).get("PartitionStyle") or "Bilinmiyor").strip()
            size = parse_int((storage_match or {}).get("Size") or (physical_match or {}).get("Size") or disk.get("Size")) or 0
            size_gb = size / (1024**3) if size else 0
            size_text = f"{size_gb:.1f} GB" if size else "Boyut bilinmiyor"
            serial = str(disk.get("SerialNumber") or (storage_match or {}).get("SerialNumber") or (physical_match or {}).get("SerialNumber") or "Bilinmiyor").strip()
            firmware = str(disk.get("FirmwareRevision") or "Bilinmiyor").strip()
            partitions = parse_int(disk.get("Partitions"))
            bytes_per_sector = parse_int(disk.get("BytesPerSector"))
            is_boot = (storage_match or {}).get("IsBoot")
            is_system = (storage_match or {}).get("IsSystem")
            is_read_only = (storage_match or {}).get("IsReadOnly")
            is_offline = (storage_match or {}).get("IsOffline")

            detail = {
                "index": index,
                "model": model,
                "capacity_gb": round(size_gb, 1) if size else None,
                "capacity_text": size_text,
                "interface": interface,
                "media_type": media,
                "partition_style": partition_style,
                "serial": serial,
                "firmware": firmware,
                "partitions": partitions,
                "bytes_per_sector": bytes_per_sector,
                "is_boot": bool(is_boot) if is_boot is not None else None,
                "is_system": bool(is_system) if is_system is not None else None,
                "is_read_only": bool(is_read_only) if is_read_only is not None else None,
                "is_offline": bool(is_offline) if is_offline is not None else None,
                "health_percent": None,
                "health_status": status_text((physical_match or {}).get("HealthStatus") or (storage_match or {}).get("HealthStatus") or disk.get("Status")),
                "health_source": "Windows disk durumu",
                "temperature": parse_int((physical_match or {}).get("Temperature")),
                "power_on_hours": parse_int((physical_match or {}).get("PowerOnHours")),
                "wear_percent": None,
                "read_errors_total": parse_int((physical_match or {}).get("ReadErrorsTotal")),
                "read_errors_uncorrected": parse_int((physical_match or {}).get("ReadErrorsUncorrected")),
                "write_errors_total": parse_int((physical_match or {}).get("WriteErrorsTotal")),
                "write_errors_uncorrected": parse_int((physical_match or {}).get("WriteErrorsUncorrected")),
            }

            # First choice: the standard NVMe SMART/Health log. This is the real
            # Percentage Used value used by NVMe firmware, not the Windows Wear guess.
            nvme = read_nvme_health_log(index) if index is not None else None
            if nvme:
                detail.update(nvme)
                if "NVME" not in detail["interface"].upper():
                    detail["interface"] = "NVMe"
                if str(detail["media_type"]).casefold() in ("bilinmiyor", "unspecified"):
                    detail["media_type"] = "SSD"
            else:
                attributes = _parse_ata_smart_attributes((smart_data_match or {}).get("VendorSpecific"))
                predict_failure = bool((smart_status_match or {}).get("PredictFailure"))
                reallocated = int((attributes.get(0x05) or {}).get("raw") or 0)
                pending = int((attributes.get(0xC5) or {}).get("raw") or 0)
                uncorrectable = int((attributes.get(0xC6) or {}).get("raw") or 0)
                detail["smart_reallocated"] = reallocated
                detail["smart_pending"] = pending
                detail["smart_uncorrectable"] = uncorrectable
                detail["smart_attributes"] = attributes
                is_ssd = _looks_like_ssd(model, media, interface, attributes)
                if attributes:
                    detail["health_source"] = "SATA SMART" if detail.get("interface") == "SATA" else "ATA SMART"
                    temp_attr = attributes.get(0xC2) or attributes.get(0xBE)
                    if detail["temperature"] is None and temp_attr:
                        raw_temp = int((temp_attr.get("raw_bytes") or [0])[0])
                        if 1 <= raw_temp <= 120:
                            detail["temperature"] = raw_temp
                    if detail["power_on_hours"] is None and attributes.get(0x09):
                        detail["power_on_hours"] = int(attributes[0x09].get("raw") or 0)
                    if attributes.get(0x0C):
                        detail["power_cycles"] = int(attributes[0x0C].get("raw") or 0)
                    if is_ssd:
                        remaining, source = _ata_life_remaining(model, attributes, detail.get("interface") or interface)
                        if remaining is not None:
                            detail["health_percent"] = remaining
                            detail["wear_percent"] = max(0, 100 - remaining)
                            detail["health_source"] = source
                if predict_failure:
                    detail["health_status"] = "Sorunlu"
                elif reallocated or pending or uncorrectable:
                    detail["health_status"] = "Uyarı"
                elif attributes:
                    detail["health_status"] = "Sağlıklı"

                # Windows reliability Wear may be useful only when it is a real,
                # non-zero value. Wear=0 is not treated as proof of 100% health.
                reliability_wear = parse_int((physical_match or {}).get("Wear"))
                # Windows Wear is used only when the drive exposes no ATA SMART table.
                # If SMART attributes exist but no vendor-defined lifetime field is known,
                # showing a guessed percentage would be misleading.
                if (not attributes and detail["health_percent"] is None
                        and reliability_wear is not None and 1 <= reliability_wear <= 100):
                    detail["wear_percent"] = reliability_wear
                    detail["health_percent"] = max(0, 100 - reliability_wear)
                    detail["health_source"] = "Windows Storage Reliability / Wear"

            health_percent = detail.get("health_percent")
            if health_percent is not None:
                if detail.get("health_status") == "Sağlıklı" and int(health_percent) <= 10:
                    detail["health_status"] = "Uyarı"
                health_summary = f"%{int(health_percent)}"
            else:
                health_summary = "Gerçek yüzde desteklenmiyor"

            compact_lines.append(
                f"Disk {index if index is not None else '?'} • {model} • {size_text} • "
                f"{health_summary} • {detail['health_status']} • Kaynak: {detail['health_source']}"
            )
            detail["summary_lines"] = [
                f"Model: {model}",
                f"Kapasite: {size_text}",
                f"Bağlantı / tür: {detail['interface']} • {detail['media_type']}",
                f"Sağlık: {health_summary} • {detail['health_status']}",
                f"Sağlık kaynağı: {detail['health_source']}",
                f"Sıcaklık: {detail.get('temperature')}°C" if detail.get("temperature") is not None else "Sıcaklık: Desteklenmiyor",
                f"Çalışma süresi: {format_number(detail.get('power_on_hours'))} saat",
                f"Açılma sayısı: {format_number(detail.get('power_cycles'))}",
                f"Aşınma / kullanılan ömür: %{detail.get('wear_percent')}" if detail.get("wear_percent") is not None else "Aşınma: Desteklenmiyor",
                f"Toplam okuma: {detail.get('data_read_tb')} TB" if detail.get("data_read_tb") is not None else "Toplam okuma: Desteklenmiyor",
                f"Toplam yazma: {detail.get('data_written_tb')} TB" if detail.get("data_written_tb") is not None else "Toplam yazma: Desteklenmiyor",
                f"Güvensiz kapanma: {format_number(detail.get('unsafe_shutdowns'))}",
                f"Medya / veri bütünlüğü hatası: {format_number(detail.get('media_errors'))}",
                f"Hata günlüğü girdisi: {format_number(detail.get('error_log_entries'))}",
                f"SMART 05 yeniden eşlenen sektör: {format_number(detail.get('smart_reallocated'))}",
                f"SMART C5 bekleyen sektör: {format_number(detail.get('smart_pending'))}",
                f"SMART C6 düzeltilemeyen sektör: {format_number(detail.get('smart_uncorrectable'))}",
                f"Firmware: {firmware}",
                f"Seri no: {serial}",
                f"Bölüm stili: {partition_style}",
                f"Fiziksel disk: {index if index is not None else '?'} • Bölüm sayısı: {partitions if partitions is not None else '—'} • Sektör: {bytes_per_sector if bytes_per_sector is not None else '—'} bayt",
                f"Sistem / önyükleme: {'Evet' if detail.get('is_system') else 'Hayır'} / {'Evet' if detail.get('is_boot') else 'Hayır'}",
            ]
            disk_details.append(detail)

        return {
            "Build": str(os_info.get("BuildNumber") or fallback["Build"]),
            "WindowsCaption": str(os_info.get("Caption") or fallback["WindowsCaption"]),
            "CPU": str(cpu_info.get("Name") or fallback["CPU"]),
            "GPU": ", ".join(gpu_descriptions) if gpu_descriptions else fallback["GPU"],
            "GPUVendors": gpu_vendor_keys or fallback["GPUVendors"],
            "RAM": ram_gb or fallback["RAM"],
            "Modules": len(memory) or fallback["Modules"],
            "RAMText": ram_text,
            "RAMModulesText": "\n".join(module_summaries) if module_summaries else fallback["RAMModulesText"],
            "Board": board_text,
            "DiskText": "\n".join(compact_lines) if compact_lines else fallback["DiskText"],
            "DisksDetailed": disk_details,
            "DiskProbeComplete": True,
        }
    except Exception as exc:
        core.log_line(f"Gelişmiş sistem / SMART özeti okunamadı, temel bilgi kullanılıyor: {exc}")
        fallback["DiskProbeComplete"] = True
        fallback["DiskProbeError"] = str(exc)
        return fallback


