NVIDIA_BACKUP_FILE = NVIDIA_STATE_DIR / "TB_NVIDIA_OLD_PROFILES.nip"
NVIDIA_STATE_FILE = NVIDIA_STATE_DIR / "state.json"
NVIDIA_PERFORMANCE_FILE = NVIDIA_STATE_DIR / "TB_NVIDIA_MAX_PERFORMANCE.nip"

NVIDIA_PROFILE_INSPECTOR_REPO = "Orbmu2k/nvidiaProfileInspector"
NVIDIA_PROFILE_INSPECTOR_API = (
    "https://api.github.com/repos/"
    + NVIDIA_PROFILE_INSPECTOR_REPO
    + "/releases?per_page=20"
)

