def _nvidia_subprocess(args, cwd=None, timeout=180):
    creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
    return subprocess.run(
        [str(item) for item in args],
        cwd=str(cwd) if cwd else None,
        capture_output=True,
        text=True,
        timeout=timeout,
        check=False,
        creationflags=creationflags,
    )


def _load_nvidia_state() -> dict:
    try:
        if NVIDIA_STATE_FILE.exists():
            data = json.loads(NVIDIA_STATE_FILE.read_text(encoding="utf-8"))
            return data if isinstance(data, dict) else {}
    except Exception as exc:
        core.log_line(f"NVIDIA durum dosyası okunamadı: {exc}")
    return {}


def _save_nvidia_state(data: dict) -> None:
    NVIDIA_STATE_DIR.mkdir(parents=True, exist_ok=True)
    NVIDIA_STATE_FILE.write_text(
        json.dumps(data, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )


def nvidia_profile_active() -> bool:
    data = _load_nvidia_state()
    return bool(data.get("active") and NVIDIA_BACKUP_FILE.exists())


def find_nvidia_profile_inspector() -> Path | None:
    candidates = [
        APP_DIR / "nvidiaProfileInspector.exe",
        APP_DIR / "nvidiaProfileInspector" / "nvidiaProfileInspector.exe",
        NVIDIA_TOOL_DIR / "nvidiaProfileInspector.exe",
    ]
    for candidate in candidates:
        if candidate.exists():
            return candidate

    if NVIDIA_TOOL_DIR.exists():
        for candidate in NVIDIA_TOOL_DIR.rglob("nvidiaProfileInspector.exe"):
            if candidate.is_file():
                return candidate
    return None


def download_official_nvidia_profile_inspector(callback) -> Path:
    NVIDIA_TOOL_DIR.mkdir(parents=True, exist_ok=True)
    callback("NVIDIA Profile Inspector resmî GitHub sürümü indiriliyor…")

    zip_path = NVIDIA_STATE_DIR / "nvidiaProfileInspector_latest.zip"
    extract_path = NVIDIA_TOOL_DIR
    zip_ps = str(zip_path).replace("'", "''")
    extract_ps = str(extract_path).replace("'", "''")
    ps_script = f'''\n$ErrorActionPreference = 'Stop'\n$headers = @{{ 'User-Agent' = 'T-Booster' }}\n$releases = Invoke-RestMethod -Headers $headers -Uri '{NVIDIA_PROFILE_INSPECTOR_API}'
$release = $releases | Where-Object {{ -not $_.draft -and $_.tag_name -match '^v3[.]' }} | Select-Object -First 1
if ($null -eq $release) {{ throw 'Yedekleme destekli NVIDIA Profile Inspector v3 sürümü bulunamadı.' }}
$asset = $release.assets | Where-Object {{ $_.name -match '[.]zip$' }} | Select-Object -First 1
if ($null -eq $asset) {{ throw 'GitHub sürümünde ZIP varlığı bulunamadı.' }}
$url = [string]$asset.browser_download_url\nif ($url -notmatch '^https://github[.]com/Orbmu2k/nvidiaProfileInspector/releases/download/') {{ throw 'İndirme adresi resmî depo ile eşleşmedi.' }}\nInvoke-WebRequest -UseBasicParsing -Headers $headers -Uri $url -OutFile '{zip_ps}'\nif (Test-Path '{extract_ps}') {{ Get-ChildItem '{extract_ps}' -Force | Remove-Item -Recurse -Force }}\nExpand-Archive -LiteralPath '{zip_ps}' -DestinationPath '{extract_ps}' -Force\n'''
    result = _nvidia_subprocess(
        [
            "powershell.exe",
            "-NoLogo",
            "-NoProfile",
            "-NonInteractive",
            "-ExecutionPolicy",
            "Bypass",
            "-Command",
            ps_script,
        ],
        timeout=240,
    )
    if result.returncode != 0:
        details = (result.stderr or result.stdout or "Bilinmeyen hata").strip()
        raise RuntimeError("NVIDIA Profile Inspector indirilemedi: " + details)

    exe = find_nvidia_profile_inspector()
    if not exe:
        raise RuntimeError("İndirme tamamlandı ancak nvidiaProfileInspector.exe bulunamadı.")

    try:
        zip_path.unlink(missing_ok=True)
    except Exception:
        pass
    callback("NVIDIA Profile Inspector hazır.")
    return exe


def ensure_nvidia_profile_inspector(callback, allow_download=True) -> Path:
    exe = find_nvidia_profile_inspector()
    if exe:
        return exe
    if not allow_download:
        raise RuntimeError("NVIDIA Profile Inspector bulunamadı.")
    return download_official_nvidia_profile_inspector(callback)


def _export_nvidia_backup(exe: Path, callback) -> Path:
    callback("Mevcut NVIDIA profil özelleştirmeleri yedekleniyor…")
    tool_dir = exe.parent
    before = {
        str(item.resolve()): item.stat().st_mtime_ns
        for item in tool_dir.rglob("*.nip")
        if item.is_file()
    }
    started_ns = time.time_ns()
    result = _nvidia_subprocess(
        [exe, "-exportCustomized"],
        cwd=tool_dir,
        timeout=120,
    )
    if result.returncode != 0:
        details = (result.stderr or result.stdout or "Bilinmeyen hata").strip()
        raise RuntimeError("NVIDIA profil yedeği alınamadı: " + details)

    candidates = []
    for item in tool_dir.rglob("*.nip"):
        if not item.is_file():
            continue
        old_stamp = before.get(str(item.resolve()))
        stamp = item.stat().st_mtime_ns
        if old_stamp is None or stamp != old_stamp or stamp >= started_ns - 3_000_000_000:
            candidates.append(item)

    named = [item for item in candidates if "customized" in item.name.casefold()]
    if named:
        candidates = named
    if not candidates:
        candidates = [
            item for item in tool_dir.rglob("*.nip")
            if item.is_file() and "customized" in item.name.casefold()
        ]
    if not candidates:
        raise RuntimeError("NVIDIA Profile Inspector yedek dosyası oluşturmadı.")

    newest = max(candidates, key=lambda item: item.stat().st_mtime_ns)
    NVIDIA_STATE_DIR.mkdir(parents=True, exist_ok=True)
    shutil.copy2(newest, NVIDIA_BACKUP_FILE)
    callback("NVIDIA profil yedeği güvenli klasöre kaydedildi.")
    return NVIDIA_BACKUP_FILE


def apply_nvidia_max_performance(callback, allow_download=True) -> dict:
    detected = driver_hardware_info()
    if not detected.get("ok") or "nvidia" not in (detected.get("gpu_vendors") or []):
        raise RuntimeError("Bu sistemde desteklenen NVIDIA ekran kartı algılanmadı.")

    NVIDIA_STATE_DIR.mkdir(parents=True, exist_ok=True)
    exe = ensure_nvidia_profile_inspector(callback, allow_download=allow_download)
    state = _load_nvidia_state()

    if not state.get("active") or not NVIDIA_BACKUP_FILE.exists():
        _export_nvidia_backup(exe, callback)

    NVIDIA_PERFORMANCE_FILE.write_text(
        NVIDIA_PERFORMANCE_PROFILE_XML,
        encoding="utf-16",
    )
    callback("NVIDIA maksimum performans profili uygulanıyor…")
    result = _nvidia_subprocess(
        [exe, "-silentImport", NVIDIA_PERFORMANCE_FILE],
        cwd=exe.parent,
        timeout=120,
    )
    if result.returncode != 0:
        details = (result.stderr or result.stdout or "Bilinmeyen hata").strip()
        raise RuntimeError("NVIDIA profili uygulanamadı: " + details)

    state.update(
        {
            "active": True,
            "backup": str(NVIDIA_BACKUP_FILE),
            "profile": str(NVIDIA_PERFORMANCE_FILE),
            "applied_at": dt.datetime.now().isoformat(timespec="seconds"),
            "gpu_names": detected.get("gpu_names") or [],
        }
    )
    _save_nvidia_state(state)
    callback("NVIDIA maksimum performans profili uygulandı.")
    return {
        "applied": True,
        "backup": str(NVIDIA_BACKUP_FILE),
        "gpu_names": detected.get("gpu_names") or [],
    }


def restore_nvidia_profile(callback, allow_download=True) -> dict:
    state = _load_nvidia_state()
    if not state.get("active"):
        return {"restored": False, "reason": "aktif_degil"}
    if not NVIDIA_BACKUP_FILE.exists():
        raise RuntimeError("NVIDIA geri alma yedeği bulunamadı.")

    exe = ensure_nvidia_profile_inspector(callback, allow_download=allow_download)
    callback("Eski NVIDIA profil ayarları geri yükleniyor…")
    result = _nvidia_subprocess(
        [exe, "-silentImport", NVIDIA_BACKUP_FILE],
        cwd=exe.parent,
        timeout=120,
    )
    if result.returncode != 0:
        details = (result.stderr or result.stdout or "Bilinmeyen hata").strip()
        raise RuntimeError("NVIDIA profil yedeği geri yüklenemedi: " + details)

    state["active"] = False
    state["restored_at"] = dt.datetime.now().isoformat(timespec="seconds")
    _save_nvidia_state(state)
    callback("Eski NVIDIA profil ayarları geri yüklendi.")
    return {"restored": True, "backup": str(NVIDIA_BACKUP_FILE)}


