# Intel Graphics güvenli maksimum performans desteği
# ---------------------------------------------------------------------------
INTEL_STATE_DIR = Path(
    os.environ.get("ProgramData", str(Path.home()))
) / "TBooster" / "Intel"
INTEL_BACKUP_FILE = INTEL_STATE_DIR / "intel_power_backup.json"
INTEL_STATE_FILE = INTEL_STATE_DIR / "state.json"
INTEL_GRAPHICS_SUBGROUP_GUID = "44f3beca-a7e0-460e-9df2-bb8b99e0cba6"
INTEL_GRAPHICS_POWER_SETTING_GUID = "3619c3f2-afb2-4afc-b0e9-e7fef372de36"
INTEL_MAXIMUM_PERFORMANCE_INDEX = 2


class _POWER_GUID(ctypes.Structure):
    _fields_ = [
        ("Data1", ctypes.c_uint32),
        ("Data2", ctypes.c_uint16),
        ("Data3", ctypes.c_uint16),
        ("Data4", ctypes.c_ubyte * 8),
    ]


def _power_guid(value: str) -> _POWER_GUID:
    return _POWER_GUID.from_buffer_copy(uuid.UUID(str(value)).bytes_le)


def _power_guid_text(value: _POWER_GUID) -> str:
    raw = ctypes.string_at(ctypes.byref(value), ctypes.sizeof(value))
    return str(uuid.UUID(bytes_le=raw))


def _power_get_active_scheme_guid() -> str:
    powrprof = ctypes.WinDLL("PowrProf.dll")
    fn = powrprof.PowerGetActiveScheme
    fn.argtypes = [ctypes.c_void_p, ctypes.POINTER(ctypes.POINTER(_POWER_GUID))]
    fn.restype = wintypes.DWORD
    pointer = ctypes.POINTER(_POWER_GUID)()
    result = int(fn(None, ctypes.byref(pointer)))
    if result != 0 or not pointer:
        raise OSError(result, "Etkin güç planı okunamadı.")
    try:
        return _power_guid_text(pointer.contents)
    finally:
        try:
            ctypes.windll.kernel32.LocalFree(ctypes.cast(pointer, ctypes.c_void_p))
        except Exception:
            pass


def _power_read_value_index(
    scheme_guid: str,
    subgroup_guid: str,
    setting_guid: str,
    *,
    dc: bool = False,
) -> int | None:
    try:
        powrprof = ctypes.WinDLL("PowrProf.dll")
        function_name = "PowerReadDCValueIndex" if dc else "PowerReadACValueIndex"
        fn = getattr(powrprof, function_name)
        fn.argtypes = [
            ctypes.c_void_p,
            ctypes.POINTER(_POWER_GUID),
            ctypes.POINTER(_POWER_GUID),
            ctypes.POINTER(_POWER_GUID),
            ctypes.POINTER(wintypes.DWORD),
        ]
        fn.restype = wintypes.DWORD
        scheme = _power_guid(scheme_guid)
        subgroup = _power_guid(subgroup_guid)
        setting = _power_guid(setting_guid)
        value = wintypes.DWORD()
        result = int(
            fn(
                None,
                ctypes.byref(scheme),
                ctypes.byref(subgroup),
                ctypes.byref(setting),
                ctypes.byref(value),
            )
        )
        return int(value.value) if result == 0 else None
    except Exception:
        return None


def _power_write_value_index(
    scheme_guid: str,
    subgroup_guid: str,
    setting_guid: str,
    value: int,
    *,
    dc: bool = False,
) -> bool:
    try:
        powrprof = ctypes.WinDLL("PowrProf.dll")
        function_name = "PowerWriteDCValueIndex" if dc else "PowerWriteACValueIndex"
        fn = getattr(powrprof, function_name)
        fn.argtypes = [
            ctypes.c_void_p,
            ctypes.POINTER(_POWER_GUID),
            ctypes.POINTER(_POWER_GUID),
            ctypes.POINTER(_POWER_GUID),
            wintypes.DWORD,
        ]
        fn.restype = wintypes.DWORD
        scheme = _power_guid(scheme_guid)
        subgroup = _power_guid(subgroup_guid)
        setting = _power_guid(setting_guid)
        result = int(
            fn(
                None,
                ctypes.byref(scheme),
                ctypes.byref(subgroup),
                ctypes.byref(setting),
                wintypes.DWORD(int(value)),
            )
        )
        return result == 0
    except Exception:
        return False


def _power_set_active_scheme(scheme_guid: str) -> bool:
    try:
        powrprof = ctypes.WinDLL("PowrProf.dll")
        fn = powrprof.PowerSetActiveScheme
        fn.argtypes = [ctypes.c_void_p, ctypes.POINTER(_POWER_GUID)]
        fn.restype = wintypes.DWORD
        scheme = _power_guid(scheme_guid)
        return int(fn(None, ctypes.byref(scheme))) == 0
    except Exception:
        return False


def _load_intel_state() -> dict:
    try:
        if INTEL_STATE_FILE.exists():
            data = json.loads(INTEL_STATE_FILE.read_text(encoding="utf-8"))
            return data if isinstance(data, dict) else {}
    except Exception as exc:
        core.log_line(f"Intel durum dosyası okunamadı: {exc}")
    return {}


def _save_intel_state(data: dict) -> None:
    INTEL_STATE_DIR.mkdir(parents=True, exist_ok=True)
    INTEL_STATE_FILE.write_text(
        json.dumps(data, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )


def intel_performance_active() -> bool:
    state = _load_intel_state()
    return bool(state.get("active") and INTEL_BACKUP_FILE.exists())


def apply_intel_max_performance(callback) -> dict:
    detected = driver_hardware_info()
    if not detected.get("ok") or "intel" not in (detected.get("gpu_vendors") or []):
        raise RuntimeError("Bu sistemde Intel ekran kartı algılanmadı.")

    scheme_guid = _power_get_active_scheme_guid()
    old_ac = _power_read_value_index(
        scheme_guid,
        INTEL_GRAPHICS_SUBGROUP_GUID,
        INTEL_GRAPHICS_POWER_SETTING_GUID,
        dc=False,
    )
    old_dc = _power_read_value_index(
        scheme_guid,
        INTEL_GRAPHICS_SUBGROUP_GUID,
        INTEL_GRAPHICS_POWER_SETTING_GUID,
        dc=True,
    )

    if old_ac is None:
        callback(
            "Intel Graphics Power Plan bu sürücüde Windows güç API'si üzerinden sunulmuyor; "
            "güvenli Windows/GPU performans ayarları uygulandı."
        )
        return {
            "applied": False,
            "supported": False,
            "gpu_names": detected.get("gpu_names") or [],
            "reason": "intel_power_setting_not_exposed",
        }

    # Aktif bir Intel ayarı varsa ilk/orijinal yedeği koru; tekrar basıldığında
    # 2 değerini yedekleyip geri alma işlevini bozmamalı.
    if not intel_performance_active():
        INTEL_STATE_DIR.mkdir(parents=True, exist_ok=True)
        backup = {
            "scheme_guid": scheme_guid,
            "ac_index": old_ac,
            "dc_index": old_dc,
            "created_at": dt.datetime.now().isoformat(timespec="seconds"),
            "gpu_names": detected.get("gpu_names") or [],
        }
        INTEL_BACKUP_FILE.write_text(
            json.dumps(backup, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )

    if not _power_write_value_index(
        scheme_guid,
        INTEL_GRAPHICS_SUBGROUP_GUID,
        INTEL_GRAPHICS_POWER_SETTING_GUID,
        INTEL_MAXIMUM_PERFORMANCE_INDEX,
        dc=False,
    ):
        raise RuntimeError("Intel Graphics Power Plan maksimum performansa alınamadı.")

    _power_set_active_scheme(scheme_guid)
    verify_ac = _power_read_value_index(
        scheme_guid,
        INTEL_GRAPHICS_SUBGROUP_GUID,
        INTEL_GRAPHICS_POWER_SETTING_GUID,
        dc=False,
    )
    if verify_ac != INTEL_MAXIMUM_PERFORMANCE_INDEX:
        raise RuntimeError("Intel maksimum performans değeri doğrulanamadı.")

    state = _load_intel_state()
    state.update(
        {
            "active": True,
            "backup": str(INTEL_BACKUP_FILE),
            "scheme_guid": scheme_guid,
            "applied_at": dt.datetime.now().isoformat(timespec="seconds"),
            "gpu_names": detected.get("gpu_names") or [],
        }
    )
    _save_intel_state(state)
    callback(
        "Intel Graphics Power Plan (prize takılı): Maximum Performance. "
        "Batarya profili korunmuştur."
    )
    return {
        "applied": True,
        "supported": True,
        "backup": str(INTEL_BACKUP_FILE),
        "old_ac": old_ac,
        "new_ac": INTEL_MAXIMUM_PERFORMANCE_INDEX,
        "dc_preserved": old_dc,
        "gpu_names": detected.get("gpu_names") or [],
    }


def restore_intel_performance(callback) -> dict:
    state = _load_intel_state()
    if not state.get("active"):
        return {"restored": False, "reason": "aktif_degil"}
    if not INTEL_BACKUP_FILE.exists():
        raise RuntimeError("Intel geri alma yedeği bulunamadı.")

    backup = json.loads(INTEL_BACKUP_FILE.read_text(encoding="utf-8"))
    scheme_guid = str(backup.get("scheme_guid") or "").strip()
    if not scheme_guid:
        raise RuntimeError("Intel yedeğinde güç planı kimliği yok.")

    callback("Eski Intel grafik güç ayarı geri yükleniyor…")
    restored_any = False
    old_ac = backup.get("ac_index")
    old_dc = backup.get("dc_index")
    if old_ac is not None:
        restored_any = _power_write_value_index(
            scheme_guid,
            INTEL_GRAPHICS_SUBGROUP_GUID,
            INTEL_GRAPHICS_POWER_SETTING_GUID,
            int(old_ac),
            dc=False,
        ) or restored_any
    if old_dc is not None:
        restored_any = _power_write_value_index(
            scheme_guid,
            INTEL_GRAPHICS_SUBGROUP_GUID,
            INTEL_GRAPHICS_POWER_SETTING_GUID,
            int(old_dc),
            dc=True,
        ) or restored_any
    if not restored_any:
        raise RuntimeError("Intel grafik güç ayarı geri yüklenemedi.")

    try:
        current_scheme = _power_get_active_scheme_guid()
    except Exception:
        current_scheme = ""
    if current_scheme.casefold() == scheme_guid.casefold():
        _power_set_active_scheme(scheme_guid)
    state["active"] = False
    state["restored_at"] = dt.datetime.now().isoformat(timespec="seconds")
    _save_intel_state(state)
    callback("Eski Intel grafik güç ayarı geri yüklendi.")
    return {"restored": True, "backup": str(INTEL_BACKUP_FILE)}


