def _tb_tweak(category, key, title, description, accent="ACCENT", recommended=False, edits=None):
    return {
        "category": category,
        "key": key,
        "title": title,
        "description": description,
        "accent": accent,
        "recommended": bool(recommended),
        "edits": list(edits or []),
    }


