def repair_alt_tab_display(callback) -> dict:
    """Restore Windows defaults that provide faster Alt-Tab transitions."""
    backup = core.BackupStore()
    applied = 0
    failed = []

    edits = [
        (
            "alt_tab_fso_mode_default",
            "HKCU",
            winreg.HKEY_CURRENT_USER,
            r"System\GameConfigStore",
            "GameDVR_FSEBehaviorMode",
            0,
        ),
        (
            "alt_tab_fso_honor_default",
            "HKCU",
            winreg.HKEY_CURRENT_USER,
            r"System\GameConfigStore",
            "GameDVR_HonorUserFSEBehaviorMode",
            0,
        ),
    ]

    for item_id, root_name, root_handle, path, name, value in edits:
        try:
            backup.backup_registry(item_id, root_name, path, name)
            with winreg.CreateKeyEx(root_handle, path, 0, winreg.KEY_SET_VALUE) as key:
                winreg.SetValueEx(key, name, 0, winreg.REG_DWORD, value)
            applied += 1
            callback(f"Alt-Tab görüntü varsayılanı onarıldı: {name}")
        except Exception as exc:
            failed.append(f"{name}: {exc}")
            callback(f"Alt-Tab görüntü ayarı onarılamadı ({name}): {exc}")

    # OverlayTestMode=5 disables MPO. Removing it returns DWM to the driver/Windows default.
    try:
        mpo_path = r"SOFTWARE\Microsoft\Windows\Dwm"
        mpo_name = "OverlayTestMode"
        backup.backup_registry("alt_tab_mpo_default", "HKLM", mpo_path, mpo_name)
        with winreg.CreateKeyEx(winreg.HKEY_LOCAL_MACHINE, mpo_path, 0, winreg.KEY_SET_VALUE) as key:
            try:
                winreg.DeleteValue(key, mpo_name)
            except FileNotFoundError:
                pass
        applied += 1
        callback("MPO / DWM görüntü modu Windows varsayılanına döndürüldü.")
    except Exception as exc:
        failed.append(f"OverlayTestMode: {exc}")
        callback(f"MPO varsayılanı onarılamadı: {exc}")

    callback("Alt-Tab siyah ekran koruması tamamlandı. Oyunu yeniden başlatman gerekebilir.")
    return {"applied": applied, "failed": failed}


