def _powercfg_ac(plan_guid: str, subgroup: str, setting: str, value: int) -> bool:
    response = core.run_command(
        [
            "powercfg.exe",
            "/setacvalueindex",
            plan_guid,
            subgroup,
            setting,
            str(value),
        ],
        timeout=15,
    )
    return getattr(response, "returncode", 1) == 0


def apply_ultra_v53_cpu_latency(callback) -> dict:
    backup = core.BackupStore()
    core.apply_power_plan(backup, callback)
    plan = core.PLAN_GUID
    # PowerCfg aliases are used where Microsoft exposes them. Unsupported
    # aliases/classes are skipped without failing the whole boost.
    settings = (
        ("SUB_PROCESSOR", "LATENCYHINTPERF", 100, "Latency hint performansı %100"),
        ("SUB_PROCESSOR", "LATENCYHINTPERF1", 100, "E-core latency hint performansı %100"),
        ("SUB_PROCESSOR", "LATENCYHINTEPP", 0, "Latency hint EPP 0"),
        ("SUB_PROCESSOR", "LATENCYHINTEPP1", 0, "E-core latency hint EPP 0"),
        ("SUB_PROCESSOR", "LATENCYHINTUNPARK", 100, "Latency hint çekirdek unpark %100"),
        ("SUB_PROCESSOR", "LATENCYHINTUNPARK1", 100, "E-core latency hint unpark %100"),
        ("SUB_PROCESSOR", "PERFINCPOL", 3, "Performans yükseltme politikası: responsiveness"),
        ("SUB_PROCESSOR", "PERFINCPOL1", 3, "E-core yükseltme politikası: responsiveness"),
        ("SUB_PROCESSOR", "PERFDECPOL", 1, "Performans düşürme: kademeli"),
        ("SUB_PROCESSOR", "PERFDECPOL1", 1, "E-core performans düşürme: kademeli"),
        ("SUB_PROCESSOR", "PERFINCTHRESHOLD", 10, "Performans yükseltme eşiği %10"),
        ("SUB_PROCESSOR", "PERFINCTHRESHOLD1", 10, "E-core yükseltme eşiği %10"),
        ("SUB_PROCESSOR", "PERFDECTHRESHOLD", 5, "Performans düşürme eşiği %5"),
        ("SUB_PROCESSOR", "PERFDECTHRESHOLD1", 5, "E-core düşürme eşiği %5"),
        ("SUB_PROCESSOR", "PERFBOOSTPOL", 100, "Boost politikası %100"),
    )
    applied = []
    skipped = []
    for subgroup, setting, value, label in settings:
        if _powercfg_ac(plan, subgroup, setting, value):
            applied.append(label)
        else:
            skipped.append(label)
    core.run_command(["powercfg.exe", "/setactive", plan], timeout=15)
    callback(f"Ultra MAX CPU gecikme ayarları: {len(applied)}/{len(settings)} uygulandı.")
    return {"applied": applied, "skipped": skipped}


def apply_ultra_v53_storage_latency(callback) -> dict:
    backup = core.BackupStore()
    core.apply_power_plan(backup, callback)
    plan = core.PLAN_GUID
    sub_disk = "0012ee47-9041-4b5d-9b77-535fba8b1442"
    settings = (
        # AHCI link power management: Active (no HIPM/DIPM) on AC.
        (sub_disk, "0b2d69d7-a2a1-449c-9680-f91c70521c60", 0, "AHCI bağlantı güç yönetimi Active"),
        # NVMe primary/secondary transition tolerances: 0 ms.
        (sub_disk, "fc95af4d-40e7-4b6d-835a-56d131dbc80e", 0, "NVMe birincil geçiş toleransı 0 ms"),
        (sub_disk, "dbc9e238-6de9-49e3-92cd-8c2b4946b472", 0, "NVMe ikincil geçiş toleransı 0 ms"),
        # Keep idle transitions far away during an AC gaming session.
        (sub_disk, "d639518a-e56d-4345-8af2-b9f32fb26109", 60000, "NVMe birincil idle 60 sn"),
        (sub_disk, "d3d55efd-c1ff-424e-9dc3-441be7833010", 60000, "NVMe ikincil idle 60 sn"),
        (sub_disk, "51dea550-bb38-4bc4-991b-eacf37be5ec8", 100, "NVMe aktif güç seviyesi %100"),
    )
    applied = []
    for subgroup, setting, value, label in settings:
        if _powercfg_ac(plan, subgroup, setting, value):
            applied.append(label)
    # TRIM is safe to request; unsupported storage drivers simply return an error.
    trim = core.run_command(["fsutil.exe", "behavior", "set", "DisableDeleteNotify", "0"], timeout=20)
    if getattr(trim, "returncode", 1) == 0:
        applied.append("SSD TRIM / DeleteNotify açık")
    core.run_command(["powercfg.exe", "/setactive", plan], timeout=15)
    callback(f"Ultra MAX depolama gecikme ayarları: {len(applied)}/7 uygulandı.")
    return {"applied": applied}


def apply_ultra_v53_device_performance(callback) -> dict:
    backup = core.BackupStore()
    core.apply_power_plan(backup, callback)
    # Device Idle Policy = Performance on AC.
    ok = _powercfg_ac(
        core.PLAN_GUID,
        "fea3413e-7e05-4911-9a71-700331f1c294",
        "4faab71a-92e5-4726-b531-224559672d19",
        0,
    )
    core.run_command(["powercfg.exe", "/setactive", core.PLAN_GUID], timeout=15)
    callback("Ultra MAX aygıt idle politikası: " + ("Performans" if ok else "desteklenmedi/atlandı"))
    return {"applied": int(ok)}


def apply_ultra_v53_game_gpu(exe_path: str, callback) -> dict:
    path = Path(exe_path)
    if not path.is_file() or path.suffix.lower() != ".exe":
        callback("Ultra MAX oyun hedefi: Oyun EXE seçilmedi, oyun-bazlı adımlar atlandı.")
        return {"applied": 0, "reason": "oyun_exe_yok"}

    backup = core.BackupStore()
    # Same value Windows Graphics Settings uses for High performance.
    core.write_registry(
        backup,
        "ultra_v53_game_gpu_" + re.sub(r"[^A-Za-z0-9]", "_", path.name)[:40],
        "HKCU",
        r"Software\Microsoft\DirectX\UserGpuPreferences",
        str(path),
        core.REG_SZ,
        "GpuPreference=2;",
    )
    applied = 1
    callback("Seçilen oyun Windows Yüksek Performanslı GPU tercihine bağlandı.")

    # If already running, raise only that game's process priority for this session.
    safe_stem = path.stem.replace("'", "''")
    ps = (
        f"$p=Get-Process -Name '{safe_stem}' -ErrorAction SilentlyContinue; "
        "if($p){foreach($x in $p){try{$x.PriorityClass='High'}catch{}}; exit 0}else{exit 3}"
    )
    response = core.run_command(
        ["powershell.exe", "-NoLogo", "-NoProfile", "-NonInteractive", "-Command", ps],
        timeout=15,
    )
    if getattr(response, "returncode", 1) == 0:
        callback("Çalışan oyun işlemi bu oturum için Yüksek önceliğe alındı.")
        applied += 1
    else:
        callback("Oyun henüz çalışmıyor; işlem önceliği adımı oyun başlatıcıya bırakıldı.")
    return {"applied": applied, "exe": str(path)}


def apply_ultra_v53_ethernet(callback) -> dict:
    try:
        result = v49tools.apply_ethernet_low_latency(False, callback)
        return {"applied": 2, "result": result}
    except Exception as exc:
        callback("Ultra MAX Ethernet adımı atlandı: " + str(exc))
        return {"applied": 0, "error": str(exc)}


def apply_ultra_v53_extensions(game_exe: str, callback) -> dict:
    result = {
        "cpu": apply_ultra_v53_cpu_latency(callback),
        "storage": apply_ultra_v53_storage_latency(callback),
        "device": apply_ultra_v53_device_performance(callback),
        "game": apply_ultra_v53_game_gpu(game_exe, callback),
        "ethernet": apply_ultra_v53_ethernet(callback),
    }
    total = 0
    for value in result.values():
        if isinstance(value, dict):
            applied = value.get("applied", 0)
            total += len(applied) if isinstance(applied, list) else int(applied or 0)
    result["total_applied"] = total
    callback(f"Ultra MAX gelişmiş katmanı tamamlandı: {total} ek adım uygulandı.")
    return result


def _auto_game_exe_for_performance() -> str:
    """Return the best detected game EXE for per-game GPU preference."""
    try:
        games = detect_installed_games()
    except Exception:
        return ""
    running = [item for item in games if item.get("running") and item.get("path")]
    found = [item for item in games if item.get("found") and item.get("path")]
    for item in (running or found):
        path = Path(str(item.get("path") or ""))
        if path.is_file() and path.suffix.casefold() == ".exe":
            return str(path)
    return ""


def apply_real_fps_performance_bundle(game_exe: str, callback, progress_callback=None) -> dict:
    """Apply measurable and reversible performance settings."""
    callback("Gerçek FPS Modu başlatıldı: güvenli performans adımları uygulanıyor…")
    result = {
        "base": {},
        "safe_options": {},
        "advanced": {},
        "vendor": {},
        "analysis": {},
        "warnings": [],
    }

    result["base"] = core.apply_boost(callback, progress_callback)

    safe_keys = [
        "game_mode",
        "game_dvr_off",
        "power_throttle_off",
        "mouse_accel_off",
        "hpet_cleanup",
        "msi_mode",
        "ultra_mmcss_safe",
        "trim_enable",
        "nvme_ac_performance",
    ]
    result["safe_options"] = apply_selected_options(safe_keys, callback)

    target_exe = str(game_exe or "").strip()
    if not Path(target_exe).is_file():
        target_exe = _auto_game_exe_for_performance()
        if target_exe:
            callback("Oyun otomatik algılandı: " + Path(target_exe).name)
        else:
            callback("Oyun EXE bulunamadı; oyun-bazlı GPU tercihi atlandı.")
    result["game_exe"] = target_exe
    result["advanced"] = apply_ultra_v53_extensions(target_exe, callback)

    detected = driver_hardware_info()
    vendors = list(detected.get("gpu_vendors") or []) if detected.get("ok") else []
    result["gpu_vendors"] = vendors

    if "intel" in vendors:
        try:
            result["vendor"]["intel"] = apply_intel_max_performance(callback)
        except Exception as exc:
            result["warnings"].append("Intel: " + str(exc))
            callback("Intel performans adımı atlandı: " + str(exc))

    if "nvidia" in vendors:
        try:
            npi = find_nvidia_profile_inspector()
            if npi:
                result["vendor"]["nvidia"] = apply_nvidia_max_performance(
                    callback,
                    allow_download=False,
                )
            else:
                result["warnings"].append(
                    "NVIDIA Profile Inspector bulunamadı; NVIDIA global profili atlandı."
                )
                callback("NVIDIA sürücü profili ayrı NVIDIA düğmesinden uygulanabilir.")
        except Exception as exc:
            result["warnings"].append("NVIDIA: " + str(exc))
            callback("NVIDIA profil adımı atlandı: " + str(exc))

    if "amd" in vendors:
        result["vendor"]["amd"] = {"applied": True, "safe_windows_profile": True}
        callback(
            "AMD kart algılandı: güvenli Windows/GPU profili uygulandı; "
            "overclock ve test edilmemiş sürücü Registry ayarları uygulanmadı."
        )

    try:
        monitors = collect_monitor_info()
        games = detect_installed_games()
        xmp = memory_profile_info()
        checks = collect_one_click_checks(monitors, games, xmp)
        result["analysis"] = {
            "monitors": monitors,
            "games": games,
            "xmp": xmp,
            "checks": checks,
        }
        bad_count = sum(1 for item in checks if item.get("level") == "bad")
        warning_count = sum(1 for item in checks if item.get("level") == "warning")
        callback(
            f"Sistem kontrolü tamamlandı: {bad_count} kritik, {warning_count} uyarı."
        )
    except Exception as exc:
        result["warnings"].append("Analiz: " + str(exc))
        callback("Performans sonrası sistem analizi kısmen atlandı: " + str(exc))

    result["hags_policy"] = "Mevcut durum korundu; oyuna göre A/B testi önerilir."
    callback("HAGS, MPO ve tam ekran zorlamaları sistemden sisteme değiştiği için korunmuştur.")
    callback("Gerçek FPS Modu tamamlandı. Yedekli değişiklikler Geri Al ile döndürülebilir.")
    return result


def apply_selected_options(option_ids: list[str], callback) -> dict:
    backup = core.BackupStore()
    result = {"applied": 0, "msi": 0, "xbox": 0, "hpet": 0}
    callback("Seçili V4 panel ayarları uygulanıyor...")
    if "fullscreen_opt_off" in option_ids or "mpo_off" in option_ids:
        callback("Uyarı: Bu görüntü ayarları bazı oyunlarda Alt-Tab yaparken kısa süreli siyah ekrana sebep olabilir.")
    for option_id in option_ids:
        if option_id in TB_PROTECTED_COMMUNICATION_KEYS:
            callback("Korunan iletişim ayarı atlandı: " + option_id)
            continue
        if option_id in ULTRA_V53_OPTION_KEYS:
            # Applied together after the core boost so power, network and game steps stay coordinated.
            continue
        if option_id == "hpet_cleanup":
            core.remove_forced_timer_overrides(backup, callback)
            result["hpet"] += 1
            result["applied"] += 1
            continue
        if option_id == "msi_mode":
            result["msi"] += core.enable_supported_gpu_msi(backup, callback)
            result["applied"] += 1
            continue
        if option_id == "xbox_cleanup":
            result["xbox"] += core.disable_xbox_services(callback)
            result["xbox"] += core.remove_xbox_apps(callback)
            result["applied"] += 1
            continue
        if option_id == "trim_enable":
            backup.backup_registry(
                "storage_trim_ntfs",
                "HKLM",
                r"SYSTEM\CurrentControlSet\Control\FileSystem",
                "NtfsDisableDeleteNotify",
            )
            response = core.run_command(
                [
                    "fsutil.exe",
                    "behavior",
                    "set",
                    "DisableDeleteNotify",
                    "0",
                ],
                timeout=20,
            )
            if getattr(response, "returncode", 1) == 0:
                callback("SSD TRIM / DeleteNotify etkinleştirildi.")
            else:
                callback("TRIM ayarı uygulanamadı; sürücü desteği kontrol edilmeli.")
            result["applied"] += 1
            continue

        if option_id == "nvme_ac_performance":
            core.apply_power_plan(backup, callback)
            subgroup_disk = "0012ee47-9041-4b5d-9b77-535fba8b1442"
            settings = (
                # Primary / secondary transition latency tolerance: AC = 0 ms.
                ("fc95af4d-40e7-4b6d-835a-56d131dbc80e", 0),
                ("dbc9e238-6de9-49e3-92cd-8c2b4946b472", 0),
                # Maximum active NVMe power level: 100%.
                ("51dea550-bb38-4bc4-991b-eacf37be5ec8", 100),
            )
            applied = 0
            for setting_guid, value in settings:
                response = core.run_command(
                    [
                        "powercfg.exe",
                        "/setacvalueindex",
                        core.PLAN_GUID,
                        subgroup_disk,
                        setting_guid,
                        str(value),
                    ],
                    timeout=15,
                )
                if getattr(response, "returncode", 1) == 0:
                    applied += 1
            core.run_command(
                ["powercfg.exe", "/setactive", core.PLAN_GUID],
                timeout=15,
            )
            callback(
                f"NVMe AC performans ayarları uygulandı: {applied}/3."
            )
            result["applied"] += 1
            continue

        if option_id == "ntfs_memoryusage_2":
            backup.backup_registry(
                "storage_ntfs_memoryusage",
                "HKLM",
                r"SYSTEM\CurrentControlSet\Control\FileSystem",
                "NtfsMemoryUsage",
            )
            response = core.run_command(
                [
                    "fsutil.exe",
                    "behavior",
                    "set",
                    "memoryusage",
                    "2",
                ],
                timeout=20,
            )
            if getattr(response, "returncode", 1) == 0:
                callback(
                    "Deneysel NTFS memoryusage=2 uygulandı; yeniden başlatma gerekir."
                )
            else:
                callback("NTFS memoryusage=2 uygulanamadı.")
            result["applied"] += 1
            continue

        if option_id == "ultra_cs2_session_priority":
            response = core.run_command(
                [
                    "powershell.exe",
                    "-NoLogo",
                    "-NoProfile",
                    "-NonInteractive",
                    "-ExecutionPolicy",
                    "Bypass",
                    "-Command",
                    "$p = Get-Process cs2 -ErrorAction SilentlyContinue; "
                    "if ($p) { $p.PriorityClass = 'High'; exit 0 } "
                    "else { exit 3 }",
                ],
                timeout=12,
            )
            if getattr(response, "returncode", 1) == 0:
                callback("CS2 bu oturum için Yüksek işlem önceliğine alındı.")
            else:
                callback("CS2 çalışmıyor; oturumluk yüksek öncelik adımı atlandı.")
            result["applied"] += 1
            continue
        edits = EXTRA_OPTION_GROUPS.get(option_id, [])
        if not edits:
            continue
        for item_id, root, path, name, value_type, value in edits:
            try:
                core.write_registry(backup, item_id, root, path, name, value_type, value)
            except Exception as exc:
                core.log_line(f"V4 panel ayarı atlandı ({option_id}/{name}): {exc}")
        result["applied"] += 1
    core.run_command(["rundll32.exe", "user32.dll,UpdatePerUserSystemParameters"], timeout=10)
    callback(f"V4 panel ayarları tamamlandı: {result['applied']} seçenek.")
    return result


# ---------------------------------------------------------------------------
# Monitor, automatic game detection and one-click system scan
# ---------------------------------------------------------------------------

class _POINTL(ctypes.Structure):
    _fields_ = [("x", ctypes.c_long), ("y", ctypes.c_long)]


class _DEVMODE_DISPLAY(ctypes.Structure):
    _fields_ = [
        ("dmPosition", _POINTL),
        ("dmDisplayOrientation", wintypes.DWORD),
        ("dmDisplayFixedOutput", wintypes.DWORD),
    ]


class _DEVMODE_UNION(ctypes.Union):
    _fields_ = [("display", _DEVMODE_DISPLAY), ("printer", ctypes.c_byte * 16)]


class _DEVMODEW(ctypes.Structure):
    _anonymous_ = ("u",)
    _fields_ = [
        ("dmDeviceName", wintypes.WCHAR * 32),
        ("dmSpecVersion", wintypes.WORD),
        ("dmDriverVersion", wintypes.WORD),
        ("dmSize", wintypes.WORD),
        ("dmDriverExtra", wintypes.WORD),
        ("dmFields", wintypes.DWORD),
        ("u", _DEVMODE_UNION),
        ("dmColor", ctypes.c_short),
        ("dmDuplex", ctypes.c_short),
        ("dmYResolution", ctypes.c_short),
        ("dmTTOption", ctypes.c_short),
        ("dmCollate", ctypes.c_short),
        ("dmFormName", wintypes.WCHAR * 32),
        ("dmLogPixels", wintypes.WORD),
        ("dmBitsPerPel", wintypes.DWORD),
        ("dmPelsWidth", wintypes.DWORD),
        ("dmPelsHeight", wintypes.DWORD),
        ("dmDisplayFlags", wintypes.DWORD),
        ("dmDisplayFrequency", wintypes.DWORD),
        ("dmICMMethod", wintypes.DWORD),
        ("dmICMIntent", wintypes.DWORD),
        ("dmMediaType", wintypes.DWORD),
        ("dmDitherType", wintypes.DWORD),
        ("dmReserved1", wintypes.DWORD),
        ("dmReserved2", wintypes.DWORD),
        ("dmPanningWidth", wintypes.DWORD),
        ("dmPanningHeight", wintypes.DWORD),
    ]


class _DISPLAY_DEVICEW(ctypes.Structure):
    _fields_ = [
        ("cb", wintypes.DWORD),
        ("DeviceName", wintypes.WCHAR * 32),
        ("DeviceString", wintypes.WCHAR * 128),
        ("StateFlags", wintypes.DWORD),
        ("DeviceID", wintypes.WCHAR * 128),
        ("DeviceKey", wintypes.WCHAR * 128),
    ]


def collect_monitor_info() -> list[dict]:
    """Read active resolution/current Hz and the highest driver-listed Hz."""
    if os.name != "nt":
        return []
    user32 = ctypes.windll.user32
    enum_current = -1
    attached = 0x00000001
    monitors = []
    adapter_index = 0
    while True:
        adapter = _DISPLAY_DEVICEW()
        adapter.cb = ctypes.sizeof(_DISPLAY_DEVICEW)
        if not user32.EnumDisplayDevicesW(None, adapter_index, ctypes.byref(adapter), 0):
            break
        adapter_index += 1
        if not (adapter.StateFlags & attached):
            continue
        current = _DEVMODEW()
        current.dmSize = ctypes.sizeof(_DEVMODEW)
        if not user32.EnumDisplaySettingsW(adapter.DeviceName, enum_current, ctypes.byref(current)):
            continue
        width = int(current.dmPelsWidth or 0)
        height = int(current.dmPelsHeight or 0)
        current_hz = int(current.dmDisplayFrequency or 0)
        if current_hz <= 1:
            current_hz = 0
        max_same = current_hz
        max_overall = current_hz
        mode_index = 0
        while mode_index < 4096:
            mode = _DEVMODEW()
            mode.dmSize = ctypes.sizeof(_DEVMODEW)
            if not user32.EnumDisplaySettingsW(adapter.DeviceName, mode_index, ctypes.byref(mode)):
                break
            mode_index += 1
            hz = int(mode.dmDisplayFrequency or 0)
            if hz <= 1 or hz > 1000:
                continue
            max_overall = max(max_overall, hz)
            if int(mode.dmPelsWidth) == width and int(mode.dmPelsHeight) == height:
                max_same = max(max_same, hz)
        friendly = str(adapter.DeviceString or adapter.DeviceName).strip()
        monitor_device = _DISPLAY_DEVICEW()
        monitor_device.cb = ctypes.sizeof(_DISPLAY_DEVICEW)
        if user32.EnumDisplayDevicesW(adapter.DeviceName, 0, ctypes.byref(monitor_device), 0):
            candidate = str(monitor_device.DeviceString or "").strip()
            if candidate and candidate.casefold() not in ("generic pnp monitor", "genel pnp monitör"):
                friendly = candidate
        max_warning = max_same or max_overall
        monitors.append({
            "device": str(adapter.DeviceName),
            "name": friendly or f"Monitör {len(monitors) + 1}",
            "width": width,
            "height": height,
            "current_hz": current_hz,
            "max_hz": max_same,
            "max_overall_hz": max_overall,
            "underclocked": bool(current_hz and max_warning and current_hz + 2 < max_warning),
        })
    return monitors


def _first_existing_file(candidates) -> Path | None:
    for raw in candidates:
        if not raw:
            continue
        try:
            candidate = Path(os.path.expandvars(str(raw))).expanduser()
            if candidate.is_file():
                return candidate.resolve()
        except Exception:
            continue
    return None


def _running_game_paths() -> dict[str, str]:
    result = {}
    if not psutil:
        return result
    try:
        for proc in psutil.process_iter(["name", "exe", "cmdline"]):
            try:
                name = str(proc.info.get("name") or "").casefold()
                exe = str(proc.info.get("exe") or "")
                cmd = " ".join(str(v) for v in (proc.info.get("cmdline") or [])).casefold()
                if name == "robloxplayerbeta.exe":
                    result["roblox"] = exe
                elif name in ("valorant-win64-shipping.exe", "valorant.exe"):
                    result["valorant"] = exe
                elif name == "cs2.exe":
                    result["cs2"] = exe
                elif name.startswith("fortniteclient-win64-shipping"):
                    result["fortnite"] = exe
                elif name in ("minecraft.exe", "minecraftlauncher.exe") or (name in ("java.exe", "javaw.exe") and "minecraft" in cmd):
                    result.setdefault("minecraft", exe)
            except Exception:
                continue
    except Exception:
        pass
    return result


def _steam_library_paths() -> list[Path]:
    roots = []
    candidates = [
        Path(os.environ.get("PROGRAMFILES(X86)", r"C:\Program Files (x86)")) / "Steam",
        Path(os.environ.get("PROGRAMFILES", r"C:\Program Files")) / "Steam",
    ]
    try:
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Valve\Steam") as key:
            value, _ = winreg.QueryValueEx(key, "SteamPath")
            candidates.insert(0, Path(str(value)))
    except Exception:
        pass
    for root in candidates:
        if root.exists() and root not in roots:
            roots.append(root)
        vdf = root / "steamapps" / "libraryfolders.vdf"
        if not vdf.is_file():
            continue
        try:
            data = vdf.read_text(encoding="utf-8", errors="ignore")
            for match in re.finditer(r'"path"\s+"([^"]+)"', data, flags=re.I):
                lib = Path(match.group(1).replace("\\\\", "\\"))
                if lib.exists() and lib not in roots:
                    roots.append(lib)
        except Exception:
            pass
    return roots


def _riot_valorant_paths() -> tuple[Path | None, Path | None]:
    local = Path(os.environ.get("LOCALAPPDATA", ""))
    program_data = Path(os.environ.get("PROGRAMDATA", r"C:\ProgramData"))
    roots = []
    riot_json = program_data / "Riot Games" / "RiotClientInstalls.json"
    if riot_json.is_file():
        try:
            raw = json.loads(riot_json.read_text(encoding="utf-8", errors="ignore"))
            mapping = raw.get("associated_client") or {}
            if isinstance(mapping, dict):
                for game_path in mapping.keys():
                    if "valorant" in str(game_path).casefold():
                        p = Path(str(game_path).replace("/", os.sep))
                        roots.append(p.parent if p.suffix else p)
        except Exception:
            pass
    for drive in ("C", "D", "E", "F"):
        roots.append(Path(f"{drive}:\\Riot Games\\VALORANT\\live"))
    roots.extend([
        local / "Riot Games" / "VALORANT" / "live",
        Path(os.environ.get("PROGRAMFILES", r"C:\Program Files")) / "Riot Games" / "VALORANT" / "live",
    ])
    for root in roots:
        try:
            if root.name.casefold() != "live" and (root / "live").exists():
                root = root / "live"
            launch = _first_existing_file([root / "VALORANT.exe"])
            profile = _first_existing_file([
                root / "ShooterGame" / "Binaries" / "Win64" / "VALORANT-Win64-Shipping.exe",
                launch,
            ])
            if profile or launch:
                return profile, launch or profile
        except Exception:
            continue
    return None, None


def _epic_fortnite_path() -> Path | None:
    manifest_root = Path(os.environ.get("PROGRAMDATA", r"C:\ProgramData")) / "Epic" / "EpicGamesLauncher" / "Data" / "Manifests"
    if manifest_root.is_dir():
        for item in manifest_root.glob("*.item"):
            try:
                raw = json.loads(item.read_text(encoding="utf-8", errors="ignore"))
                identity = " ".join(str(raw.get(k) or "") for k in ("DisplayName", "AppName", "CatalogItemId")).casefold()
                if "fortnite" not in identity:
                    continue
                root = Path(str(raw.get("InstallLocation") or ""))
                candidate = _first_existing_file([
                    root / str(raw.get("LaunchExecutable") or ""),
                    root / "FortniteGame" / "Binaries" / "Win64" / "FortniteClient-Win64-Shipping.exe",
                ])
                if candidate:
                    return candidate
            except Exception:
                continue
    for drive in ("C", "D", "E", "F"):
        candidate = _first_existing_file([
            Path(f"{drive}:\\Program Files\\Epic Games\\Fortnite\\FortniteGame\\Binaries\\Win64\\FortniteClient-Win64-Shipping.exe"),
            Path(f"{drive}:\\Epic Games\\Fortnite\\FortniteGame\\Binaries\\Win64\\FortniteClient-Win64-Shipping.exe"),
        ])
        if candidate:
            return candidate
    return None


def detect_installed_games() -> list[dict]:
    running = _running_game_paths()
    local = Path(os.environ.get("LOCALAPPDATA", ""))
    appdata = Path(os.environ.get("APPDATA", ""))
    program_files = Path(os.environ.get("PROGRAMFILES", r"C:\Program Files"))
    program_files_x86 = Path(os.environ.get("PROGRAMFILES(X86)", r"C:\Program Files (x86)"))

    roblox_candidates = []
    versions = local / "Roblox" / "Versions"
    if versions.is_dir():
        try:
            roblox_candidates = sorted(versions.glob("version-*/RobloxPlayerBeta.exe"), key=lambda p: p.stat().st_mtime, reverse=True)
        except Exception:
            roblox_candidates = list(versions.glob("version-*/RobloxPlayerBeta.exe"))
    roblox = _first_existing_file([running.get("roblox"), *roblox_candidates])

    valorant_profile, valorant_launch = _riot_valorant_paths()
    if running.get("valorant"):
        valorant_profile = _first_existing_file([running.get("valorant")]) or valorant_profile

    cs2 = _first_existing_file([running.get("cs2")])
    if not cs2:
        for library in _steam_library_paths():
            cs2 = _first_existing_file([library / "steamapps" / "common" / "Counter-Strike Global Offensive" / "game" / "bin" / "win64" / "cs2.exe"])
            if cs2:
                break

    minecraft = _first_existing_file([
        running.get("minecraft"),
        program_files_x86 / "Minecraft Launcher" / "MinecraftLauncher.exe",
        program_files / "Minecraft Launcher" / "MinecraftLauncher.exe",
        local / "Programs" / "Minecraft Launcher" / "MinecraftLauncher.exe",
        appdata / ".minecraft" / "TLauncher.exe",
        Path.home() / "Desktop" / "TLauncher.exe",
    ])

    fortnite = _first_existing_file([running.get("fortnite")]) or _epic_fortnite_path()

    definitions = [
        ("roblox", "Roblox", "R", "ACCENT_2", roblox, roblox, "file"),
        ("valorant", "Valorant", "V", "RED", valorant_profile, valorant_launch or valorant_profile, "file"),
        ("cs2", "Counter-Strike 2", "CS2", "GOLD", cs2, "steam://rungameid/730", "uri"),
        ("minecraft", "Minecraft", "MC", "GREEN", minecraft, minecraft, "file"),
        ("fortnite", "Fortnite", "F", "ACCENT", fortnite, "com.epicgames.launcher://apps/Fortnite?action=launch&silent=true", "uri"),
    ]
    results = []
    for game_id, name, icon, accent, profile, launch, launch_kind in definitions:
        results.append({
            "id": game_id,
            "name": name,
            "icon": icon,
            "accent": accent,
            "found": bool(profile),
            "running": game_id in running,
            "path": str(profile) if profile else "",
            "launch_target": str(launch) if launch else "",
            "launch_kind": launch_kind,
        })
    return results


def _read_active_power_plan() -> dict:
    output = run_text_command(["powercfg.exe", "/getactivescheme"], timeout=6)
    name_match = re.search(r"\(([^)]+)\)", output)
    return {"raw": output, "name": name_match.group(1).strip() if name_match else (output.strip() or "Okunamadı")}


def _trim_status() -> dict:
    output = run_text_command(["fsutil.exe", "behavior", "query", "DisableDeleteNotify"], timeout=8)
    lines = [line.strip() for line in output.splitlines() if line.strip()]
    line = next((item for item in lines if "NTFS" in item.upper()), lines[0] if lines else "")
    return {
        "enabled": bool(re.search(r"=\s*0(?:\s|$)", line)),
        "disabled": bool(re.search(r"=\s*1(?:\s|$)", line)),
        "raw": line or "Okunamadı",
    }


def _display_driver_info() -> list[dict]:
    script = r"""
$ErrorActionPreference = 'SilentlyContinue'
$items = @(Get-CimInstance Win32_PnPSignedDriver | Where-Object { $_.DeviceClass -eq 'DISPLAY' } | ForEach-Object {
    [PSCustomObject]@{
        Name = $_.DeviceName
        Version = $_.DriverVersion
        Manufacturer = $_.Manufacturer
        Date = if ($_.DriverDate) { $_.DriverDate.ToString('yyyy-MM-dd') } else { '' }
    }
})
$items | ConvertTo-Json -Depth 4 -Compress
"""
    output = run_text_command([
        "powershell.exe", "-NoLogo", "-NoProfile", "-NonInteractive",
        "-ExecutionPolicy", "Bypass", "-Command", script,
    ], timeout=15)
    if not output:
        return []
    try:
        raw = json.loads(output)
        return raw if isinstance(raw, list) else ([raw] if isinstance(raw, dict) else [])
    except Exception:
        return []


def _gpu_preference_for_exe(exe_path: str) -> int | None:
    if not exe_path:
        return None
    try:
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Microsoft\DirectX\UserGpuPreferences") as key:
            value, _ = winreg.QueryValueEx(key, str(exe_path))
        match = re.search(r"GpuPreference\s*=\s*([012])", str(value), flags=re.I)
        return int(match.group(1)) if match else None
    except Exception:
        return None


def collect_one_click_checks(monitors: list[dict], games: list[dict], xmp: dict | None = None) -> list[dict]:
    checks = []
    xmp = xmp or memory_profile_info()
    if xmp.get("ok"):
        configured = int(xmp.get("configured_mhz") or 0)
        rated = int(xmp.get("rated_mhz") or 0)
        if xmp.get("mixed"):
            checks.append({"level": "warning", "title": "RAM / XMP", "detail": "Karışık RAM modülleri algılandı; XMP/DOCP kararlılığı BIOS'tan doğrulanmalı."})
        elif rated >= 2800 and configured and configured + 200 < rated:
            checks.append({"level": "bad", "title": "RAM / XMP", "detail": f"RAM {configured} MHz çalışıyor, modül {rated} MHz bildiriyor. XMP/DOCP kapalı veya hız düşürülmüş olabilir."})
        elif configured >= 2800:
            checks.append({"level": "good", "title": "RAM / XMP", "detail": f"RAM {configured} MHz çalışıyor; yüksek bellek profili etkin görünüyor."})
        else:
            checks.append({"level": "warning", "title": "RAM / XMP", "detail": f"RAM hızı {configured or 'okunamadı'} MHz. XMP/DOCP durumu BIOS'tan kesin doğrulanır."})
    else:
        checks.append({"level": "unknown", "title": "RAM / XMP", "detail": xmp.get("error", "RAM profili okunamadı.")})

    if not monitors:
        checks.append({"level": "unknown", "title": "Monitör yenileme hızı", "detail": "Aktif monitör modu okunamadı."})
    else:
        low = [m for m in monitors if m.get("underclocked")]
        if low:
            detail = "; ".join(f"{m.get('name')}: {m.get('current_hz') or '?'} Hz kullanılıyor, {m.get('max_hz') or '?'} Hz destekleniyor" for m in low)
            checks.append({"level": "bad", "title": "Monitör yanlış Hz", "detail": detail})
        else:
            detail = "; ".join(f"{m.get('name')}: {m.get('width')}×{m.get('height')} @ {m.get('current_hz') or '?'} Hz" for m in monitors)
            checks.append({"level": "good", "title": "Monitör yenileme hızı", "detail": detail})

    disk_warnings = []
    roots = []
    if os.name == "nt":
        mask = ctypes.windll.kernel32.GetLogicalDrives()
        roots = [f"{chr(65 + i)}:\\" for i in range(26) if mask & (1 << i)]
    else:
        roots = [str(Path.home().anchor or "/")]
    for root in roots:
        try:
            drive_type = ctypes.windll.kernel32.GetDriveTypeW(root) if os.name == "nt" else 3
            if drive_type != 3:
                continue
            total, used, free = shutil.disk_usage(root)
            percent = used * 100 / total if total else 0
            if percent >= 90:
                disk_warnings.append(("bad", f"{root} %{percent:.0f} dolu ({free / (1024**3):.1f} GB boş)"))
            elif percent >= 80:
                disk_warnings.append(("warning", f"{root} %{percent:.0f} dolu ({free / (1024**3):.1f} GB boş)"))
        except Exception:
            continue
    if disk_warnings:
        level = "bad" if any(item[0] == "bad" for item in disk_warnings) else "warning"
        checks.append({"level": level, "title": "Disk doluluk oranı", "detail": "; ".join(item[1] for item in disk_warnings)})
    else:
        checks.append({"level": "good", "title": "Disk doluluk oranı", "detail": "Sabit disklerde kritik doluluk algılanmadı."})

    trim = _trim_status()
    if trim["enabled"]:
        checks.append({"level": "good", "title": "SSD TRIM", "detail": "NTFS DisableDeleteNotify = 0; TRIM açık."})
    elif trim["disabled"]:
        checks.append({"level": "bad", "title": "SSD TRIM", "detail": "NTFS DisableDeleteNotify = 1; TRIM kapalı."})
    else:
        checks.append({"level": "unknown", "title": "SSD TRIM", "detail": "TRIM durumu okunamadı: " + trim["raw"]})

    power = _read_active_power_plan()
    low_name = power["name"].casefold()
    if any(token in low_name for token in ("power saver", "güç tasarrufu")):
        checks.append({"level": "bad", "title": "Güç planı", "detail": f"Aktif plan: {power['name']}. Oyun için uygun değil."})
    elif any(token in low_name for token in ("balanced", "dengeli")):
        checks.append({"level": "warning", "title": "Güç planı", "detail": f"Aktif plan: {power['name']}. T-Booster veya Yüksek Performans planı tercih edilebilir."})
    elif power["name"] == "Okunamadı":
        checks.append({"level": "unknown", "title": "Güç planı", "detail": "Aktif güç planı okunamadı."})
    else:
        checks.append({"level": "good", "title": "Güç planı", "detail": f"Aktif plan: {power['name']}"})

    drivers = _display_driver_info()
    if drivers:
        level = "good"
        details = []
        today = dt.date.today()
        for driver in drivers:
            date_text = str(driver.get("Date") or "")
            age_days = None
            try:
                age_days = (today - dt.datetime.strptime(date_text, "%Y-%m-%d").date()).days
            except Exception:
                pass
            if age_days is not None and age_days > 730:
                level = "bad"
            elif age_days is not None and age_days > 365 and level != "bad":
                level = "warning"
            suffix = f" • {age_days} gün önce" if age_days is not None else ""
            details.append(f"{driver.get('Name') or 'GPU'} • {driver.get('Version') or '?'} • {date_text or 'tarih yok'}{suffix}")
        checks.append({"level": level, "title": "Ekran kartı sürücüsü", "detail": "; ".join(details)})
    else:
        checks.append({"level": "unknown", "title": "Ekran kartı sürücüsü", "detail": "Sürücü tarihi okunamadı."})

    hw = driver_hardware_info()
    gpu_names = [str(name) for name in (hw.get("gpu_names") or [])]
    combined = " ".join(gpu_names).casefold()
    has_integrated = "intel" in combined or "radeon(tm) graphics" in combined or "vega" in combined
    has_discrete = any(token in combined for token in ("nvidia", "geforce", "rtx", "gtx", "radeon rx"))
    found_games = [g for g in games if g.get("found") and g.get("path")]
    if has_integrated and has_discrete and found_games:
        power_saving = []
        missing = []
        for game in found_games:
            pref = _gpu_preference_for_exe(str(game.get("path") or ""))
            if pref == 1:
                power_saving.append(game["name"])
            elif pref != 2:
                missing.append(game["name"])
        if power_saving:
            checks.append({"level": "bad", "title": "Oyun GPU tercihi", "detail": "Dahili / güç tasarruflu GPU'ya ayarlı: " + ", ".join(power_saving)})
        elif missing:
            running_missing = [g["name"] for g in found_games if g.get("running") and g["name"] in missing]
            if running_missing:
                checks.append({"level": "bad", "title": "Oyun GPU tercihi", "detail": "Çalışan oyunlarda yüksek performans GPU tercihi yok; dahili GPU'ya düşebilir: " + ", ".join(running_missing)})
            else:
                checks.append({"level": "warning", "title": "Oyun GPU tercihi", "detail": "Yüksek performans GPU tercihi tanımlı değil: " + ", ".join(missing)})
        else:
            checks.append({"level": "good", "title": "Oyun GPU tercihi", "detail": "Algılanan oyunlar yüksek performans GPU'ya ayarlı."})
    elif found_games:
        checks.append({"level": "good", "title": "Oyun GPU tercihi", "detail": "Hibrit GPU riski algılanmadı veya sistemde tek GPU sınıfı bulunuyor."})
    else:
        checks.append({"level": "unknown", "title": "Oyun GPU tercihi", "detail": "Kontrol edilecek kurulu oyun EXE'si bulunamadı."})
    return checks

# ---------------------------------------------------------------------------
# Antialiased (supersampled) UI shapes. Tk canvas primitives are not antialiased,
# so rounded shapes are rendered with Pillow at 4x and scaled down.
# ---------------------------------------------------------------------------
_AA_CACHE = {}


def _aa_ready():
    return Image is not None and ImageTk is not None and ImageDraw is not None and ImageFilter is not None


def _tk_rgb(widget, color):
    if not color:
        return None
    text = str(color)
    if len(text) == 7 and text[0] == "#":
        try:
            return (int(text[1:3], 16), int(text[3:5], 16), int(text[5:7], 16))
        except ValueError:
            pass
    r, g, b = widget.winfo_rgb(text)
    return (r // 257, g // 257, b // 257)


def _mix_rgb(a, b, t):
    return tuple(int(round(a[k] * (1.0 - t) + b[k] * t)) for k in range(3))


def _render_round_rect(w, h, radius, fill, outline, border_w, ss=4):
    W, H = w * ss, h * ss
    r = max(0, min(int(radius), w // 2, h // 2)) * ss
    base = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    draw = ImageDraw.Draw(base)
    if outline and border_w > 0:
        draw.rounded_rectangle((0, 0, W - 1, H - 1), r, fill=tuple(outline) + (255,))
        inset = int(border_w) * ss
        box = (inset, inset, W - 1 - inset, H - 1 - inset)
        inner_r = max(0, r - inset)
        if fill:
            draw.rounded_rectangle(box, inner_r, fill=tuple(fill) + (255,))
        else:
            hole = Image.new("L", (W, H), 0)
            ImageDraw.Draw(hole).rounded_rectangle(box, inner_r, fill=255)
            base.paste((0, 0, 0, 0), mask=hole)
    elif fill:
        draw.rounded_rectangle((0, 0, W - 1, H - 1), r, fill=tuple(fill) + (255,))
    return base.resize((w, h), Image.LANCZOS)


def _aa_round_rect_photo(w, h, radius, fill, outline, border_w):
    key = ("rr", w, h, int(radius), fill, outline, border_w if outline else 0)
    photo = _AA_CACHE.get(key)
    if photo is None:
        photo = ImageTk.PhotoImage(_render_round_rect(w, h, radius, fill, outline, border_w if outline else 0))
        _AA_CACHE[key] = photo
    return photo


def _render_toggle(acc, off, border, t, hover=False, w=66, h=36, ss=4):
    """Smooth pill switch. t=0 (off) .. 1 (on). Returns an RGBA PIL image."""
    W, H = w * ss, h * ss
    x0, y0, x1, y1 = 4 * ss, 5 * ss, (w - 4) * ss, (h - 5) * ss
    rad = (y1 - y0) // 2
    track = _mix_rgb(off, acc, t)
    edge = _mix_rgb(border, acc, t)
    canvas = Image.new("RGBA", (W, H), (0, 0, 0, 0))

    # soft glow around the track (stronger when on / hovered)
    strength = 0.85 * t + (0.20 if hover else 0.0)
    if strength > 0.03:
        glow_mask = Image.new("L", (W, H), 0)
        ImageDraw.Draw(glow_mask).rounded_rectangle((x0, y0, x1, y1), rad, fill=255)
        glow_mask = glow_mask.filter(ImageFilter.GaussianBlur(3 * ss)).point(lambda v: int(v * strength))
        glow = Image.new("RGBA", (W, H), tuple(acc) + (0,))
        glow.putalpha(glow_mask)
        canvas.alpha_composite(glow)

    draw = ImageDraw.Draw(canvas)
    draw.rounded_rectangle((x0, y0, x1, y1), rad, fill=tuple(edge) + (255,))
    inner = (x0 + ss, y0 + ss, x1 - ss, y1 - ss)
    draw.rounded_rectangle(inner, rad - ss, fill=tuple(track) + (255,))

    # glossy top highlight clipped to the track
    pill = Image.new("L", (W, H), 0)
    ImageDraw.Draw(pill).rounded_rectangle(inner, rad - ss, fill=255)
    gloss = Image.new("L", (W, H), 0)
    gdraw = ImageDraw.Draw(gloss)
    span = int((inner[3] - inner[1]) * 0.55)
    for row in range(span):
        gdraw.line((0, inner[1] + row, W, inner[1] + row), fill=int(64 * (1.0 - row / span)))
    gloss = Image.composite(gloss, Image.new("L", (W, H), 0), pill)
    canvas.paste((255, 255, 255, 255), mask=gloss)

    # knob
    cx = (19 + 28 * t) * ss
    cy = (h / 2) * ss
    kr = (11.6 if hover else 11.0) * ss
    shadow_mask = Image.new("L", (W, H), 0)
    ImageDraw.Draw(shadow_mask).ellipse((cx - kr, cy - kr + 2 * ss, cx + kr, cy + kr + 2 * ss), fill=255)
    shadow_mask = shadow_mask.filter(ImageFilter.GaussianBlur(2 * ss)).point(lambda v: int(v * 0.30))
    shadow = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    shadow.putalpha(shadow_mask)
    canvas.alpha_composite(shadow)

    draw = ImageDraw.Draw(canvas)
    draw.ellipse((cx - kr, cy - kr, cx + kr, cy + kr), fill=(211, 221, 237, 255))
    draw.ellipse((cx - kr + ss, cy - kr + ss, cx + kr - ss, cy + kr - ss), fill=(252, 253, 255, 255))
    dot = 3.4 * ss
    dot_color = _mix_rgb((190, 201, 219), acc, t)
    draw.ellipse((cx - dot, cy - dot, cx + dot, cy + dot), fill=tuple(dot_color) + (255,))
    return canvas.resize((w, h), Image.LANCZOS)


def _render_header_backdrop(width, height, bg, panel, orbs, strength=0.30, line=None):
    """Vertical gradient + soft blurred colour orbs (no hard banding)."""
    column = Image.new("RGB", (1, height))
    for y in range(height):
        amount = min(1.0, y / max(1, height - 1)) * 0.82
        column.putpixel((0, y), _mix_rgb(bg, panel, amount))
    img = column.resize((width, height), Image.NEAREST).convert("RGBA")
    for x, y, radius, color in orbs:
        mask = Image.new("L", (width, height), 0)
        r = radius * 1.15
        ImageDraw.Draw(mask).ellipse((x - r, y - r, x + r, y + r), fill=255)
        mask = mask.filter(ImageFilter.GaussianBlur(radius * 0.55)).point(lambda v: int(v * strength))
        layer = Image.new("RGBA", (width, height), tuple(color) + (0,))
        layer.putalpha(mask)
        img.alpha_composite(layer)
    if line:
        c_mid, c_edge = line
        strip = Image.new("RGBA", (width, height), tuple(c_mid) + (0,))
        sdraw = ImageDraw.Draw(strip)
        for x in range(width):
            edge = abs((x / max(1, width - 1)) * 2 - 1)
            sdraw.line((x, height - 3, x, height - 2), fill=tuple(_mix_rgb(c_mid, c_edge, edge)) + (255,))
        halo = strip.filter(ImageFilter.GaussianBlur(4))
        halo.putalpha(halo.getchannel("A").point(lambda v: int(v * 0.9)))
        img.alpha_composite(halo)
        img.alpha_composite(strip)
    return img


def _load_ui_font(size):
    if ImageFont is None:
        return None
    for name in ("seguibl.ttf", "segoeuib.ttf", "arialbd.ttf", "DejaVuSans-Bold.ttf",
                 "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"):
        try:
            return ImageFont.truetype(name, size)
        except Exception:
            continue
    return None


def _render_neon_text(text, size, color, glow, glow2=None, strength=1.0, pad=16, ss=2):
    """Glowing neon-sign text. Returns (RGBA image, pad) or None when no font is available."""
    font = _load_ui_font(size * ss)
    if font is None:
        return None
    probe = ImageDraw.Draw(Image.new("L", (1, 1)))
    left, top, right, bottom = probe.textbbox((0, 0), text, font=font)
    w = (right - left) + pad * 2 * ss
    h = (bottom - top) + pad * 2 * ss
    mask = Image.new("L", (w, h), 0)
    ImageDraw.Draw(mask).text((pad * ss - left, pad * ss - top), text, font=font, fill=255)
    out = Image.new("RGBA", (w, h), (0, 0, 0, 0))

    def add_glow(rgb, radius, gain, shift=(0, 0)):
        shifted = mask if shift == (0, 0) else Image.new("L", (w, h), 0)
        if shift != (0, 0):
            shifted.paste(mask, (shift[0] * ss, shift[1] * ss))
        blurred = shifted.filter(ImageFilter.GaussianBlur(radius * ss)).point(lambda v: min(255, int(v * gain * strength)))
        layer = Image.new("RGBA", (w, h), tuple(rgb) + (0,))
        layer.putalpha(blurred)
        out.alpha_composite(layer)

    if glow2 is not None:
        add_glow(glow2, 5, 1.5, (3, 2))
    add_glow(glow, 7, 1.8)
    add_glow(glow, 2, 1.0)
    face = Image.new("RGBA", (w, h), tuple(color) + (0,))
    face.putalpha(mask)
    out.alpha_composite(face)
    return out.resize((w // ss, h // ss), Image.LANCZOS), pad


def _render_score_ring(score, size, color, track, ss=4):
    W = size * ss
    thick = int(size * 0.10 * ss)
    margin = int(size * 0.15 * ss)
    box = (margin, margin, W - margin, W - margin)
    img = Image.new("RGBA", (W, W), (0, 0, 0, 0))
    draw = ImageDraw.Draw(img)
    draw.arc(box, 0, 360, fill=tuple(track) + (255,), width=thick)
    score = max(0, min(100, score))
    if score > 0:
        end = -90 + 3.6 * score
        glow = Image.new("RGBA", (W, W), tuple(color) + (0,))
        ImageDraw.Draw(glow).arc(box, -90, end, fill=tuple(color) + (255,), width=thick)
        halo = glow.filter(ImageFilter.GaussianBlur(int(size * 0.045 * ss)))
        img.alpha_composite(halo)
        img.alpha_composite(halo)
        draw.arc(box, -90, end, fill=tuple(color) + (255,), width=thick)
        cx = cy = W / 2
        radius = (W - 2 * margin) / 2 - thick / 2
        for angle in (-90, end):
            px = cx + radius * math.cos(math.radians(angle))
            py = cy + radius * math.sin(math.radians(angle))
            draw.ellipse((px - thick / 2, py - thick / 2, px + thick / 2, py + thick / 2), fill=tuple(color) + (255,))
    return img.resize((size, size), Image.LANCZOS)


class AnimatedToggle(tk.Canvas):
    _W, _H, _STEPS = 66, 36, 12
    _frames = {}

    def __init__(self, parent, variable: tk.BooleanVar, accent: str, off_color: str, border: str, command=None):
        super().__init__(
            parent,
            width=self._W,
            height=self._H,
            highlightthickness=0,
            bd=0,
            bg=parent.cget("bg"),
            cursor="hand2",
        )
        self.variable = variable
        self.accent = accent
        self.off_color = off_color
        self.border = border
        self.command = command
        self.t = 1.0 if variable.get() else 0.0
        self.target = self.t
        self.hover = False
        self.after_id = None
        self._photo = None
        self._aa_ok = _aa_ready()
        self.bind("<Button-1>", self._toggle)
        self.bind("<Enter>", lambda _e: self._set_hover(True))
        self.bind("<Leave>", lambda _e: self._set_hover(False))
        self.variable.trace_add("write", self._on_variable)
        self._draw()

    def _set_hover(self, value):
        self.hover = value
        self._draw()

    def _toggle(self, _event=None):
        self.variable.set(not self.variable.get())
        if self.command:
            self.command()
        return "break"

    def _on_variable(self, *_args):
        try:
            self.target = 1.0 if self.variable.get() else 0.0
            if self.after_id is None:
                self._animate()
        except tk.TclError:
            pass

    def _animate(self):
        distance = self.target - self.t
        if abs(distance) < 0.04:
            self.t = self.target
            self.after_id = None
            self._draw()
            return
        self.t += distance * 0.36
        self._draw()
        try:
            self.after_id = self.after(14, self._animate)
        except tk.TclError:
            self.after_id = None

    def _frame(self, step, hover):
        acc = _tk_rgb(self, self.accent)
        off = _tk_rgb(self, self.off_color)
        border = _tk_rgb(self, self.border)
        key = (acc, off, border, step, hover)
        photo = AnimatedToggle._frames.get(key)
        if photo is None:
            photo = ImageTk.PhotoImage(_render_toggle(acc, off, border, step / self._STEPS, hover, self._W, self._H))
            AnimatedToggle._frames[key] = photo
        return photo

    def _draw(self):
        try:
            self.delete("all")
            if self._aa_ok:
                try:
                    step = int(round(max(0.0, min(1.0, self.t)) * self._STEPS))
                    self._photo = self._frame(step, self.hover)
                    self.create_image(self._W // 2, self._H // 2, image=self._photo)
                    return
                except Exception:
                    self._aa_ok = False
                    self.delete("all")
            self._draw_fallback()
        except tk.TclError:
            pass

    # ---- plain canvas fallback (used only when Pillow is unavailable)
    def _rounded_track(self, x1, y1, x2, y2, fill, outline, width=1):
        r = (y2 - y1) / 2
        self.create_rectangle(x1 + r, y1, x2 - r, y2, fill=fill, outline="")
        self.create_oval(x1, y1, x1 + 2 * r, y2, fill=fill, outline="")
        self.create_oval(x2 - 2 * r, y1, x2, y2, fill=fill, outline="")
        if outline:
            self.create_arc(x1, y1, x1 + 2 * r, y2, start=90, extent=180, style="arc", outline=outline, width=width)
            self.create_arc(x2 - 2 * r, y1, x2, y2, start=270, extent=180, style="arc", outline=outline, width=width)
            self.create_line(x1 + r, y1, x2 - r, y1, fill=outline, width=width)
            self.create_line(x1 + r, y2, x2 - r, y2, fill=outline, width=width)

    def _draw_fallback(self):
        on = self.variable.get()
        pos = 19 + 28 * self.t
        self._rounded_track(4, 6, 62, 30, fill=self.accent if on else self.off_color, outline=self.accent if on else self.border, width=1)
        self.create_oval(pos - 11, 7, pos + 11, 29, fill="#ffffff", outline="#d9e2f2")


