    @staticmethod
    def _mix(c1, c2, amount):
        a = tuple(int(c1[i:i+2], 16) for i in (1, 3, 5)); b = tuple(int(c2[i:i+2], 16) for i in (1, 3, 5))
        rgb = tuple(round(a[i] + (b[i] - a[i]) * amount) for i in range(3))
        return "#{:02x}{:02x}{:02x}".format(*rgb)

