    def _load_scaled_asset(self, path, size, cache_key):
        cached = self.asset_cache.get(cache_key)
        if cached is not None:
            return cached
        if not Path(path).exists():
            return None
        try:
            if Image is not None and ImageTk is not None:
                img = Image.open(path).convert("RGBA")
                ratio = min(size / max(1, img.width), size / max(1, img.height))
                new_size = (max(1, int(img.width * ratio)), max(1, int(img.height * ratio)))
                img = img.resize(new_size, Image.LANCZOS)
                photo = ImageTk.PhotoImage(img)
            else:
                original = tk.PhotoImage(file=str(path))
                x_factor = max(1, round(original.width() / size))
                y_factor = max(1, round(original.height() / size))
                photo = original.subsample(x_factor, y_factor)
            self.asset_cache[cache_key] = photo
            return photo
        except Exception as exc:
            core.log_line(f"Görsel ölçekleme hatası ({Path(path).name}): {exc}")
            return None

