    def switch_theme(self, theme_name):
        self.theme_name = theme_name; self.palette = dict(self.DARK if theme_name == "dark" else self.LIGHT); self._rebuild_ui()

    def animate_open(self):
        if self.open_step == 0:
            self.root.update_idletasks(); sw = self.root.winfo_screenwidth(); sh = self.root.winfo_screenheight(); self.target_w = min(1280, sw - 60); self.target_h = min(860, sh - 80); self.target_x = max((sw - self.target_w)//2, 10); self.target_y = max((sh - self.target_h)//2, 10)
        self.open_step += 1; ratio = min(1.0, self.open_step / 14.0); eased = 1 - (1-ratio) ** 3
        width = int(1020 + (self.target_w - 1020) * eased); height = int(690 + (self.target_h - 690) * eased)
        self.root.geometry(f"{width}x{height}+{self.target_x}+{self.target_y}")
        try: self.root.attributes("-alpha", max(0.05, ratio))
        except Exception: pass
        if ratio < 1.0: self.root.after(14, self.animate_open)
        else:
            self.root.lift(); self.root.focus_force()

    def animate_close(self):
        if self.closing: return
        try:
            v49tools.stop_active_session()
        except Exception as exc:
            core.log_line(f"Oyun oturumu kapanış temizliği: {exc}")
        try:
            v50tools.stop_presentmon_capture()
        except Exception as exc:
            core.log_line(f"PresentMon kapanış temizliği: {exc}")
        self.closing = True; self.close_step = 12
        def step():
            self.close_step -= 1; ratio = max(0.0, self.close_step / 12.0)
            try: self.root.attributes("-alpha", ratio)
            except Exception: pass
            if self.close_step > 0: self.root.after(12, step)
            else: self.root.destroy()
        step()

