    def _header_backdrop(self, canvas, width, height):
        if not _aa_ready():
            return None
        try:
            bucket = ((width + 63) // 64) * 64
            cache = self.__dict__.setdefault("_aa_header_cache", {})
            key = (self.theme_name, bucket, height)
            photo = cache.get(key)
            if photo is None:
                bg = _tk_rgb(canvas, self.palette["BG"])
                panel = _tk_rgb(canvas, self.palette["PANEL"])
                acc = _tk_rgb(canvas, self.palette["ACCENT"])
                acc2 = _tk_rgb(canvas, self.palette["ACCENT_2"])
                pink = _tk_rgb(canvas, self.palette["PINK"])
                orbs = [(70, 30, 110, acc2), (330, -10, 90, pink), (bucket - 90, 20, 140, acc)]
                if len(cache) > 8:
                    cache.clear()
                photo = ImageTk.PhotoImage(_render_header_backdrop(bucket, height, bg, panel, orbs, 0.34 if self.theme_name == "dark" else 0.22, line=(acc, pink)))
                cache[key] = photo
            return photo
        except Exception:
            return None

    def _neon_title(self, canvas):
        if not _aa_ready() or ImageFont is None:
            return None
        cache = self.__dict__.setdefault("_aa_title_cache", {})
        key = ("title", self.theme_name)
        if key in cache:
            return cache[key]
        try:
            dark = self.theme_name == "dark"
            face = _mix_rgb(_tk_rgb(canvas, self.palette["ACCENT"]), (255, 255, 255), 0.82) if dark else _tk_rgb(canvas, self.palette["TEXT"])
            glow = _tk_rgb(canvas, self.palette["ACCENT"] if dark else self.palette["ACCENT_2"])
            glow2 = _tk_rgb(canvas, self.palette["PINK"])
            rendered = _render_neon_text("T-BOOSTER", 38, face, glow, glow2, 1.0 if dark else 0.55)
            if rendered is None:
                return None
            image, pad = rendered
            cache[key] = (ImageTk.PhotoImage(image), pad)
            return cache[key]
        except Exception:
            return None

    def _draw_header(self, canvas):
        canvas.delete("all")
        width = max(1100, canvas.winfo_width() or 1100)
        height = 112
        backdrop = self._header_backdrop(canvas, width, height)
        if backdrop is not None:
            canvas.create_image(0, 0, anchor="nw", image=backdrop)
        else:
            for y in range(height):
                amount = min(1.0, y / max(1, height - 1))
                canvas.create_line(0, y, width, y, fill=self._mix(self.palette["BG"], self.palette["PANEL"], amount * 0.82))

            for x, y, radius, color in (
                (45, 18, 92, self.palette["ACCENT"]),
                (290, -5, 70, self.palette["ACCENT_2"]),
                (width - 70, 12, 110, self.palette["ACCENT"]),
            ):
                for index in range(3):
                    rr = radius + index * 18
                    fill = self._mix(color, self.palette["BG"], 0.70 + index * 0.08)
                    canvas.create_oval(x - rr, y - rr, x + rr, y + rr, fill=fill, outline="")

        canvas.create_line(0, height - 1, width, height - 1, fill=self.palette["BORDER"], width=1)
