    def _load_fixed_gpu_icon(self, path, cache_name):
        cached = getattr(self, cache_name, None)
        if cached is not None:
            return cached
        image = self._load_scaled_asset(path, 28, (cache_name, self.theme_name))
        if image is None:
            return None
        setattr(self, cache_name, image)
        return image

