        border = accent if active else self._mix(accent, self.palette["BORDER"], 0.42 if hover else 0.72)
        fill = self._mix(accent, self.palette["PANEL_2"], 0.90 if not is_hot else 0.82)
        shadow = self._mix(self.palette["BG"], self.palette["PANEL"], 0.18)

        self._round_rect(canvas, 3, 5, width - 3, height - 2, 16, fill=shadow, outline="")
        if is_hot:
            self._round_rect(canvas, 1, 2, width - 2, height - 2, 18, fill="", outline=self._mix(accent, self.palette["PANEL"], 0.62 if active else 0.76), width=2)
        self._round_rect(canvas, 2, 3, width - 4, height - 4, 16, fill=fill, outline=border, width=2 if active else 1)
