    def _sidebar_card(self, parent, icon, text, accent, command, active=False, page_key=None):
        frame = tk.Frame(parent, bg=self.palette["PANEL"], cursor="hand2")
        frame.pack(fill="x", padx=10, pady=3)
        canvas = tk.Canvas(frame, height=62, bg=self.palette["PANEL"], highlightthickness=0, bd=0, cursor="hand2")
        canvas.pack(fill="x", expand=True)
        state = {"hover": False}

        def render(_event=None):
            is_active = (self.current_page == page_key) if page_key else active
            self._draw_sidebar_card(canvas, icon, text, accent, hover=state["hover"], active=is_active)

        def on_enter(_event=None):
            state["hover"] = True
            render()

        def on_leave(_event=None):
            state["hover"] = False
            render()

        for widget in (frame, canvas):
            widget.bind("<Enter>", on_enter, add="+")
            widget.bind("<Leave>", on_leave, add="+")
            widget.bind("<Button-1>", lambda _e: command(), add="+")
        canvas.bind("<Configure>", render, add="+")
        if page_key:
            self.sidebar_renderers.append(render)
        render()
        self._refresh_sidebar_layout()
        return frame

    def _sidebar_btn(self, parent, icon, text, page, accent=None):
        accent = accent or self.palette["ACCENT"]
        return self._sidebar_card(parent, icon, text, accent, lambda: self.show_page(page), page_key=page)

    def _sidebar_action(self, parent, icon, text, command, accent=None):
        accent = accent or self.palette["ACCENT"]
        return self._sidebar_card(parent, icon, text, accent, command, active=False)

    def _roblox_player_running(self):
        process_names = {"robloxplayerbeta.exe", "robloxplayerlauncher.exe", "windows10universal.exe"}
        if psutil:
            try:
                for process in psutil.process_iter(["name"]):
                    if str(process.info.get("name") or "").casefold() in process_names:
                        return True
            except Exception:
                pass
        output = run_text_command(["tasklist.exe", "/FO", "CSV", "/NH"], timeout=6).casefold()
        return any(name in output for name in process_names)

    def unlock_roblox_fps(self):
        try:
            if self._roblox_player_running():
                close_now = messagebox.askyesno(
                    "Roblox açık",
                    "Roblox şu anda açık. Oyun açıkken dosya tekrar eski değere dönebilir.\n\n"
                    "Roblox'u şimdi kapatıp FPS kilidini kaldırayım mı?",
                    parent=self.root,
                )
                if not close_now:
                    self.status_var.set("Roblox FPS işlemi iptal edildi — önce oyunu kapat.")
                    return
                for image_name in ("RobloxPlayerBeta.exe", "RobloxPlayerLauncher.exe", "Windows10Universal.exe"):
                    try:
                        flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
                        subprocess.run(
                            ["taskkill.exe", "/F", "/IM", image_name],
                            capture_output=True,
                            timeout=6,
                            creationflags=flags,
                            errors="ignore",
                        )
                    except Exception:
                        pass
                time.sleep(0.8)

            result = set_roblox_framerate_cap(9999)
            old_value = result.get("old_cap")
            self.status_var.set("Roblox FPS sınırı 9999 olarak ayarlandı.")
            self._append_log(
                f"ROBLOX FPS: FramerateCap {old_value} -> 9999 | Yedek: {result.get('backup')}"
            )
            messagebox.showinfo(
                "Roblox FPS Kilidi Kaldırıldı",
                "Roblox FPS sınırı başarıyla 9999 yapıldı.\n\n"
                f"Eski değer: {old_value}\n"
                f"Dosya: {result.get('path')}\n\n"
                "Roblox'u yeniden açabilirsin. Ekran kartı sürücüsünde ayrıca FPS sınırı varsa onu da kapatman gerekir.",
                parent=self.root,
            )
        except FileNotFoundError as exc:
            self.status_var.set("Roblox ayar dosyası bulunamadı.")
            self._append_log(f"ROBLOX FPS DOSYA HATASI: {exc}")
            messagebox.showwarning("Roblox Ayarı Bulunamadı", str(exc), parent=self.root)
        except Exception as exc:
            self.status_var.set("Roblox FPS sınırı değiştirilemedi.")
            self._append_log(f"ROBLOX FPS HATASI: {exc}")
            messagebox.showerror(
                "Roblox FPS Hatası",
                f"FPS sınırı değiştirilemedi:\n{exc}",
                parent=self.root,
            )

    def _bind_global_mousewheel(self):
        self.root.bind_all("<MouseWheel>", self._on_global_mousewheel, add="+")
        self.root.bind_all("<Button-4>", self._on_global_mousewheel, add="+")
        self.root.bind_all("<Button-5>", self._on_global_mousewheel, add="+")

    def _is_descendant(self, widget, ancestor):
        current = widget
        while current is not None:
            if current == ancestor:
                return True
            try:
                parent_name = current.winfo_parent()
            except Exception:
                return False
            if not parent_name:
                return False
            try:
                current = current._nametowidget(parent_name)
            except Exception:
                return False
        return False

    def _mousewheel_units(self, event):
        if getattr(event, "num", None) == 4:
            return -3
        if getattr(event, "num", None) == 5:
            return 3
        delta = int(getattr(event, "delta", 0))
        if delta == 0:
            return 0
        steps = max(1, abs(delta) // 120)
        return -steps if delta > 0 else steps

    def _on_global_mousewheel(self, event):
        try:
            units = self._mousewheel_units(event)
            if units == 0:
                return
            hovered = self.root.winfo_containing(event.x_root, event.y_root)
            target = None
            if hovered is not None and hasattr(self, "sidebar_canvas") and self._is_descendant(hovered, self.sidebar_shell):
                target = self.sidebar_canvas
            else:
                target = self.scroll_canvases.get(self.current_page)
            if target is None or not target.winfo_exists():
                return
            target.yview_scroll(units, "units")
            return "break"
        except Exception:
            return

