    def show_page(self, page_name, animate=True):
        self.current_page = page_name
        titles = {
            "dashboard": "Kontrol Merkezi",
            "gaming": "Oyun Modu",
            "windows": "Windows Ayarları",
            "drivers": "Sürücü Merkezi",
            "tools": "Performans Araçları",
            "smartscan": "Sistemi Tara",
            "diskinfo": "T-Booster Disk Info",
            "v50": "T-Booster FPS LAB",
            "toolbox": "Neon Araç Kutusu",
            "tweak100": "T-Booster 200 Tweak Paketi",
            "xmp": "D.O.C.P. / XMP Asistanı",
            "restore": "Geri Alma Merkezi",
            "logs": "İşlem Günlüğü",
        }
        self.page_title_var.set(titles.get(page_name, "T-Booster"))
        for renderer in list(getattr(self, "sidebar_renderers", [])):
            try:
                renderer()
            except Exception:
                pass
        for page in self.pages.values(): page.place_forget()
        page = self.pages[page_name]; start_x = 24 if animate else 0; page.place(x=start_x, y=0, relwidth=1, relheight=1)
        if animate:
            state = {"x": start_x}
            def slide():
                state["x"] = int(state["x"] * 0.58); page.place_configure(x=state["x"])
                if state["x"] > 0: self.root.after(12, slide)
            slide()

