    def open_advanced_display_settings(self):
        try:
            if hasattr(os, "startfile"):
                os.startfile("ms-settings:display-advanced")
            else:
                subprocess.Popen(["explorer.exe", "ms-settings:display-advanced"])
            self.status_var.set("Windows gelişmiş görüntü ayarları açıldı.")
        except Exception as exc:
            messagebox.showerror(APP_NAME, f"Görüntü ayarları açılamadı:\n{exc}", parent=self.root)

    def start_smart_scan(self):
        if self.smart_scan_busy:
            self.smart_scan_status_var.set("Tarama zaten devam ediyor…")
            return
        self.smart_scan_busy = True
        self.smart_scan_status_var.set("Monitör, oyun yolları ve sistem ayarları taranıyor…")
        self.status_var.set("T-Booster Akıllı Sistem Taraması çalışıyor…")
        threading.Thread(target=self._smart_scan_worker, daemon=True).start()

    def _smart_scan_worker(self):
        try:
            monitors = collect_monitor_info()
            games = detect_installed_games()
            xmp = memory_profile_info()
            checks = collect_one_click_checks(monitors, games, xmp)
            self.events.put(("smart_scan_done", {"monitors": monitors, "games": games, "xmp": xmp, "checks": checks}))
        except Exception as exc:
            core.log_line(traceback.format_exc())
            self.events.put(("smart_scan_error", str(exc)))

    def _clear_dynamic_body(self, body):
        if body is None or not body.winfo_exists():
            return False
        for child in body.winfo_children():
            child.destroy()
        return True

    def _render_monitor_cards(self, monitors):
        body = self.monitor_cards_body
        if not self._clear_dynamic_body(body):
            return
        if not monitors:
            tk.Label(body, text="Aktif monitör bilgisi henüz okunmadı.", bg=self.palette["PANEL"], fg=self.palette["MUTED"], font=("Segoe UI", 9), pady=10).pack(fill="x")
            self._mini_action(body, "🖥 GELİŞMİŞ GÖRÜNTÜ AYARLARINI AÇ", self.open_advanced_display_settings, self.palette["ACCENT_2"])
            return
        for index, monitor in enumerate(monitors, start=1):
            bad = bool(monitor.get("underclocked"))
            accent = self.palette["RED"] if bad else self.palette["GREEN"]
            card = tk.Frame(body, bg=self.palette["PANEL_2"], highlightbackground=accent, highlightthickness=1)
            card.pack(fill="x", pady=5)
            left = tk.Frame(card, bg=self.palette["PANEL_2"])
            left.pack(side="left", fill="x", expand=True, padx=12, pady=10)
            tk.Label(left, text=f"🖥 {monitor.get('name') or f'Monitör {index}'}", bg=self.palette["PANEL_2"], fg=self.palette["TEXT"], font=("Segoe UI Semibold", 10, "bold")).pack(anchor="w")
            resolution = f"{monitor.get('width') or '?'} × {monitor.get('height') or '?'}"
            current_hz = monitor.get("current_hz") or "?"
            max_hz = monitor.get("max_hz") or monitor.get("max_overall_hz") or "?"
            detail = f"Aktif: {resolution} @ {current_hz} Hz  •  Aynı çözünürlükte desteklenen en yüksek: {max_hz} Hz"
            tk.Label(left, text=detail, bg=self.palette["PANEL_2"], fg=self.palette["MUTED"], font=("Segoe UI", 9), wraplength=700, justify="left").pack(anchor="w", pady=(3, 0))
            tk.Label(card, text="YANLIŞ HZ" if bad else "HZ UYGUN", bg=self.palette["PANEL_2"], fg=accent, font=("Segoe UI Semibold", 9, "bold"), padx=10).pack(side="right", padx=10)
        self._mini_action(body, "🖥 GELİŞMİŞ GÖRÜNTÜ AYARLARINI AÇ", self.open_advanced_display_settings, self.palette["ACCENT_2"])

    def _select_detected_game(self, game, show_message=True):
        path = str(game.get("path") or "")
        if not path or not Path(path).is_file():
            if show_message:
                messagebox.showwarning("Oyun Bulunamadı", f"{game.get('name')} için kullanılabilir EXE bulunamadı.", parent=self.root)
            return False
        self.game_exe_var.set(path)
        self.game_status_var.set(f"Otomatik seçildi: {game.get('name')} — {Path(path).name}")
        self.status_var.set(f"{game.get('name')} T-Booster oyun araçları için seçildi.")
        self._append_log(f"OTOMATİK OYUN SEÇİMİ: {game.get('name')} | {path}")
        if show_message:
            messagebox.showinfo("Oyun Seçildi", f"{game.get('name')} T-Booster için seçildi.\n\n{path}", parent=self.root)
        return True

    def _open_detected_game(self, game):
        if not game.get("found"):
            messagebox.showwarning("Oyun Bulunamadı", f"{game.get('name')} bu bilgisayarda otomatik bulunamadı.", parent=self.root)
            return
        target = str(game.get("launch_target") or game.get("path") or "")
        try:
            self._select_detected_game(game, show_message=False)
            if game.get("launch_kind") == "uri":
                os.startfile(target)
            elif Path(target).is_file():
                subprocess.Popen([target], cwd=str(Path(target).parent))
            else:
                raise FileNotFoundError(target)
            self.status_var.set(f"{game.get('name')} başlatılıyor…")
            self._append_log(f"OYUN BAŞLATILDI: {game.get('name')} | {target}")
        except Exception as exc:
            messagebox.showerror("Oyun Başlatılamadı", f"{game.get('name')} açılamadı:\n{exc}", parent=self.root)

    def _render_game_cards(self, games):
        body = self.game_cards_body
        if not self._clear_dynamic_body(body):
            return
        if not games:
            tk.Label(body, text="Oyun taraması henüz tamamlanmadı.", bg=self.palette["PANEL"], fg=self.palette["MUTED"], font=("Segoe UI", 9), pady=10).pack(fill="x")
            return
        grid = tk.Frame(body, bg=self.palette["PANEL"])
        grid.pack(fill="x")
        for column in range(2):
            grid.grid_columnconfigure(column, weight=1, uniform="games")
        for index, game in enumerate(games):
            found = bool(game.get("found"))
            accent = self.palette.get(str(game.get("accent") or "ACCENT"), self.palette["ACCENT"])
            if not found:
                accent = self.palette["MUTED"]
            card = tk.Frame(grid, bg=self.palette["PANEL_2"], highlightbackground=accent, highlightthickness=1)
            card.grid(row=index // 2, column=index % 2, sticky="nsew", padx=(0 if index % 2 == 0 else 5, 5 if index % 2 == 0 else 0), pady=5)

            top = tk.Frame(card, bg=self.palette["PANEL_2"])
            top.pack(fill="x", padx=10, pady=(10, 5))

            icon_wrap = tk.Frame(
                top,
                bg=self.palette["ICON_BG"],
                highlightthickness=1,
                highlightbackground=self._mix(accent, self.palette["BORDER"], 0.35),
                width=42,
                height=42,
            )
            icon_wrap.pack(side="left", padx=(0, 9))
            icon_wrap.pack_propagate(False)
            game_img = self._load_game_card_icon(game.get("id"), size=24)
            if game_img:
                icon = tk.Label(icon_wrap, image=game_img, bg=self.palette["ICON_BG"], bd=0)
                icon.image = game_img
            else:
                fallback_text = str(game.get("icon") or "?")
                if len(fallback_text) > 2:
                    fallback_text = fallback_text[:2]
                icon = tk.Label(icon_wrap, text=fallback_text, bg=self.palette["ICON_BG"], fg=accent, font=("Segoe UI Black", 10, "bold"), bd=0)
            icon.pack(expand=True)

            labels = tk.Frame(top, bg=self.palette["PANEL_2"])
            labels.pack(side="left", fill="x", expand=True)
            tk.Label(labels, text=str(game.get("name")), bg=self.palette["PANEL_2"], fg=self.palette["TEXT"], font=("Segoe UI Semibold", 10, "bold")).pack(anchor="w")
            state_text = "ÇALIŞIYOR" if game.get("running") else ("BULUNDU" if found else "BULUNAMADI")
            tk.Label(labels, text=state_text, bg=self.palette["PANEL_2"], fg=self.palette["GREEN"] if found else self.palette["RED"], font=("Segoe UI", 8, "bold")).pack(anchor="w")
            tk.Label(card, text=str(game.get("path") or "Kurulum yolu bulunamadı"), bg=self.palette["PANEL_2"], fg=self.palette["MUTED"], font=("Consolas", 7), wraplength=320, justify="left").pack(anchor="w", fill="x", padx=10, pady=(0, 7))

            actions = tk.Frame(card, bg=self.palette["PANEL_2"])
            actions.pack(fill="x", padx=10, pady=(0, 10))
            select_btn = tk.Label(actions, text="T-BOOSTER İÇİN SEÇ", bg=self.palette["GLASS"], fg=accent, cursor="hand2" if found else "arrow", font=("Segoe UI Semibold", 8, "bold"), padx=8, pady=6, highlightthickness=1, highlightbackground=accent)
            select_btn.pack(side="left", fill="x", expand=True, padx=(0, 4))
            open_btn = tk.Label(actions, text="AÇ", bg=self.palette["GLASS"], fg=self.palette["GREEN"] if found else self.palette["MUTED"], cursor="hand2" if found else "arrow", font=("Segoe UI Semibold", 8, "bold"), padx=8, pady=6, highlightthickness=1, highlightbackground=self.palette["BORDER"])
            open_btn.pack(side="left")
            if found:
                select_btn.bind("<Button-1>", lambda _e, item=game: self._select_detected_game(item))
                open_btn.bind("<Button-1>", lambda _e, item=game: self._open_detected_game(item))

    def _render_system_checks(self, checks):
        body = self.system_check_body
        if not self._clear_dynamic_body(body):
            return
        if not checks:
            tk.Label(body, text="Tek tuş sistem kontrolü henüz çalıştırılmadı.", bg=self.palette["PANEL"], fg=self.palette["MUTED"], font=("Segoe UI", 9), pady=10).pack(fill="x")
            return
        colors = {"good": self.palette["GREEN"], "warning": self.palette["GOLD"], "bad": self.palette["RED"], "unknown": self.palette["MUTED"]}
        symbols = {"good": "✓", "warning": "!", "bad": "✕", "unknown": "?"}
        bad_count = sum(1 for item in checks if item.get("level") == "bad")
        warning_count = sum(1 for item in checks if item.get("level") == "warning")
        summary_color = self.palette["RED"] if bad_count else (self.palette["GOLD"] if warning_count else self.palette["GREEN"])
        tk.Label(body, text=f"SONUÇ: {bad_count} KRİTİK • {warning_count} UYARI • {len(checks) - bad_count - warning_count} NORMAL/BİLGİ", bg=self.palette["GLASS"], fg=summary_color, font=("Segoe UI Semibold", 10, "bold"), padx=12, pady=9).pack(fill="x", pady=(0, 7))
        for item in checks:
            level = str(item.get("level") or "unknown")
            color = colors.get(level, self.palette["MUTED"])
            row = tk.Frame(body, bg=self.palette["PANEL_2"], highlightbackground=color, highlightthickness=1)
            row.pack(fill="x", pady=4)
            tk.Label(row, text=symbols.get(level, "?"), bg=self.palette["PANEL_2"], fg=color, font=("Segoe UI Black", 13, "bold"), width=3).pack(side="left", padx=(7, 2), pady=9)
            holder = tk.Frame(row, bg=self.palette["PANEL_2"])
            holder.pack(side="left", fill="x", expand=True, padx=(0, 10), pady=8)
            tk.Label(holder, text=str(item.get("title") or "Kontrol"), bg=self.palette["PANEL_2"], fg=self.palette["TEXT"], font=("Segoe UI Semibold", 9, "bold")).pack(anchor="w")
            tk.Label(holder, text=str(item.get("detail") or ""), bg=self.palette["PANEL_2"], fg=self.palette["MUTED"], font=("Segoe UI", 8), wraplength=790, justify="left").pack(anchor="w", pady=(2, 0))

