    def refresh_disk_info(self):
        self.disk_info_status_var.set("T-Booster Disk Info SMART verilerini yeniden okuyor…")
        self.status_var.set("Disk SMART / NVMe sağlık bilgileri yenileniyor…")
        self._start_hardware_probe()

    def _disk_health_color(self, disk):
        status = str(disk.get("health_status") or "").casefold()
        if "sorun" in status or "bad" in status:
            return self.palette["RED"]
        if "uyarı" in status or "warning" in status:
            return self.palette["GOLD"]
        if "sağlıklı" in status or "healthy" in status or "good" in status:
            return self.palette["GREEN"]
        return self.palette["MUTED"]

    def _render_disk_info(self, disks):
        self.disk_info_last = list(disks or [])
        body = self.disk_info_body
        if body is None or not body.winfo_exists():
            return
        for child in body.winfo_children():
            child.destroy()
        if not disks:
            self.disk_info_status_var.set("Disk SMART bilgisi okunamadı veya desteklenmiyor.")
            tk.Label(
                body,
                text="Disk bulunamadı ya da sürücü SMART verisini Windows'a açmıyor.",
                bg=self.palette["PANEL"],
                fg=self.palette["MUTED"],
                font=("Segoe UI", 10),
                pady=24,
            ).pack(fill="x")
            return

        self.disk_info_status_var.set(f"{len(disks)} fiziksel disk algılandı — gerçek sağlık kaynağı kartlarda yazıyor.")
        for position, disk in enumerate(disks, start=1):
            accent = self._disk_health_color(disk)
            card = tk.Frame(
                body,
                bg=self.palette["PANEL_2"],
                highlightbackground=accent,
                highlightthickness=1,
            )
            card.pack(fill="x", pady=7)
            top = tk.Frame(card, bg=self.palette["PANEL_2"])
            top.pack(fill="x", padx=12, pady=(10, 6))
            model = str(disk.get("model") or f"Disk {position}")
            tk.Label(
                top,
                text=f"DİSK {disk.get('index') if disk.get('index') is not None else position}  •  {model}",
                bg=self.palette["PANEL_2"],
                fg=self.palette["TEXT"],
                font=("Segoe UI Semibold", 11, "bold"),
                anchor="w",
            ).pack(side="left", fill="x", expand=True)
            tk.Label(
                top,
                text=str(disk.get("health_source") or "SMART kaynağı bilinmiyor"),
                bg=self.palette["PANEL_2"],
                fg=self.palette["MUTED"],
                font=("Segoe UI", 8),
            ).pack(side="right")

            content = tk.Frame(card, bg=self.palette["PANEL_2"])
            content.pack(fill="both", expand=True, padx=12, pady=(0, 12))
            badge = tk.Frame(
                content,
                bg=self.palette["SURFACE"],
                width=142,
                highlightbackground=accent,
                highlightthickness=1,
            )
            badge.pack(side="left", fill="y", padx=(0, 10))
            badge.pack_propagate(False)
            health = disk.get("health_percent")
            health_text = f"%{int(health)}" if health is not None else "SMART"
            tk.Label(
                badge,
                text=health_text,
                bg=self.palette["SURFACE"],
                fg=accent,
                font=("Segoe UI Black", 22, "bold"),
            ).pack(pady=(16, 1))
            tk.Label(
                badge,
                text=str(disk.get("health_status") or "Bilinmiyor"),
                bg=self.palette["SURFACE"],
                fg=self.palette["TEXT"],
                font=("Segoe UI Semibold", 10, "bold"),
            ).pack()
            temp = disk.get("temperature")
            tk.Label(
                badge,
                text=(f"{temp}°C" if temp is not None else "— °C"),
                bg=self.palette["SURFACE"],
                fg=self.palette["ACCENT_2"],
                font=("Segoe UI Semibold", 11),
            ).pack(pady=(8, 4))
            tk.Label(
                badge,
                text="Gerçek kalan ömür" if health is not None else "Tahmini yüzde gösterilmez",
                bg=self.palette["SURFACE"],
                fg=self.palette["MUTED"],
                font=("Segoe UI", 7),
                wraplength=120,
                justify="center",
            ).pack(pady=(0, 10))

            detail_holder = tk.Frame(content, bg=self.palette["PANEL_2"])
            detail_holder.pack(side="left", fill="both", expand=True)
            detail_holder.grid_rowconfigure(0, weight=1)
            detail_holder.grid_columnconfigure(0, weight=1)
            detail_text = tk.Text(
                detail_holder,
                height=12,
                wrap="none",
                bg=self.palette["SURFACE"],
                fg=self.palette["TEXT"],
                insertbackground=self.palette["TEXT"],
                font=("Consolas", 9),
                relief="flat",
                bd=0,
                padx=10,
                pady=8,
                cursor="arrow",
            )
            xscroll = ttk.Scrollbar(detail_holder, orient="horizontal", command=detail_text.xview)
            yscroll = ttk.Scrollbar(detail_holder, orient="vertical", command=detail_text.yview)
            detail_text.configure(xscrollcommand=xscroll.set, yscrollcommand=yscroll.set)
            detail_text.grid(row=0, column=0, sticky="nsew")
            yscroll.grid(row=0, column=1, sticky="ns")
            xscroll.grid(row=1, column=0, sticky="ew")
            detail_text.insert("1.0", "\n".join(str(line) for line in (disk.get("summary_lines") or [])))
            detail_text.configure(state="disabled")

        self._refresh_sidebar_layout()

    def _hero_action(self, parent, title, subtitle, accent, command):
        base_bg = self.palette["GLASS"]
        hover_bg = self._mix(accent, base_bg, 0.90)
        card = tk.Frame(parent, bg=base_bg, highlightbackground=self._mix(accent, self.palette["BORDER"], 0.38), highlightthickness=1, cursor="hand2")
        card.pack(fill="x", pady=4)
        tk.Frame(card, bg=accent, width=4).pack(side="left", fill="y")
        row = tk.Frame(card, bg=base_bg)
        row.pack(side="left", fill="both", expand=True, padx=10, pady=8)

        brand_image = None
        upper_title = title.upper()
        if "NVIDIA" in upper_title:
            brand_image = self._load_nvidia_icon()
        elif "AMD" in upper_title:
            brand_image = self._load_amd_icon()

        widgets = [card, row]
        if brand_image is not None:
            icon = tk.Label(row, image=brand_image, bg=base_bg, width=34, height=34, bd=0)
            icon.image = brand_image
        else:
            icon = tk.Label(row, text=title.split()[0], bg=self._mix(accent, base_bg, 0.68), fg=accent, font=("Segoe UI Emoji", 12), width=2, pady=4)
        icon.pack(side="left", padx=(0, 9))
        widgets.append(icon)

        texts = tk.Frame(row, bg=base_bg)
        texts.pack(side="left", fill="x", expand=True)
        widgets.append(texts)
        title_label = tk.Label(texts, text=title, bg=base_bg, fg=self.palette["TEXT"], font=("Segoe UI Semibold", 9, "bold"), anchor="w", justify="left")
        title_label.pack(fill="x")
        sub_label = tk.Label(texts, text=subtitle, bg=base_bg, fg=self.palette["MUTED"], font=("Segoe UI", 7), wraplength=430, justify="left", anchor="w")
        sub_label.pack(fill="x", pady=(2, 0))
        widgets.extend([title_label, sub_label])
        arrow = tk.Label(row, text="→", bg=base_bg, fg=accent, font=("Segoe UI", 13, "bold"))
        arrow.pack(side="right", padx=(6, 0))
        widgets.append(arrow)

        def paint(hover=False):
            bg = hover_bg if hover else base_bg
            card.configure(bg=bg, highlightbackground=accent if hover else self._mix(accent, self.palette["BORDER"], 0.38))
            for widget in widgets[1:]:
                try:
                    widget.configure(bg=bg)
                except Exception:
                    pass
        self._bind_recursive(card, command)
        for widget in widgets:
            widget.bind("<Enter>", lambda _e: paint(True), add="+")
            widget.bind("<Leave>", lambda _e: paint(False), add="+")
        return card

    def _toggle_row(self, parent, title, description, key, accent):
        variable = self.option_vars[key]
        row = tk.Frame(parent, bg=self.palette["PANEL_2"], highlightbackground=self.palette["BORDER"], highlightthickness=1, cursor="hand2")
        row.pack(fill="x", pady=4)
        meta = tk.Frame(row, bg=self.palette["PANEL_2"])
        meta.pack(side="left", fill="x", expand=True, padx=12, pady=10)
        tk.Label(meta, text=title, bg=self.palette["PANEL_2"], fg=self.palette["TEXT"], font=("Segoe UI", 10, "bold")).pack(anchor="w")
        tk.Label(meta, text=description, bg=self.palette["PANEL_2"], fg=self.palette["MUTED"], font=("Segoe UI", 8), wraplength=610, justify="left").pack(anchor="w", pady=(2, 0))
        def maybe_warn_display_tweak():
            if variable.get() and key in {"fullscreen_opt_off", "mpo_off"}:
                messagebox.showwarning(
                    APP_NAME,
                    "Bu ayar bazı oyunlarda Alt-Tab yaparken kısa süreli siyah ekrana sebep olabilir.\n\n"
                    "Sorun yaşarsan Oyun Modu panelindeki 'ALT-TAB SİYAH EKRANI ONAR' düğmesi ile geri döndürebilirsin.",
                )
        toggle = AnimatedToggle(row, variable, accent, self.palette["SURFACE"], self.palette["BORDER"], command=maybe_warn_display_tweak)
        toggle.pack(side="right", padx=14)
        self._bind_recursive(meta, lambda: (variable.set(not variable.get()), maybe_warn_display_tweak()))
        return row

