    def _tb_init_state(self):
        if getattr(self, "_tb_ready", False):
            return
        self._tb_ready = True
        self.tb_health_result = None
        self.tb_health_busy = False
        self.tb_temp_busy = False
        self.tb_temp_last_bytes = None
        self.tb_dns_busy = False
        self.tb_large_busy = False
        self.tb_large_cancel = threading.Event()
        self.tb_proc_busy = False
        self.tb_ring_canvas = None
        self.tb_health_items_body = None
        self.tb_temp_vars = {target["key"]: tk.BooleanVar(value=True) for target in tbf.temp_targets()}
        self.tb_recycle_var = tk.BooleanVar(value=False)
        self.tb_health_status_var = tk.StringVar(value="Puan hesaplanıyor…")
        self.tb_temp_status_var = tk.StringVar(value="Taramak için TARA'ya bas — yalnızca 1 günden eski dosyalar silinir.")
        self.tb_dns_status_var = tk.StringVar(value="DNS hız testi hazır.")
        self.tb_large_status_var = tk.StringVar(value="Bir klasör seç ve taramayı başlat (yalnızca listeler, hiçbir şey silmez).")
        self.tb_proc_status_var = tk.StringVar(value="Yenile'ye basarak RAM'i en çok kullanan uygulamaları listele.")
        self.tb_large_path_var = tk.StringVar(value=str(Path.home()))
        self.tb_large_min_var = tk.StringVar(value="100 MB")
        self.tb_trees = {}

    def _tb_tree(self, parent, key, columns, height):
        frame = tk.Frame(parent, bg=self.palette["PANEL"], highlightbackground=self._mix(self.palette["ACCENT"], self.palette["BORDER"], 0.6), highlightthickness=1)
        tree = ttk.Treeview(frame, columns=[c[0] for c in columns], show="headings", height=height, style="Neon.Treeview")
        for col_key, title, width, anchor in columns:
            tree.heading(col_key, text=title, anchor=anchor)
            tree.column(col_key, width=width, anchor=anchor, stretch=(col_key == columns[-1][0]))
        scroll = ttk.Scrollbar(frame, orient="vertical", command=tree.yview)
        tree.configure(yscrollcommand=scroll.set)
        tree.pack(side="left", fill="both", expand=True)
        scroll.pack(side="right", fill="y")
        tree.tag_configure("good", foreground=self.palette["GREEN"])
        tree.tag_configure("warn", foreground=self.palette["GOLD"])
        tree.tag_configure("bad", foreground=self.palette["RED"])
        tree.tag_configure("dim", foreground=self.palette["MUTED"])
        self.tb_trees[key] = tree
        return frame, tree

    def _tb_button_row(self, parent, buttons):
        row = tk.Frame(parent, bg=self.palette["PANEL"])
        row.pack(fill="x", pady=(6, 0))
        for text, command, color in buttons:
            cell = tk.Frame(row, bg=self.palette["PANEL"])
            cell.pack(side="left", fill="x", expand=True, padx=4)
            self._mini_action(cell, text, command, color)
        return row

    def _tb_toggle_row(self, parent, title, note, variable, accent):
        row = tk.Frame(parent, bg=self.palette["PANEL_2"], highlightbackground=self.palette["BORDER"], highlightthickness=1, cursor="hand2")
        row.pack(fill="x", pady=3)
        meta = tk.Frame(row, bg=self.palette["PANEL_2"])
        meta.pack(side="left", fill="x", expand=True, padx=12, pady=7)
        tk.Label(meta, text=title, bg=self.palette["PANEL_2"], fg=self.palette["TEXT"], font=("Segoe UI", 10, "bold")).pack(anchor="w")
        tk.Label(meta, text=note, bg=self.palette["PANEL_2"], fg=self.palette["MUTED"], font=("Segoe UI", 8)).pack(anchor="w")
        AnimatedToggle(row, variable, accent, self.palette["SURFACE"], self.palette["BORDER"]).pack(side="right", padx=12)
        self._bind_recursive(meta, lambda: variable.set(not variable.get()))
        return row

