    # ---------------------------------------------------------------- olay yönlendirici
    def _tb_on_event(self, name, payload):
        try:
            if name == "health":
                self.tb_health_busy = False
                self.tb_health_result = payload
                self._tb_render_health()
            elif name == "temp_scan":
                self.tb_temp_busy = False
                self.tb_temp_last_bytes = payload["total"]
                parts = " • ".join(f"{label}: {tbf.fmt_size(size)}" for label, size in payload["rows"])
                self.tb_temp_status_var.set(f"Temizlenebilir alan: {tbf.fmt_size(payload['total'])} ({payload['count']} dosya)  —  {parts}")
            elif name == "temp_clean":
                self.tb_temp_busy = False
                text = f"Temizlendi: {tbf.fmt_size(payload['freed'])} boşaldı • {payload['deleted']} dosya silindi • {payload['skipped']} dosya kullanımda/yeni olduğu için atlandı"
                if payload.get("recycle") is True:
                    text += " • geri dönüşüm kutusu boşaltıldı"
                self.tb_temp_status_var.set(text)
                self.status_var.set("Geçici dosya temizliği tamamlandı.")
                self._append_log(text)
                self.tb_start_health()
            elif name == "dns_flush":
                self.tb_dns_status_var.set(("✓ DNS önbelleği temizlendi." if payload["ok"] else "DNS önbelleği temizlenemedi: ") + ("" if payload["ok"] else str(payload["text"])))
                self._append_log(self.tb_dns_status_var.get())
            elif name == "dns_progress":
                self.tb_dns_status_var.set(f"DNS testi: {payload['done']}/{payload['total']} — {payload['name']}")
            elif name == "dns_done":
                self.tb_dns_busy = False
                tree = self.tb_trees.get("dns")
                if tree is not None and tree.winfo_exists():
                    tree.delete(*tree.get_children())
                    best = None
                    for row in payload["rows"]:
                        avg = f"{row['avg_ms']:.0f} ms" if row["avg_ms"] is not None else "yanıt yok"
                        low = f"{row['min_ms']:.0f} ms" if row["min_ms"] is not None else "—"
                        tag = ("good",) if best is None and row["avg_ms"] is not None else (() if row["avg_ms"] is not None else ("bad",))
                        if best is None and row["avg_ms"] is not None:
                            best = row
                        tree.insert("", "end", values=(row["name"], row["ip"], avg, low, f"{row['ok']}/{row['total']}", "★" if tag == ("good",) else ""), tags=tag)
                ping = payload.get("ping")
                ping_text = f" • İnternet gecikmesi: {ping:.0f} ms" if ping is not None else ""
                if payload["rows"] and payload["rows"][0]["avg_ms"] is not None:
                    top = payload["rows"][0]
                    self.tb_dns_status_var.set(f"En hızlı DNS: {top['name']} ({top['ip']}) ort. {top['avg_ms']:.0f} ms{ping_text}. Değiştirmek için 'AĞ AYARLARINI AÇ'.")
                else:
                    self.tb_dns_status_var.set("Hiçbir DNS sunucusundan yanıt alınamadı (güvenlik duvarı veya bağlantı sorunu olabilir)." + ping_text)
                self._append_log(self.tb_dns_status_var.get())
            elif name == "large_progress":
                self.tb_large_status_var.set(f"Taranıyor… {payload['scanned']} dosya bakıldı")
            elif name == "large_done":
                self.tb_large_busy = False
                tree = self.tb_trees.get("large")
                if tree is not None and tree.winfo_exists():
                    tree.delete(*tree.get_children())
                    for item in payload["files"]:
                        tree.insert("", "end", values=(tbf.fmt_size(item["size"]), item["path"]))
                extra = " (süre doldu, tarama yarıda kesildi)" if payload["timed_out"] else ""
                self.tb_large_status_var.set(f"{len(payload['files'])} büyük dosya bulundu • {payload['scanned']} dosya tarandı{extra}. Çift tıklayarak konumunu aç.")
                self._append_log(self.tb_large_status_var.get())
            elif name == "proc_list":
                self.tb_proc_busy = False
                tree = self.tb_trees.get("proc")
                if tree is not None and tree.winfo_exists():
                    tree.delete(*tree.get_children())
                    for row in payload["rows"]:
                        tag = ("dim",) if row["protected"] else (("warn",) if row["hint"] else ())
                        hint = "Korumalı sistem işlemi" if row["protected"] else row["hint"]
                        tree.insert("", "end", iid=str(row["pid"]), values=(row["name"], row["pid"], f"{row['mem_mb']:.0f} MB", hint), tags=tag)
                self.tb_proc_status_var.set(f"{len(payload['rows'])} işlem listelendi. Sarı satırlar oyun öncesi kapatılabilecek uygulamalardır.")
            elif name == "proc_ended":
                self.tb_proc_status_var.set(payload["text"])
                self._append_log(payload["text"])
                self.tb_refresh_processes()
            elif name == "error":
                for flag in ("tb_health_busy", "tb_temp_busy", "tb_dns_busy", "tb_large_busy", "tb_proc_busy"):
                    setattr(self, flag, False)
                self.status_var.set("Araç Kutusu hatası: " + str(payload))
                self._append_log("ARAÇ KUTUSU HATASI: " + str(payload))
        except tk.TclError:
            pass

    # ---------------------------------------------------------------- 1) sağlık puanı
    def _tb_health_color(self, score):
        return "GREEN" if score >= 75 else ("GOLD" if score >= 55 else "RED")

    def _tb_draw_ring(self, score):
        canvas = self.tb_ring_canvas
        if canvas is None or not canvas.winfo_exists():
            return
        canvas.delete("all")
        color_key = self._tb_health_color(score)
        if _aa_ready():
            photo = ImageTk.PhotoImage(_render_score_ring(score, 150, _tk_rgb(canvas, self.palette[color_key]), _tk_rgb(canvas, self.palette["BORDER"])))
            self._tb_ring_photo = photo
            canvas.create_image(75, 75, image=photo)
        else:
            canvas.create_oval(22, 22, 128, 128, outline=self.palette["BORDER"], width=10)
            canvas.create_arc(22, 22, 128, 128, start=90, extent=-3.6 * score, style="arc", outline=self.palette[color_key], width=10)
        canvas.create_text(75, 70, text=str(score), fill=self.palette["TEXT"], font=("Segoe UI Black", 30, "bold"))
        canvas.create_text(75, 103, text="/ 100", fill=self.palette["MUTED"], font=("Segoe UI", 9))

    def _tb_render_health(self):
        result = self.tb_health_result
        body = self.tb_health_items_body
        if body is None or not body.winfo_exists():
            return
        for child in body.winfo_children():
            child.destroy()
        if not result:
            self._tb_draw_ring(0)
            return
        self._tb_draw_ring(result["score"])
        self.tb_health_status_var.set(f"{result['grade']} — {result['score']}/100")
        colors = {"ok": self.palette["GREEN"], "warning": self.palette["GOLD"], "bad": self.palette["RED"]}
        for item in result["items"]:
            row = tk.Frame(body, bg=self.palette["PANEL"])
            row.pack(fill="x", pady=1)
            tk.Label(row, text="●", bg=self.palette["PANEL"], fg=colors[item["level"]], font=("Segoe UI", 9)).pack(side="left")
            text = f"{item['title']}: {item['detail']}"
            if item["tip"]:
                text += f"  —  {item['tip']}"
            tk.Label(row, text=text, bg=self.palette["PANEL"], fg=self.palette["TEXT"] if item["level"] == "ok" else colors[item["level"]],
                     font=("Segoe UI", 9), anchor="w", justify="left", wraplength=620).pack(side="left", padx=(6, 0))

    def tb_start_health(self):
        if self.tb_health_busy:
            return
        self.tb_health_busy = True
        self.tb_health_status_var.set("Puan hesaplanıyor…")
        threading.Thread(target=self._tb_health_worker, daemon=True).start()

    def _tb_health_worker(self):
        try:
            temp_bytes = self.tb_temp_last_bytes
            if temp_bytes is None:
                paths = [p for target in tbf.temp_targets() for p in target["paths"]]
                temp_bytes, _count = tbf.scan_paths(paths, 1.0)
            self.events.put(("tb_feature", "health", tbf.compute_health(tbf.collect_health_inputs(temp_bytes))))
        except Exception as exc:
            core.log_line(traceback.format_exc())
            self.events.put(("tb_feature", "error", exc))

    # ---------------------------------------------------------------- 2) geçici dosyalar
    def _tb_selected_temp_targets(self):
        return [t for t in tbf.temp_targets() if self.tb_temp_vars[t["key"]].get()]

    def tb_scan_temp(self):
        if self.tb_temp_busy:
            return
        targets = self._tb_selected_temp_targets()
        if not targets:
            self.tb_temp_status_var.set("Önce en az bir temizlik hedefi aç.")
            return
        self.tb_temp_busy = True
        self.tb_temp_status_var.set("Taranıyor…")

        def worker():
            try:
                rows, total, count = [], 0, 0
                for target in targets:
                    size, files = tbf.scan_paths(target["paths"], 1.0)
                    rows.append((target["label"], size))
                    total += size
                    count += files
                self.events.put(("tb_feature", "temp_scan", {"rows": rows, "total": total, "count": count}))
            except Exception as exc:
                self.events.put(("tb_feature", "error", exc))
        threading.Thread(target=worker, daemon=True).start()

    def tb_clean_temp(self):
        if self.tb_temp_busy:
            return
        targets = self._tb_selected_temp_targets()
        recycle = self.tb_recycle_var.get()
        if not targets and not recycle:
            self.tb_temp_status_var.set("Önce en az bir temizlik hedefi aç.")
            return
        message = "Seçili klasörlerdeki 1 günden eski geçici dosyalar silinecek."
        if recycle:
            message += "\n\nGeri dönüşüm kutusu da kalıcı olarak boşaltılacak."
        if not messagebox.askyesno(APP_NAME, message + "\n\nDevam edilsin mi?", parent=self.root):
            return
        self.tb_temp_busy = True
        self.tb_temp_status_var.set("Temizleniyor…")

        def worker():
            try:
                freed = deleted = skipped = 0
                for target in targets:
                    result = tbf.clean_paths(target["paths"], 1.0)
                    freed += result["freed"]
                    deleted += result["deleted"]
                    skipped += result["skipped"]
                recycled = tbf.empty_recycle_bin() if recycle else None
                self.tb_temp_last_bytes = None
                self.events.put(("tb_feature", "temp_clean", {"freed": freed, "deleted": deleted, "skipped": skipped, "recycle": recycled}))
            except Exception as exc:
                self.events.put(("tb_feature", "error", exc))
        threading.Thread(target=worker, daemon=True).start()

    # ---------------------------------------------------------------- 3) DNS & ağ
    def tb_flush_dns(self):
        def worker():
            ok, text = tbf.flush_dns()
            self.events.put(("tb_feature", "dns_flush", {"ok": ok, "text": text}))
        self.tb_dns_status_var.set("DNS önbelleği temizleniyor…")
        threading.Thread(target=worker, daemon=True).start()

    def tb_start_dns_test(self):
        if self.tb_dns_busy:
            return
        self.tb_dns_busy = True
        self.tb_dns_status_var.set("DNS sunucuları test ediliyor…")

        def worker():
            try:
                def progress(done, total, name):
                    self.events.put(("tb_feature", "dns_progress", {"done": done, "total": total, "name": name}))
                rows = tbf.dns_benchmark(progress=progress)
                ping_values = tbf.tcp_latency("1.1.1.1", 443, 3, 2.0)
                ping = (sum(ping_values) / len(ping_values)) if ping_values else None
                self.events.put(("tb_feature", "dns_done", {"rows": rows, "ping": ping}))
            except Exception as exc:
                self.events.put(("tb_feature", "error", exc))
        threading.Thread(target=worker, daemon=True).start()

    def tb_open_network_settings(self):
        try:
            if hasattr(os, "startfile"):
                os.startfile("ms-settings:network")
            self.status_var.set("Windows ağ ayarları açıldı.")
        except Exception as exc:
            messagebox.showerror(APP_NAME, f"Ağ ayarları açılamadı:\n{exc}", parent=self.root)

    # ---------------------------------------------------------------- 4) büyük dosyalar
    def tb_pick_large_folder(self):
        chosen = filedialog.askdirectory(parent=self.root, initialdir=self.tb_large_path_var.get() or str(Path.home()))
        if chosen:
            self.tb_large_path_var.set(chosen)

    def tb_start_large_scan(self):
        if self.tb_large_busy:
            return
        root_path = self.tb_large_path_var.get().strip()
        if not root_path or not Path(root_path).is_dir():
            self.tb_large_status_var.set("Geçerli bir klasör seç.")
            return
        text = self.tb_large_min_var.get().split()
        min_bytes = int(float(text[0]) * (1024 ** 3 if text[1] == "GB" else 1024 ** 2))
        self.tb_large_busy = True
        self.tb_large_cancel.clear()
        self.tb_large_status_var.set("Taranıyor…")

        def worker():
            try:
                result = tbf.find_large_files(
                    root_path, 30, min_bytes, cancel=self.tb_large_cancel.is_set,
                    progress=lambda scanned, _cur: self.events.put(("tb_feature", "large_progress", {"scanned": scanned})),
                )
                self.events.put(("tb_feature", "large_done", result))
            except Exception as exc:
                self.events.put(("tb_feature", "error", exc))
        threading.Thread(target=worker, daemon=True).start()

    def tb_stop_large_scan(self):
        self.tb_large_cancel.set()
        self.tb_large_status_var.set("Tarama durduruluyor…")

    def tb_open_selected_large(self):
        tree = self.tb_trees.get("large")
        if tree is None or not tree.selection():
            self.tb_large_status_var.set("Önce listeden bir dosya seç.")
            return
        path = tree.item(tree.selection()[0], "values")[1]
        try:
            if os.name == "nt":
                subprocess.Popen(f'explorer.exe /select,"{path}"')
            else:
                subprocess.Popen(["xdg-open", str(Path(path).parent)])
        except Exception as exc:
            messagebox.showerror(APP_NAME, f"Konum açılamadı:\n{exc}", parent=self.root)

    # ---------------------------------------------------------------- 5) uygulama avcısı
    def tb_refresh_processes(self):
        if self.tb_proc_busy:
            return
        self.tb_proc_busy = True
        self.tb_proc_status_var.set("İşlemler okunuyor…")

        def worker():
            try:
                self.events.put(("tb_feature", "proc_list", {"rows": tbf.list_processes(40)}))
            except Exception as exc:
                self.events.put(("tb_feature", "error", exc))
        threading.Thread(target=worker, daemon=True).start()

    def tb_end_selected_process(self):
        tree = self.tb_trees.get("proc")
        if tree is None or not tree.selection():
            self.tb_proc_status_var.set("Önce listeden bir uygulama seç.")
            return
        name, pid = tree.item(tree.selection()[0], "values")[0:2]
        if tbf.is_protected_process(str(name), int(pid)):
            self.tb_proc_status_var.set(f"{name} korumalı bir sistem işlemi; kapatılamaz.")
            return
        if not messagebox.askyesno(APP_NAME, f"{name} (PID {pid}) kapatılsın mı?\n\nKaydedilmemiş veriler kaybolabilir.", parent=self.root):
            return

        def worker():
            ok, text = tbf.end_process(int(pid), str(name))
            self.events.put(("tb_feature", "proc_ended", {"text": (f"✓ {name} kapatıldı." if ok else f"{name} kapatılamadı: {text}")}))
        threading.Thread(target=worker, daemon=True).start()

    def _scroll_page(self, title, subtitle, page_key):
        page = self._page()
        outer, holder = self._glass_card(page, title, subtitle)
        outer.pack(fill="both", expand=True)

        canvas = tk.Canvas(holder, bg=self.palette["PANEL"], highlightthickness=0, bd=0)
        scrollbar = ttk.Scrollbar(holder, orient="vertical", command=canvas.yview)
        body = tk.Frame(canvas, bg=self.palette["PANEL"])
        window_id = canvas.create_window((0, 0), window=body, anchor="nw")

        def update_scrollregion(_event=None):
            canvas.configure(scrollregion=canvas.bbox("all"))

        def resize_inner(event):
            canvas.itemconfigure(window_id, width=max(1, event.width - 2))
            update_scrollregion()

        body.bind("<Configure>", update_scrollregion)
        canvas.bind("<Configure>", resize_inner)
        canvas.configure(yscrollcommand=scrollbar.set, yscrollincrement=34)
