    def _open_official_driver_url(self, url, description):
        from urllib.parse import urlparse
        try:
            host = (urlparse(url).hostname or "").casefold()
            allowed = any(host == domain or host.endswith("." + domain) for domain in OFFICIAL_DRIVER_HOSTS)
            if not allowed:
                raise RuntimeError("Resmî alan adı doğrulanamadı.")
            opened = webbrowser.open(url, new=2)
            if not opened and hasattr(os, "startfile"):
                os.startfile(url)
            self._append_log(f"{description} açıldı: {url}")
            return True
        except Exception as exc:
            messagebox.showerror(APP_NAME, f"{description} açılamadı:\n{exc}")
            return False

    def _copy_board_model(self):
        model = str(self.driver_data.get("board_model") or "").strip()
        if not model or model.casefold() == "bilinmiyor":
            return
        try:
            self.root.clipboard_clear(); self.root.clipboard_append(model); self.root.update()
            self._append_log(f"Anakart modeli panoya kopyalandı: {model}")
        except Exception as exc:
            core.log_line(f"Anakart modeli panoya kopyalanamadı: {exc}")

    def open_gpu_driver_pages(self):
        if not self.driver_data.get("ok"):
            messagebox.showwarning(APP_NAME, "Donanım algılama tamamlanmadı. Önce yeniden algılamayı çalıştır.")
            return
        vendors = self.driver_data.get("gpu_vendors") or []
        if not vendors:
            messagebox.showwarning(APP_NAME, "NVIDIA, AMD veya Intel ekran kartı üreticisi algılanamadı.")
            return
        labels = {"nvidia": "NVIDIA resmî sürücü sayfası", "amd": "AMD resmî otomatik algılama / sürücü sayfası", "intel": "Intel Driver & Support Assistant"}
        for index, vendor in enumerate(vendors):
            url = GPU_DRIVER_URLS.get(vendor)
            if not url:
                continue
            if index == 0:
                self._open_official_driver_url(url, labels[vendor])
            else:
                self.root.after(900 * index, lambda target=url, label=labels[vendor]: self._open_official_driver_url(target, label))
        self.driver_vars["status"].set(f"{len(vendors)} ekran kartı üreticisinin resmî sayfası açılıyor.")

    def open_motherboard_driver_page(self):
        if not self.driver_data.get("ok"):
            messagebox.showwarning(APP_NAME, "Anakart bilgisi henüz algılanmadı.")
            return
        url = motherboard_support_url(self.driver_data)
        manufacturer = self.driver_data.get("board_manufacturer", "Bilinmiyor")
        model = self.driver_data.get("board_model", "Bilinmiyor")
        if not url:
            messagebox.showwarning(APP_NAME, f"Anakart üreticisi için güvenli resmî destek adresi eşleştirilemedi.\n\nÜretici: {manufacturer}\nModel: {model}")
            return
        self._copy_board_model()
        if self._open_official_driver_url(url, f"{manufacturer} resmî anakart destek sayfası"):
            self.driver_vars["status"].set(f"{manufacturer} destek sayfası açıldı. Model panoya kopyalandı: {model}")

    def open_all_driver_pages(self):
        if not self.driver_data.get("ok"):
            messagebox.showwarning(APP_NAME, "Donanım algılama tamamlanmadı.")
            return
        self.open_gpu_driver_pages()
        self.root.after(1400, self.open_motherboard_driver_page)

