        dialog = tk.Toplevel(self.root)
        dialog.title("T-Booster Başlangıç Uygulamaları Asistanı")
        dialog.geometry("1120x680")
        dialog.minsize(900, 560)
        dialog.configure(bg=self.palette["BG"])
