        tk.Label(dialog, text="BAŞLANGIÇ UYGULAMALARI ASİSTANI", bg=self.palette["BG"], fg=self.palette["ACCENT"], font=("Segoe UI Black", 17)).pack(anchor="w", padx=18, pady=(16, 4))
        tk.Label(dialog, text="Seçili girdileri devre dışı bırakabilirsin. Korumalı sistem/sürücü girdileri T-Booster tarafından kapatılmaz. Dosyalar silinmez.", bg=self.palette["BG"], fg=self.palette["MUTED"], font=("Segoe UI", 9), wraplength=1060, justify="left").pack(anchor="w", padx=18, pady=(0, 10))

        holder = tk.Frame(dialog, bg=self.palette["PANEL"]); holder.pack(fill="both", expand=True, padx=18, pady=6)
        columns = ("status", "name", "scope", "kind", "impact", "publisher", "advice")
