        widths = {"status":80,"name":180,"scope":130,"kind":120,"impact":85,"publisher":110,"advice":300}
        labels = {"status":"Durum","name":"Program","scope":"Kapsam","kind":"Kaynak","impact":"Etki","publisher":"Yayıncı","advice":"T-Booster Önerisi"}
        for col in columns:
            tree.heading(col, text=labels[col]); tree.column(col, width=widths[col], anchor="w")
        scroll_y = ttk.Scrollbar(holder, orient="vertical", command=tree.yview)
        scroll_x = ttk.Scrollbar(holder, orient="horizontal", command=tree.xview)
        tree.configure(yscrollcommand=scroll_y.set, xscrollcommand=scroll_x.set)
        tree.grid(row=0,column=0,sticky="nsew"); scroll_y.grid(row=0,column=1,sticky="ns"); scroll_x.grid(row=1,column=0,sticky="ew")
        holder.grid_rowconfigure(0,weight=1); holder.grid_columnconfigure(0,weight=1)
        item_map = {}

        def refresh():
            tree.delete(*tree.get_children()); item_map.clear()
            try:
                entries = v50tools.list_startup_entries()
            except Exception as exc:
                messagebox.showerror(APP_NAME, "Başlangıç girdileri okunamadı:\n\n" + str(exc), parent=dialog); return
            for index, item in enumerate(entries):
                iid = "s" + str(index)
                item_map[iid] = item
                status = "Açık" if item.get("enabled") else "Kapalı"
                if item.get("protected"):
                    status += " / Korumalı"
                tree.insert("", "end", iid=iid, values=(status,item.get("name"),item.get("scope"),item.get("kind"),item.get("impact"),item.get("publisher"),item.get("recommendation")))
            self.startup_status_var.set(f"{len(entries)} başlangıç girdisi listelendi")

        def selected_ids():
            return [item_map[iid]["id"] for iid in tree.selection() if iid in item_map]

        def disable_selected():
            ids = selected_ids()
            if not ids: messagebox.showinfo(APP_NAME,"Önce bir veya daha fazla açık girdi seç.",parent=dialog); return
            if not messagebox.askyesno(APP_NAME,"Seçili başlangıç girdileri yedeklenerek devre dışı bırakılsın mı?",parent=dialog): return
            try:
                result=v50tools.disable_startup_entries(ids)
                messagebox.showinfo(APP_NAME,f"Kapatılan: {len(result['changed'])}\nAtlanan/korumalı: {len(result['skipped'])}",parent=dialog)
                refresh()
            except Exception as exc: messagebox.showerror(APP_NAME,str(exc),parent=dialog)

        def restore_selected():
            ids=selected_ids()
            if not ids: messagebox.showinfo(APP_NAME,"Geri açılacak kapalı girdileri seç.",parent=dialog); return
            try:
                result=v50tools.restore_startup_entries(ids)
                messagebox.showinfo(APP_NAME,f"Geri açılan: {len(result['changed'])}\nBaşarısız: {len(result['failed'])}",parent=dialog)
                refresh()
            except Exception as exc: messagebox.showerror(APP_NAME,str(exc),parent=dialog)

        actions=tk.Frame(dialog,bg=self.palette["BG"]); actions.pack(fill="x",padx=18,pady=(6,14))
        for label,cmd,color in (("YENİLE",refresh,self.palette["ACCENT"]),("SEÇİLİLERİ KAPAT",disable_selected,self.palette["RED"]),("SEÇİLİLERİ GERİ AÇ",restore_selected,self.palette["GREEN"]),("KAPAT",dialog.destroy,self.palette["MUTED"])):
            tk.Button(actions,text=label,command=cmd,bg=color,fg="white",activebackground=color,activeforeground="white",relief="flat",font=("Segoe UI Semibold",9,"bold"),padx=14,pady=8,cursor="hand2").pack(side="left",padx=(0,8))
        refresh()

