    def start_restore_point(self):
        if self.busy:
            return
        if not messagebox.askyesno(APP_NAME,"Windows geri yükleme noktası oluşturulsun mu? Windows aynı 24 saat içinde ikinci noktayı reddedebilir."):
            return
        self._set_busy(True); self.backup_center_status_var.set("Geri yükleme noktası oluşturuluyor…")
        threading.Thread(target=self._restore_point_worker,daemon=True).start()

    def _restore_point_worker(self):
        try: self.events.put(("restore_point_done",v50tools.create_restore_point("T-Booster Öncesi")))
        except Exception as exc: self.events.put(("restore_point_error",str(exc)))

    def _backup_status_text(self):
        rows=v50tools.backup_status(self._backup_paths())
        lines=[]
        for row in rows:
            state="HAZIR" if row["exists"] else "YOK"
            lines.append(f"[{state}] {row['label']}\n  {row['path']}\n  Güncelleme: {row['modified']} • Boyut: {row['size']} bayt")
        return "\n\n".join(lines)

