        dialog=tk.Toplevel(self.root); dialog.title("T-Booster Güvenli İşlem ve Yedek Merkezi"); dialog.geometry("900x650"); dialog.configure(bg=self.palette["BG"]); dialog.transient(self.root)
        tk.Label(dialog,text="GÜVENLİ İŞLEM VE YEDEK MERKEZİ",bg=self.palette["BG"],fg=self.palette["GREEN"],font=("Segoe UI Black",17)).pack(anchor="w",padx=18,pady=(16,5))
        text_box=tk.Text(dialog,bg=self.palette["PANEL"],fg=self.palette["TEXT"],insertbackground=self.palette["TEXT"],font=("Consolas",9),wrap="word",relief="flat",padx=12,pady=10)
        text_box.pack(fill="both",expand=True,padx=18,pady=8); self.backup_text_widget=text_box
        def refresh():
            text_box.configure(state="normal"); text_box.delete("1.0","end"); text_box.insert("1.0",self._backup_status_text()); text_box.configure(state="disabled")
