        actions=tk.Frame(dialog,bg=self.palette["BG"]); actions.pack(fill="x",padx=18,pady=(4,14))
        for label,cmd,color in (("YENİLE",refresh,self.palette["ACCENT"]),("GERİ YÜKLEME NOKTASI",self.start_restore_point,self.palette["GREEN"]),("RAPORU DIŞA AKTAR",export,self.palette["ACCENT_2"]),("YEDEK KLASÖRÜ",open_folder,self.palette["GOLD"]),("SİSTEM GERİ YÜKLEME",system_restore,self.palette["RED"]),("KAPAT",dialog.destroy,self.palette["MUTED"])):
            tk.Button(actions,text=label,command=cmd,bg=color,fg="white",activebackground=color,activeforeground="white",relief="flat",font=("Segoe UI Semibold",8,"bold"),padx=10,pady=8,cursor="hand2").pack(side="left",padx=(0,6))
        refresh()

