    def select_game_exe(self):
        path = filedialog.askopenfilename(
            title="Oyun EXE dosyasını seç",
            filetypes=(("Windows uygulaması", "*.exe"), ("Tüm dosyalar", "*.*")),
        )
        if path:
            self.game_exe_var.set(path)
            self.game_status_var.set("Oyun seçildi: " + Path(path).name)

    def start_game_session(self):
        if self.game_session_active:
            messagebox.showinfo(APP_NAME, "Bir T-Booster oyun oturumu zaten çalışıyor.")
            return
        exe = self.game_exe_var.get().strip()
        if not Path(exe).is_file() or Path(exe).suffix.lower() != ".exe":
            messagebox.showwarning(APP_NAME, "Önce geçerli bir oyun EXE dosyası seç.")
            return
        warning = (
            "T-Booster oyun oturumu başlatılsın mı?\n\n"
            "• T-Booster yüksek performans güç planı etkinleşir\n"
            "• Timer 0.5 ms talep edilir; desteklenmezse 1 ms kullanılır\n"
            "• Oyun Normal Üstü veya Yüksek öncelikle açılır\n"
            "• Oyun işleminin güç kısıtlaması kapatılır\n"
            "• Oyun kapanınca önceki güç planı ve timer geri döner"
        )
        if not messagebox.askyesno(APP_NAME, warning):
            return
        self.game_session_active = True
        self.game_status_var.set("Oyun oturumu hazırlanıyor…")
        threading.Thread(target=self._game_session_worker, args=(exe,), daemon=True).start()

    def _game_session_worker(self, exe):
        try:
            previous = v49tools.active_power_plan_guid()
            core.apply_power_plan(core.BackupStore(), self._callback)
            priority = "high" if self.game_priority_var.get() == "Yüksek" else "above_normal"
            self.events.put(("game_started", Path(exe).name))
            result = v49tools.run_game_session(exe, priority, self._callback, previous)
            self.events.put(("game_finished", result))
        except Exception as exc:
            v49tools.stop_active_session()
            self.events.put(("error_game", str(exc)))

    def start_network_apply(self):
        if self.busy: return
        if not messagebox.askyesno(APP_NAME, "Etkin fiziksel Ethernet adaptöründe RSS ve güç yönetimi ayarları yedeklenip performans profili uygulansın mı? Ağ bağlantısı kısa süre kesilebilir."):
            return
        self._set_busy(True)
        threading.Thread(target=self._network_apply_worker, daemon=True).start()

    def _network_apply_worker(self):
        try:
            result = v49tools.apply_ethernet_low_latency(bool(self.network_interrupt_var.get()), self._callback)
            self.events.put(("network_done", result))
        except Exception as exc:
            self.events.put(("error", "Ethernet profili uygulanamadı:\n" + str(exc)))

    def start_network_restore(self):
        if self.busy: return
        if not v49tools.ethernet_backup_exists():
            messagebox.showinfo(APP_NAME, "Geri alınacak Ethernet yedeği bulunamadı.")
            return
        if not messagebox.askyesno(APP_NAME, "Ethernet adaptörü yedeklenen ayarlarına döndürülsün mü? Ağ bağlantısı kısa süre kesilebilir."):
            return
        self._set_busy(True)
        threading.Thread(target=self._network_restore_worker, daemon=True).start()

    def _network_restore_worker(self):
        try:
            self.events.put(("network_restored", v49tools.restore_ethernet(self._callback)))
        except Exception as exc:
            self.events.put(("error", "Ethernet geri alınamadı:\n" + str(exc)))

    def start_nvidia_game_profile(self):
        if self.busy: return
        exe_path = self.game_exe_var.get().strip()
        if not Path(exe_path).is_file() or Path(exe_path).suffix.lower() != ".exe":
            messagebox.showwarning(APP_NAME, "Önce Oyun EXE Seç düğmesiyle oyun dosyasını seç.")
            return
        detected = self.driver_data if self.driver_data.get("ok") else driver_hardware_info()
        if "nvidia" not in (detected.get("gpu_vendors") or []):
            messagebox.showwarning(APP_NAME, "Bu sistemde NVIDIA ekran kartı algılanmadı.")
            return
        if not messagebox.askyesno(APP_NAME, "Seçilen oyuna özel NVIDIA performans profili uygulansın mı? Mevcut özelleştirilmiş NVIDIA profilleri önce yedeklenir."):
            return
        self._set_busy(True)
        threading.Thread(target=self._nvidia_game_profile_worker, args=(exe_path,), daemon=True).start()

    def _nvidia_game_profile_worker(self, exe_path):
        try:
            exe = ensure_nvidia_profile_inspector(self._callback, allow_download=True)
            state = _load_nvidia_state()
            if not state.get("active") or not NVIDIA_BACKUP_FILE.exists():
                _export_nvidia_backup(exe, self._callback)
            result = v49tools.import_nvidia_game_profile(str(exe), exe_path, self._callback)
            state.update({
                "active": True,
                "backup": str(NVIDIA_BACKUP_FILE),
                "game_profile": result,
                "applied_at": dt.datetime.now().isoformat(timespec="seconds"),
            })
            _save_nvidia_state(state)
            self.events.put(("nvidia_game_done", result))
        except Exception as exc:
            core.log_line(traceback.format_exc())
            self.events.put(("error", "NVIDIA oyun profili uygulanamadı:\n" + str(exc)))

    def start_bios_probe(self):
        if self.busy: return
        self._set_busy(True)
        self.bios_status_var.set("BIOS ve Re-Size BAR bilgileri okunuyor…")
        threading.Thread(target=self._bios_probe_worker, daemon=True).start()

    def _bios_probe_worker(self):
        try:
            self.events.put(("bios_done", v49tools.bios_rebar_probe()))
        except Exception as exc:
            self.events.put(("error", "BIOS analizi tamamlanamadı:\n" + str(exc)))

    def _select_recommended_200_tweaks(self):
        count = 0
        for tweak in TB_200_TWEAKS:
            value = (
                bool(tweak.get("recommended"))
                and tweak["key"] not in TB_PROTECTED_COMMUNICATION_KEYS
            )
            variable = self.option_vars.get(tweak["key"])
            if variable is not None:
                variable.set(value)
                count += int(value)
        self.status_var.set(f"200 Tweak Paketi: {count} önerilen seçenek işaretlendi")

    def _clear_200_tweaks(self):
        for tweak in TB_200_TWEAKS:
            variable = self.option_vars.get(tweak["key"])
            if variable is not None:
                variable.set(False)
        self.status_var.set("200 Tweak Paketi seçimleri temizlendi")

