    def _animate_metric_bars(self):
        for key, target in self.metric_targets.items():
            current = self.metric_values.get(key, 0.0); current += (target - current) * 0.18
            if abs(target-current) < 0.15: current = target
            self.metric_values[key] = current
            progress = self.metric_progress.get(key)
            if progress is not None and progress.winfo_exists(): progress["value"] = max(0, min(100, current))
        self.root.after(40, self._animate_metric_bars)

