    def apply_ultra_preset(self):
        excluded = {
            "lock_screen_off", "numlock_on",
            "sticky_keys_off", "aero_shake_off", "end_task_menu",
            "tray_icons_always", "full_path_title", "device_metadata_off",
            "fast_startup_off", "driver_updates_off", "store_auto_updates_off",
            "ntfs_memoryusage_2", "windows_spotlight_off", "t100_lock_slideshow_off",
            *TB_PROTECTED_COMMUNICATION_KEYS,
        }
        for key in self.option_vars:
            self.option_vars[key].set(key not in excluded)
        for key in ULTRA_V53_OPTION_KEYS:
            variable = self.option_vars.get(key)
            if variable is not None:
                variable.set(True)
        selected = sum(1 for variable in self.option_vars.values() if variable.get())
        self.status_var.set(f"Ultra MAX hazır: {selected} modül/seçenek işaretlendi")

