    def _capture_wallpaper_state(self):
        state = {
            "path": "",
            "style": None,
            "tile": None,
            "slideshow": None,
        }
        try:
            buffer = ctypes.create_unicode_buffer(32768)
            ok = ctypes.windll.user32.SystemParametersInfoW(
                0x0073,
                len(buffer),
                buffer,
                0,
            )
            if ok:
                state["path"] = buffer.value
        except Exception as exc:
            core.log_line(f"Duvar kağıdı yolu okunamadı: {exc}")

        try:
            with winreg.OpenKey(
                winreg.HKEY_CURRENT_USER,
                r"Control Panel\Desktop",
                0,
                winreg.KEY_READ,
            ) as key:
                for name, field in (("Wallpaper", "path"), ("WallpaperStyle", "style"), ("TileWallpaper", "tile")):
                    try:
                        value, _kind = winreg.QueryValueEx(key, name)
                        if name != "Wallpaper" or not state["path"]:
                            state[field] = str(value)
                    except OSError:
                        pass
        except Exception as exc:
            core.log_line(f"Duvar kağıdı Registry bilgisi okunamadı: {exc}")

        try:
            with winreg.OpenKey(
                winreg.HKEY_CURRENT_USER,
                r"Software\Microsoft\Windows\CurrentVersion\Explorer\Wallpapers",
                0,
                winreg.KEY_READ,
            ) as key:
                value, _kind = winreg.QueryValueEx(key, "BackgroundType")
                state["slideshow"] = int(value)
        except Exception:
            pass
        return state

    def _restore_wallpaper_state(self, state):
        if not isinstance(state, dict):
            return False
        path = str(state.get("path") or "").strip()
        if not path:
            fallback = Path(os.environ.get("APPDATA", "")) / "Microsoft" / "Windows" / "Themes" / "TranscodedWallpaper"
            if fallback.is_file():
                path = str(fallback)
                state["path"] = path
        try:
            with winreg.CreateKeyEx(
                winreg.HKEY_CURRENT_USER,
                r"Control Panel\Desktop",
                0,
                winreg.KEY_SET_VALUE,
            ) as key:
                if path:
                    winreg.SetValueEx(key, "Wallpaper", 0, winreg.REG_SZ, path)
                if state.get("style") is not None:
                    winreg.SetValueEx(key, "WallpaperStyle", 0, winreg.REG_SZ, str(state["style"]))
                if state.get("tile") is not None:
                    winreg.SetValueEx(key, "TileWallpaper", 0, winreg.REG_SZ, str(state["tile"]))
        except Exception as exc:
            core.log_line(f"Duvar kağıdı Registry bilgisi geri yüklenemedi: {exc}")

        restored = False
        if path:
            try:
                restored = bool(
                    ctypes.windll.user32.SystemParametersInfoW(
                        0x0014,
                        0,
                        path,
                        0x0001 | 0x0002,
                    )
                )
            except Exception as exc:
                core.log_line(f"Duvar kağıdı yeniden uygulanamadı: {exc}")
        try:
            core.run_command(
                ["rundll32.exe", "user32.dll,UpdatePerUserSystemParameters"],
                timeout=20,
            )
        except Exception:
            pass
        return restored or not path

    def start_repair_wallpaper(self):
        if self.busy:
            return
        state = self._capture_wallpaper_state()
        path = str(state.get("path") or "").strip()
        if not path:
            messagebox.showinfo(
                APP_NAME,
                "Windows'ta kayıtlı bir duvar kağıdı yolu bulunamadı. Windows Ayarları > Kişiselleştirme > Arka Plan bölümünden bir görsel seçebilirsin.",
            )
            return
        ok = self._restore_wallpaper_state(state)
        if ok:
            self.status_var.set("Duvar kağıdı yeniden uygulandı ve korumaya alındı")
            self._append_log("Duvar kağıdı yeniden uygulandı: " + path)
            messagebox.showinfo(APP_NAME, "Duvar kağıdı yeniden uygulandı. Ultra Boost artık bu ayara dokunmayacak.")
        else:
            messagebox.showerror(APP_NAME, "Duvar kağıdı yeniden uygulanamadı. Dosyanın hâlâ mevcut olduğunu kontrol et.")

